SELECT '9d91dbee-ce87-5bb3-8acc-db303f434298','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9d91dbee-ce87-5bb3-8acc-db303f434298' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '018f961d-1a6f-5c82-a99d-7a9fcf599fd7','Cryptographic hash','A cryptographic hash is a function that maps data of arbitrary size to a fixed-length value (the digest) such that it is deterministic, fast to compute, infeasible to invert, and collision-resistant, so any change to the input produces a substantially different output. Standardized functions such as the SHA-2 family (for example SHA-256) are specified in NIST FIPS 180-4.','A cryptographic hash turns any file into a short fixed-length code. The same file always gives the same code. Even a tiny change gives a very different code. And you cannot work backward from the code to the file. Archives use it to check that files stay unchanged.','It provides a compact, tamper-evident fingerprint of data, so archives can detect corruption or alteration by comparing a file''s current digest with a trusted stored value.','An archivist computes a SHA-256 digest for each preservation file, stores it in a manifest, and re-computes it during audits to confirm the bits have not changed.','Fixity & Integrity',ARRAY['Checksum manifest','Checksum collision','Fixity','Content migration','Content preservation']::text[],ARRAY['Using a cryptographic hash for confidentiality; hashing does not encrypt or hide data, it only fingerprints it.','Relying on MD5 or SHA-1 for integrity-critical work despite their known collision weaknesses.','Storing the reference digest in a way that can be altered together with the file, defeating tamper detection.']::text[],ARRAY['Generating SHA-256 digests for a batch of digitized audio masters.','Verifying a downloaded preservation package against a published hash.','Choosing SHA-256 over MD5 when specifying a repository''s fixity policy.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='018f961d-1a6f-5c82-a99d-7a9fcf599fd7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cryptographic hash'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '018f961d-1a6f-5c82-a99d-7a9fcf599fd7','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='018f961d-1a6f-5c82-a99d-7a9fcf599fd7' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '412f58f0-2111-5f6f-94be-b5f33d9603bf','Cut groove','A cut groove is a sound groove inscribed directly into a disc by the stylus of a recording lathe at the moment of recording, as on lacquer (acetate) instantaneous discs, rather than moulded from a stamper during mass replication. Because each cut disc is a unique, unreplicated original, its groove is comparatively soft and vulnerable, and the disc is typically the only carrier of that recording.','A cut groove is carved straight into a disc by a recording machine as the sound happens. Pressed records copy their grooves from a metal stamper instead. So a cut disc is a one-off original, not a copy. Its groove is softer and easy to damage, and it may be the only copy that exists.','The distinction matters because cut (instantaneous) discs are unique originals with no press master to fall back on, so they rank high for careful handling and prompt preservation transfer.','A transfer engineer identifies a lacquer disc''s cut groove, treats it as an irreplaceable original, cleans and plays it with correct stylus geometry, and prioritizes digitizing it before the coating degrades.','Grooved Media',ARRAY['Concentric cracking','Concentric runout','Content migration','Content preservation','Cylinder bore deformation']::text[],ARRAY['UNSAFE: Handling a degrading lacquer (cut) disc without care for its cellulose-nitrate coating, which is chemically unstable and flammable; store cool and dry and follow hazardous-material guidance.','Assuming a cut lacquer disc is as durable as a pressed vinyl or shellac record.','Playing a unique cut disc repeatedly before making a preservation transfer, wearing the fragile groove.']::text[],ARRAY['Identifying instantaneous lacquer discs in a radio archive as unique originals.','Prioritizing cut discs for urgent transfer over mass-produced pressings.','Selecting stylus and cleaning methods suited to a soft cut lacquer groove.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='412f58f0-2111-5f6f-94be-b5f33d9603bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cut groove'),'[^a-z0-9]','','g'));
