INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '349473ee-93ec-5bfd-9b0e-81571da52923','Cylinder bore deformation','Cylinder bore deformation is a change in the internal cylindrical opening (bore) of a phonograph cylinder away from its original round, uniform dimension, caused by core swelling, celluloid shrinkage, warping, or physical stress. Because the bore must seat concentrically on the playback mandrel, deformation makes the cylinder fit too tightly or unevenly, risking cracking and unstable rotation during playback.','A cylinder record has a hollow inside that slides onto a rod on the player, called the mandrel. Over time that opening can change shape or size. Then the cylinder no longer fits the rod snugly and evenly. Forcing it on can crack it, and a loose fit makes playback wobble.','Recognizing bore deformation lets an operator judge whether a cylinder can seat safely on the mandrel, preventing cracking and the pitch instability that an uneven fit causes.','Before playback a technician test-fits the cylinder gently, checks for a swollen or out-of-round bore, and stops rather than forcing a deformed cylinder that could crack on the mandrel.','Media Degradation',ARRAY['Core swelling','Concentric runout','Concentric cracking','Content migration','Content preservation']::text[],ARRAY['UNSAFE: Forcing a deformed cylinder onto the mandrel, which can shatter brittle celluloid and produce sharp fragments; stop and reassess rather than push.','Assuming a poor mandrel fit is normal, when it signals bore deformation that risks cracking.','Ignoring uneven rotation or wobble on playback that a deformed bore can cause.']::text[],ARRAY['Test-fitting an old cylinder on the mandrel and finding it too tight to seat safely.','Diagnosing playback wobble traced to an out-of-round bore.','Deciding a deformed cylinder needs specialist mounting or touchless capture instead of standard playback.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='349473ee-93ec-5bfd-9b0e-81571da52923' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cylinder bore deformation'),'[^a-z0-9]','','g'));
