SELECT '349473ee-93ec-5bfd-9b0e-81571da52923','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='349473ee-93ec-5bfd-9b0e-81571da52923' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5a835c35-bc01-52d2-88f4-27b044f1c987','Cylinder eccentricity','The condition in which a phonograph cylinder rotates about an axis that does not coincide with the centre of its recorded groove surface, so the groove is offset from the axis of rotation. As the mandrel turns, the stylus is driven cyclically toward and away from the centre once per revolution, producing speed and pitch variation (wow) and tracking errors on playback.','A cylinder record should spin around its exact centre. Eccentricity means it spins slightly off-centre. Each turn, the needle gets pushed in and out. This makes the pitch waver, and the needle can jump the groove.','Recognising eccentricity explains a common source of wow and mistracking on cylinder playback, and tells the transfer engineer the fault is mechanical rather than in the recording itself.','An archivist transferring cylinders uses eccentric adjusters on the playback machine to re-centre the reading surface and reduce the once-per-revolution wow caused by off-centre mounting.','Carrier Degradation',ARRAY['Cylinder ovalization','Wax cylinder','Wow and flutter','Tracking error','Mandrel']::text[],ARRAY['Confusing eccentricity (the groove offset from the rotation axis) with ovalization (the cylinder itself being out of round); the mechanical causes differ.','Assuming the wow is in the original recording when it is actually caused by off-centre mounting on the mandrel.','UNSAFE: Forcing a shrunken or fragile cylinder onto an oversized mandrel to ''centre'' it, which can split the brittle carrier; use a correctly sized or adjustable mandrel and handle with gloves.']::text[],ARRAY['Hearing a once-per-revolution pitch wobble on an Edison wax cylinder and tracing it to off-centre mounting.','Adjusting the eccentric correction on a cylinder playback machine before an archival transfer.','Deciding whether wow is in the carrier or the recording during quality control of a digitised cylinder.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5a835c35-bc01-52d2-88f4-27b044f1c987' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cylinder eccentricity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5a835c35-bc01-52d2-88f4-27b044f1c987','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5a835c35-bc01-52d2-88f4-27b044f1c987' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9705d6f-7418-581b-94a3-fe476780548e','Cylinder ovalization','A form of cylinder deformation in which the originally circular cross-section of a phonograph cylinder becomes oval (out of round), typically through warping of wax or shrinkage of a celluloid layer over its core. The non-circular profile makes the stylus rise and fall as the cylinder turns, giving cyclic speed variation (wow), amplitude modulation, and loss of groove contact.','A cylinder record should be perfectly round. Ovalization means it has warped into an oval shape. As it spins, the needle rides up and down over the bulge. This makes the sound waver and the needle can skip.','Naming ovalization separates a physical shape defect of the carrier from electrical or recording faults, guiding the archivist toward mechanical playback correction rather than blaming the transfer chain.','Faced with an out-of-round cylinder, a transfer engineer may lower playback speed and use eccentric adjusters so the stylus can follow the groove despite the oval profile.','Carrier Degradation',ARRAY['Cylinder eccentricity','Wax cylinder','Warping','Wow and flutter','Groove']::text[],ARRAY['Confusing ovalization (the cylinder out of round) with eccentricity (the groove offset from the rotation axis).','UNSAFE: Applying heat or force to ''re-round'' a warped cylinder, which can shatter brittle celluloid or melt wax and destroy an irreplaceable recording; leave reshaping to trained conservators.','Assuming a cylinder that looks intact will play evenly, without first checking for out-of-round distortion.']::text[],ARRAY['Diagnosing cyclic wow on a celluloid cylinder whose layer has shrunk over its plaster core.','Choosing a slower, monitored playback speed to transfer a badly ovalized cylinder.','Documenting an out-of-round wax cylinder''s condition before attempting playback.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9705d6f-7418-581b-94a3-fe476780548e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cylinder ovalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b9705d6f-7418-581b-94a3-fe476780548e','f2442389-2379-4010-8b5a-6835773b85c7',true
