INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31e93077-aab5-5781-b41a-3f27e7d36818','Dictabelt','A proprietary dictation recording medium introduced by the Dictaphone Corporation in the late 1940s, consisting of a thin flexible plastic belt onto which audio was recorded by embossing (ploughing) a groove into the soft plastic with a stylus rather than cutting it. The belt was fitted over rotating mandrels on a Dictabelt machine for recording and playback, and was used mainly for business, medical, legal, and police dictation into the 1960s.','A Dictabelt was a thin plastic belt used to record speech. A blunt needle pressed a groove into the soft plastic instead of carving it out. Offices, hospitals, and police stations used them to record dictation. They were common from the late 1940s to the 1960s.','It provided a cheap, compact way to capture spoken dictation for a typist to replay and transcribe later, before magnetic tape and cassettes took over that role.','An archivist who finds Dictabelts must locate or adapt a compatible belt machine, because the embossed groove and belt format cannot be played on standard disc or tape equipment.','Obsolete Media',ARRAY['Dictation belt','Embossed groove','Direct-cut disc','Instantaneous recording','Groove']::text[],ARRAY['Trying to play a Dictabelt on a normal record player; the embossed groove and belt shape need a compatible Dictabelt machine.','UNSAFE: Flattening or unrolling a creased, brittle Dictabelt by force, which can crack the plastic and destroy the only copy; relax and rehouse it under conservation guidance.','Assuming all dictation belts are Dictabelts, when other brands, such as the SoundScriber Memobelt, used different machines.']::text[],ARRAY['Cataloguing a box of legal or police dictation belts found in an archive.','Sourcing a working Dictaphone belt machine to transfer 1950s office recordings.','Rehousing creased Dictabelts around acid-free supports to reduce further damage.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31e93077-aab5-5781-b41a-3f27e7d36818' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dictabelt'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
