INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd2fb3b16-d729-500e-aaf7-95a5713b75e7','Dictation belt','A generic term for the family of belt-format sound recording media used for office and institutional dictation from the late 1940s through the 1960s, in which a groove carrying speech was embossed into a thin flexible plastic loop. Proprietary examples include the Dictaphone Dictabelt and the SoundScriber Memobelt, each requiring its own dedicated machine.','A dictation belt is a loop of thin plastic used to record speech for typing up later. A needle pressed a groove into the soft plastic. Different brands, like the Dictabelt, needed their own machines. Offices and hospitals used them before cassette tapes.','The belt format let people record and store spoken notes cheaply and compactly, so a typist could replay and transcribe them afterwards.','When an archivist encounters unlabelled dictation belts, identifying the brand and its matching machine is the first step, because the formats are not interchangeable.','Obsolete Media',ARRAY['Dictabelt','Embossed groove','Direct-cut disc','Instantaneous recording','Obsolete media']::text[],ARRAY['Assuming any dictation belt will fit any belt machine, when brands like the Dictabelt and Memobelt are incompatible.','Storing belts flat under weight, which creases the plastic and damages the embossed groove.','UNSAFE: Forcing a stiff, aged belt onto a machine''s mandrels, which can tear or crack it and lose the recording; assess flexibility and rehouse before playback.']::text[],ARRAY['Sorting mixed dictation belts by brand before finding compatible playback machines.','Transferring institutional dictation belts holding legal or medical records.','Explaining why a dictation belt needs different equipment from a phonograph disc.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d2fb3b16-d729-500e-aaf7-95a5713b75e7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dictation belt'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd2fb3b16-d729-500e-aaf7-95a5713b75e7','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d2fb3b16-d729-500e-aaf7-95a5713b75e7' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e06f914-d5ff-5e5a-958b-c4c0382b9fd4','Direct-cut disc','A disc recording whose groove is cut directly by a recording lathe at the moment of performance or transfer, producing a playable disc without any intermediate stamper or pressing stage. The category includes instantaneous (lacquer/acetate) discs cut in real time and audiophile ''direct-to-disc'' masters cut live from the mixing console, and each disc so made is normally unique.','A direct-cut disc is made by cutting the groove straight onto it as the sound happens. Instantaneous direct-cut discs have no stamper, so each one is usually unique. But audiophile direct-to-disc masters skip tape, yet can be pressed into many copies. Radio stations and studios used direct-cut discs to catch sound as it played.','Cutting directly to disc allowed immediate recording and playback without any processing stage, and later gave audiophiles a master with no intermediate tape in the signal path.','Because a direct-cut disc is often the only copy, an archivist handles it with special care and transfers it with a stylus and speed matched to the original cutting.','Grooved Media',ARRAY['Instantaneous recording','Lacquer disc','Embossed groove','Dictabelt','Groove']::text[],ARRAY['Treating a direct-cut disc as a mass-produced pressing, when it is usually a unique recording with no backup.','Assuming all direct-cut discs are durable vinyl, when many are fragile lacquer-on-metal instantaneous discs.','UNSAFE: Wet-cleaning a delaminating or exuding lacquer direct-cut disc without first checking for cracks or exudate, which can lift the coating and destroy the recording.']::text[],ARRAY['Transferring a unique radio broadcast preserved only on an instantaneous direct-cut disc.','Identifying an audiophile direct-to-disc master among ordinary commercial pressings.','Documenting that a direct-cut disc has no duplicate before it is played.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e06f914-d5ff-5e5a-958b-c4c0382b9fd4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Direct-cut disc'),'[^a-z0-9]','','g'));
