INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '76df765c-2ea3-5677-82b0-42cf316c82ef','Documented intervention','Any preservation or conservation action performed on an object or its signal that is fully recorded — noting what was done, why, by whom, when, and with what methods and materials — so the treatment is transparent, accountable, and can be understood or reversed later. In audiovisual preservation this record is captured as process history, or preservation metadata, alongside the reformatted content.','A documented intervention means writing down every change you make to an item you preserve. You record what you did, why, when, and how. This lets others see exactly what was altered. It keeps the work honest and, where possible, reversible.','Documentation makes preservation actions transparent and repeatable, protects the object''s authenticity, and lets future custodians judge and, if needed, undo what was done.','After cleaning a disc or de-noising a transfer, a technician logs the exact steps, tools, and settings in the preservation metadata so the intervention is on record.','Preservation Practice',ARRAY['Event metadata','Preservation metadata','Provenance','Reversibility','Authenticity']::text[],ARRAY['Performing a treatment but recording nothing, so later custodians cannot tell what is original and what was changed.','Documenting only the outcome, not the method and materials, which makes the intervention impossible to assess or reverse.','Assuming digital edits, such as filtering or de-clicking, need no record because the file ''looks'' clean.']::text[],ARRAY['Recording the solution and steps used to clean an exuding lacquer disc.','Logging de-click and de-noise settings applied during a digital restoration.','Noting the playback speed and stylus chosen for a cylinder transfer in the object''s metadata.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='76df765c-2ea3-5677-82b0-42cf316c82ef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Documented intervention'),'[^a-z0-9]','','g'));
