SELECT '76df765c-2ea3-5677-82b0-42cf316c82ef','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='76df765c-2ea3-5677-82b0-42cf316c82ef' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95700208-1f45-5867-9715-06cc36155a69','Embedded checksum','A checksum — a short, fixed-length value computed from a file''s data that changes if the data changes — that is stored inside the file or its wrapper itself, rather than in a separate sidecar file, manifest, or external database. Because the integrity value travels within the same file as the data, the file can be checked for corruption without relying on a matching record kept elsewhere.','A checksum is like a fingerprint worked out from a file. If even one bit changes, the fingerprint changes. An embedded checksum is stored inside the same file. So the file carries its own way to prove it has not been altered.','Embedding the checksum keeps a file''s integrity value bound to its data, so corruption can still be detected even if any external record of the checksum is lost.','During ingest or migration, a technician recalculates the file''s checksum and compares it with the value stored inside the file to confirm the data is unchanged.','Digital Preservation',ARRAY['Fixity','Checksum','MD5','Preservation metadata','Migration']::text[],ARRAY['Confusing an embedded checksum (inside the file) with a sidecar or manifest checksum stored in a separate file.','Assuming a matching checksum proves authenticity, when it only proves the bits are unchanged since the checksum was made.','Using a weak or outdated algorithm and treating it as proof against deliberate tampering rather than accidental corruption.']::text[],ARRAY['Verifying a preservation file on ingest by comparing its internal checksum against a fresh calculation.','Detecting silent bit corruption during a storage migration.','Choosing between an embedded checksum and an external manifest for a repository''s fixity strategy.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95700208-1f45-5867-9715-06cc36155a69' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Embedded checksum'),'[^a-z0-9]','','g'));
