INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e387ea31-fe23-54fb-b175-5f9bbc1b6599','Embossed groove','A sound-recording groove formed by pressing or ploughing a stylus into a soft surface so that material is displaced (embossed) rather than cut away as a chip. Embossing needs less force than engraving but yields a shallower, rougher groove wall, giving higher surface noise and lower fidelity; it was used for media such as Dictabelts and some low-cost instantaneous recordings.','An embossed groove is pushed into soft material instead of being carved out. The needle squashes a channel rather than slicing one. This is easier to do, but it leaves a rougher groove. So embossed recordings tend to be noisier than cut ones.','Embossing allowed cheap, immediate recording on soft media without the sharp cutting styli and chip removal that engraved discs need, at the cost of sound quality.','Recognising an embossed groove tells a transfer engineer to expect higher noise and to choose a stylus and tracking force suited to a shallow, displaced groove.','Grooved Media',ARRAY['Dictabelt','Dictation belt','Instantaneous recording','Groove','Lacquer disc']::text[],ARRAY['Confusing an embossed groove (material displaced) with an engraved or cut groove (material removed as a chip).','Using a standard cutting-style playback stylus that mistracks a shallow embossed groove.','Expecting engraved-disc fidelity from an embossed recording and blaming the transfer for the extra noise.']::text[],ARRAY['Selecting a stylus to play an embossed Dictabelt dictation recording.','Explaining why a home instantaneous recording sounds noisier than a pressed record.','Identifying whether a groove was cut or embossed when assessing a carrier.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e387ea31-fe23-54fb-b175-5f9bbc1b6599' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Embossed groove'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e387ea31-fe23-54fb-b175-5f9bbc1b6599','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e387ea31-fe23-54fb-b175-5f9bbc1b6599' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '893b90cf-404a-5464-a22a-086ff67a5218','Essence','In audiovisual and file-based media, essence is the actual programme content itself — the picture, sound, data, or timed-text bitstreams — as distinct from the metadata that describes it and the wrapper that packages it. Essence is what a viewer or listener ultimately experiences once it is decoded.','Essence is the real content of a media file, the actual sound or picture. It is not the labels or notes about the file, and not the container that holds it. If metadata is the label on a can, the essence is the food inside.','Separating essence from metadata and wrapper lets systems handle, store, and exchange the content on its own, independently of its packaging and descriptive data.','When repackaging an archival file, a technician can rewrap the same audio or video essence in a new container without re-encoding or altering the content itself.','AV File Structure',ARRAY['Essence container','Wrapper','Metadata','MXF','Transcoding']::text[],ARRAY['Confusing essence (the actual content) with metadata (data that describes the content).','Assuming rewrapping essence in a new container changes the content, when the essence bitstream can stay identical.','Treating the wrapper file format as the same thing as the essence codec inside it.']::text[],ARRAY['Rewrapping video essence from one container into another during a format migration.','Checking that a codec is supported before ingesting the essence it carries.','Explaining why the wrapper and the essence can be preserved as separate concerns.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='893b90cf-404a-5464-a22a-086ff67a5218' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Essence'),'[^a-z0-9]','','g'));
