SELECT '893b90cf-404a-5464-a22a-086ff67a5218','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='893b90cf-404a-5464-a22a-086ff67a5218' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '788731b7-3630-5811-888e-b158af47110f','Essence container','The part of a media file (wrapper) format that holds the essence — the actual audio, video, or data bitstreams — as opposed to the header metadata that describes them. In MXF (SMPTE ST 377), the Generic Container is the essence container: a sequence of content packages that interleave picture, sound, and data items with their stream metadata.','The essence container is the part of a media file that holds the real content. The rest of the file holds labels and structure. Think of a shipping crate: the container is the crate, and the essence is the goods packed inside it.','It gives the content bitstreams a standard place and structure inside a file, so different systems can reliably find and decode the picture, sound, and data.','When troubleshooting an MXF file, a technician separates header-metadata problems from essence-container problems to tell a labelling fault from a content fault.','AV File Structure',ARRAY['Essence','Wrapper','Metadata','MXF','Embedded checksum']::text[],ARRAY['Confusing the essence container (which holds the content) with the whole wrapper or with the descriptive metadata.','Assuming a valid wrapper means the essence inside is intact, when the container can hold corrupt or unsupported essence.','Treating the container format and the essence codec as one and the same choice.']::text[],ARRAY['Locating the Generic Container while inspecting the structure of an archival MXF file.','Deciding which essence container and codec to use for a preservation master.','Diagnosing whether a playback fault lies in the container or the essence.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='788731b7-3630-5811-888e-b158af47110f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Essence container'),'[^a-z0-9]','','g'));
