WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='788731b7-3630-5811-888e-b158af47110f' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '50f000a4-f202-528e-b7c1-4edf542cfd64','Event metadata','Metadata that records an action or occurrence affecting a digital object over its life — for example creation, ingest, fixity check, migration, or restoration — including what happened, when, which agent performed it, and the outcome. In the PREMIS preservation metadata model, the Event is one of the core entities, linking objects to the agents and actions that shaped them.','Event metadata is a record of things that happen to a file. It notes what was done, when, who did it, and how it turned out. For example: checked for damage on this date, passed. Together the records build a history you can trust.','It provides an auditable history of preservation actions, so custodians can prove authenticity, trace what was done, and troubleshoot problems.','A repository writes event metadata each time it ingests a file, runs a fixity check, or migrates a format, building a complete process history.','Preservation Metadata',ARRAY['Preservation metadata','Documented intervention','Fixity','Embedded checksum','Provenance']::text[],ARRAY['Recording only that an event happened, without the date, agent, or outcome that make it useful.','Confusing event metadata (what was done to the object) with descriptive metadata (what the object is about).','Assuming manual notes are enough, when preservation systems should log events consistently and automatically.']::text[],ARRAY['Logging a fixity-check result as an event in a repository''s preservation metadata.','Reviewing the event history to see every migration a file has undergone.','Proving chain of custody for a legal recording through its event records.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='50f000a4-f202-528e-b7c1-4edf542cfd64' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Event metadata'),'[^a-z0-9]','','g'));
