INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0ed5f58b-1473-52db-baba-2970be09af4d','Exudate removal','The controlled cleaning of exudate — waxy or crystalline deposits, chiefly palmitic and stearic acids, that migrate to the surface of degrading lacquer (acetate) discs as the castor-oil plasticizer breaks down, and analogous bloom on wax cylinders — from a carrier before playback or transfer. On lacquer discs a mild solution, such as dilute Tergitol with a little ammonium hydroxide, is used to break down the fatty-acid exudate without harming the nitrocellulose coating.','Old lacquer discs can sweat out a greasy white film called exudate. It sits on the surface and adds noise when you play the disc. Exudate removal means gently cleaning that film off first. A weak, disc-safe cleaner dissolves the greasy layer without hurting the disc.','Removing exudate restores clean stylus-to-groove contact so a transfer captures the recording with less noise, without dissolving or abrading the fragile carrier.','Before transferring an exuding lacquer disc, a technician inspects for cracks, protects the label, wipes away the fatty-acid bloom with an approved dilute solution, and dries it at once.','Conservation Treatment',ARRAY['Lacquer disc','Direct-cut disc','Instantaneous recording','Documented intervention','Wax cylinder']::text[],ARRAY['UNSAFE: Cleaning a cracked, flaking, or delaminating lacquer disc, which can lift the coating and permanently destroy the recording; inspect and reject damaged discs first.','UNSAFE: Using strong solvents, alcohol, or abrasive pads on lacquer or wax, which can dissolve or scratch the carrier; use only tested, media-safe dilute solutions and soft cloths.','Letting a hygroscopic lacquer disc soak in liquid instead of cleaning it briefly and drying it immediately.','Skipping documentation of what was cleaned and with what, leaving the intervention unrecorded.']::text[],ARRAY['Wiping palmitic-acid bloom from a broadcast lacquer disc before a stylus or optical transfer.','Deciding not to clean a delaminating acetate disc because wetting it would lift the coating.','Protecting a paper label while removing exudate from an instantaneous disc.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0ed5f58b-1473-52db-baba-2970be09af4d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Exudate removal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0ed5f58b-1473-52db-baba-2970be09af4d','f2442389-2379-4010-8b5a-6835773b85c7',true
