INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '90abb6d3-b395-5f3d-bba6-ac34a3060371','Fixity','In digital preservation, fixity is the property of a digital file or object being fixed and unchanged at the bit level over time. It is the documented assurance that stored data has not been altered, corrupted, or degraded since a known reference point, and it underpins the authenticity and integrity of preserved content.','Fixity means a digital file has stayed exactly the same, bit for bit. Nothing has been changed or damaged since you saved it. Think of it as proof the file is still whole.','It gives archivists a measurable way to prove that preserved files remain authentic and uncorrupted, so damage or tampering can be detected and repaired before the only good copy is lost.','A technician establishes fixity at ingest and rechecks it over time, using the result to confirm a file survived transfer, storage, and copying unchanged.','Digital Preservation',ARRAY['Fixity check','Fixity information','Checksum','Bit rot','Data integrity','Format migration']::text[],ARRAY['Assuming fixity guarantees a file is still usable, when it only proves the bits are unchanged, not that the format can still be opened.','Confusing fixity (the file is unchanged) with a backup (a second copy that may itself be corrupt).','Recording a checksum once and never re-checking it, so silent corruption goes unnoticed for years.']::text[],ARRAY['Confirming a master audio file is unchanged after moving it to a new storage system.','Proving the authenticity of a digitized recording used as legal evidence.','Detecting silent data corruption on an archival hard drive during a routine audit.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='90abb6d3-b395-5f3d-bba6-ac34a3060371' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fixity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '90abb6d3-b395-5f3d-bba6-ac34a3060371','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='90abb6d3-b395-5f3d-bba6-ac34a3060371' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '288fb616-e35f-5b51-994d-3f1967b0c501','Fixity check','A fixity check is the act of verifying a digital object''s fixity by generating a current checksum, hash, or other integrity value and comparing it against a previously stored reference value. A match confirms the data is unchanged; a mismatch signals corruption or alteration requiring investigation and repair from a verified copy.','A fixity check tests whether a file has changed. The computer makes a short code from the file and compares it to the code saved earlier. If the two codes differ, the file is damaged.','It detects corruption, accidental change, or tampering early, so a damaged file can be replaced from a known-good copy before every copy degrades.','An archivist runs scheduled fixity checks on stored files, then investigates and restores any file whose new checksum no longer matches its recorded value.','Digital Preservation',ARRAY['Fixity','Fixity information','Checksum','MD5','SHA-256','Data integrity']::text[],ARRAY['Running a fixity check but never acting on a mismatch, so detected corruption is never repaired.','Checking fixity so often that the extra reads wear the media or overload the system, or so rarely that damage spreads unnoticed.','Assuming a matching checksum proves the file is good, when the reference value itself may have been recorded from an already-corrupt file.']::text[],ARRAY['Comparing checksums before and after transferring files to confirm a clean copy.','Auditing an archive on a schedule to catch silent bit rot on stored media.','Validating a downloaded preservation package against its manifest of checksums.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='288fb616-e35f-5b51-994d-3f1967b0c501' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fixity check'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '288fb616-e35f-5b51-994d-3f1967b0c501','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='288fb616-e35f-5b51-994d-3f1967b0c501' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b7b195ce-6b71-590c-9129-430a1f610ea8','Fixity information','Fixity information is the preservation metadata that records the values and methods used to verify a digital object''s integrity — typically one or more checksums or message digests, the algorithm used (for example MD5 or SHA-256), and when they were generated. The PREMIS data dictionary defines it as information used to verify whether an object has been altered in an undocumented or unauthorized way.','Fixity information is the saved record used to check a file later. It stores the file''s short code and the method that made it. Without it, you cannot tell if the file changed.','It provides the trusted reference values a fixity check compares against, and documents the method so the check can be repeated reliably across systems and over time.','A technician stores fixity information in the object''s metadata, a database, or a BagIt manifest, then uses it as the baseline for every future fixity check.','Digital Preservation',ARRAY['Fixity','Fixity check','Checksum','PREMIS','Preservation metadata','BagIt']::text[],ARRAY['Storing fixity information in the same place as the file with no independent copy, so one failure can destroy both.','Recording the checksum but not the algorithm, leaving no reliable way to reproduce the value.','Treating fixity information as optional metadata rather than the essential baseline for proving integrity.']::text[],ARRAY['Writing checksums and their algorithm into a PREMIS metadata record at ingest.','Shipping a BagIt package whose manifest lists the fixity information for every file.','Consulting stored fixity information to decide which of several copies is authentic.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b7b195ce-6b71-590c-9129-430a1f610ea8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fixity information'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b7b195ce-6b71-590c-9129-430a1f610ea8','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b7b195ce-6b71-590c-9129-430a1f610ea8' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e0934080-4a9e-5dc6-bbf0-3614972d05d2','Format migration','Format migration is the digital-preservation strategy of transferring content from an obsolete or at-risk file format to a current, better-supported format while preserving its essential characteristics. It addresses format (encoding) obsolescence, as distinct from refreshing, which copies the same bitstream to new media without changing the format.','File formats go out of date as software changes. Format migration copies the content into a newer file type that today''s programs can open. The goal is to keep the material usable, not just stored.','It keeps content accessible as the software and formats needed to open it become obsolete, preventing files from becoming unreadable even when the bits survive intact.','A technician migrates aging files to a current preservation format on a planned schedule, checking after each migration that no essential content was lost.','Digital Preservation',ARRAY['Format obsolescence risk','Refreshing','Emulation','Normalization','Preservation format','Fixity']::text[],ARRAY['Confusing migration (changing the file format) with refreshing (copying the same format to new media).','Migrating repeatedly without checking results, so small losses accumulate across generations.','Assuming migration preserves everything, when complex or proprietary features can be lost in conversion.']::text[],ARRAY['Converting obsolete word-processor files to a current archival document format.','Migrating an old proprietary audio format to a supported preservation format such as broadcast WAV.','Planning a scheduled migration before a format loses vendor support.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e0934080-4a9e-5dc6-bbf0-3614972d05d2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Format migration'),'[^a-z0-9]','','g'));
