INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '92afea89-94a2-55ad-908b-3ba16f6c230d','Format obsolescence risk','Format obsolescence risk is the likelihood that a file format will become difficult or impossible to render because the software, hardware, or knowledge needed to open it is no longer available or supported. It is assessed from factors such as how open and well-documented the format is, how widely adopted it is, and its dependence on proprietary or unsupported tools.','A file format can go out of date when the software to open it disappears. Format obsolescence risk is the chance that will happen to a given format. Open, common formats carry lower risk.','Rating this risk lets an archive decide which files to migrate first and which formats to choose for new content, so material is preserved before it becomes unreadable.','A technician reviews collections for high-risk proprietary formats and prioritizes them for migration to open, well-supported preservation formats.','Digital Preservation',ARRAY['Format migration','Media obsolescence','Preservation format','Emulation','File format registry']::text[],ARRAY['Watching only for media failure and ignoring format obsolescence, so files survive on disk but cannot be opened.','Assuming a popular current format will stay readable forever without monitoring its support.','Choosing an undocumented proprietary format for new archival content, which raises its future obsolescence risk.']::text[],ARRAY['Ranking collection formats by risk to set migration priorities.','Rejecting a proprietary format for a new digitization project in favor of an open one.','Reassessing risk when a software vendor announces end of support for a format.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='92afea89-94a2-55ad-908b-3ba16f6c230d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Format obsolescence risk'),'[^a-z0-9]','','g'));
