SELECT '92afea89-94a2-55ad-908b-3ba16f6c230d','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='92afea89-94a2-55ad-908b-3ba16f6c230d' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1d33ce02-748d-5d6e-9a94-d88a1501fb58','Geographic replication','Geographic replication is the storage of multiple complete copies of digital content in physically separate locations, ideally with different disaster-threat profiles, so that no single local event can destroy every copy. It is a core requirement of tiered preservation frameworks such as the NDSA Levels of Digital Preservation.','Geographic replication means keeping copies of your files in different places, far apart. A fire or flood in one place cannot destroy the others. The best copies sit in areas with different disaster risks.','It protects against localized disasters — fire, flood, earthquake, theft — by ensuring surviving copies exist elsewhere, guarding against the correlated loss of every copy at once.','A technician stores preservation copies across separate sites and confirms at least one copy sits in a region with a different disaster threat than the others.','Digital Preservation',ARRAY['Redundancy','Fixity check','Disaster recovery','LOCKSS','Distributed digital preservation','Off-site backup']::text[],ARRAY['Keeping several copies but storing them all in the same building or region, so one disaster destroys them all.','Placing distant copies that still share the same disaster threat, such as two sites on the same flood plain or fault line.','Assuming a single cloud provider automatically gives true geographic separation without confirming where copies are held.']::text[],ARRAY['Storing master files at two sites in different seismic zones.','Meeting an NDSA Level requirement for a copy in a different disaster-threat region.','Recovering an archive from a remote copy after a fire destroys the primary site.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1d33ce02-748d-5d6e-9a94-d88a1501fb58' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Geographic replication'),'[^a-z0-9]','','g'));
