SELECT '1d33ce02-748d-5d6e-9a94-d88a1501fb58','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1d33ce02-748d-5d6e-9a94-d88a1501fb58' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd393c6d7-d74d-58a1-b928-0d2784780cd1','Glass-base fracture','Glass-base fracture is the cracking or shattering of a lacquer (instantaneous) disc that was manufactured on a rigid glass core. Such discs were common during World War II when aluminium was rationed; the glass base is extremely brittle, grows more fragile with age, and can crack beneath the lacquer or break entirely from shock, flexing, or thermal stress, often causing irretrievable loss of the recording.','Some old recording discs were made on a glass core. Glass is brittle, so it can crack or shatter if bumped or bent. This is called glass-base fracture, and it can destroy the recording for good.','Recognizing glass-base discs and their fracture risk tells an archivist to handle, store, and transfer them with extra care and to prioritize them for digitization before they break.','A technician identifies a glass-base disc (heavy, semi-translucent when backlit), supports it flat and fully during handling, and reformats it promptly because a fracture is unrecoverable.','Disc Preservation',ARRAY['Lacquer disc','Instantaneous disc','Delamination','Plasticizer exudate','Format migration']::text[],ARRAY['UNSAFE: Handling a cracked or shattered glass-base disc without cut-resistant gloves and full support, risking cuts from sharp glass edges.','Flexing or stacking glass-base discs like sturdier aluminium ones, which can crack the brittle base.','Assuming a glass disc that looks intact is sound, when it may already be cracked beneath the lacquer.','Delaying transfer of glass-base discs, since their fragility only increases with age.']::text[],ARRAY['Identifying a wartime glass-base lacquer disc by holding it up to the light.','Carefully transporting a fragile glass disc flat and supported to a playback lab.','Prioritizing glass-base discs for urgent digitization before they fracture.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d393c6d7-d74d-58a1-b928-0d2784780cd1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Glass-base fracture'),'[^a-z0-9]','','g'));
