INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c96d832d-0e4f-530d-b781-252f69c08b9f','Gray Audograph disc','The Gray Audograph disc is a flexible plastic office-dictation record used with the Gray Manufacturing Company''s Audograph machine, introduced in the mid-1940s. It was recorded and replayed only on that machine, used a variable recording speed to extend playing time on a small disc, and is now an obsolete format requiring the original or specially built equipment to play back.','The Gray Audograph was a soft plastic disc used to record office dictation. It played back only on its own special machine. That machine is now rare, so the discs are very hard to hear today.','It let offices record spoken dictation cheaply on a small flexible disc for later typing; today its obsolescence means recordings survive only where the rare original machine or a custom playback rig is available.','An archivist who finds Audograph discs must locate or build compatible playback equipment, since standard turntables cannot track the format''s variable-speed grooves.','Obsolete Formats',ARRAY['Dictation disc','Instantaneous disc','Format obsolescence risk','Format migration','Lacquer disc']::text[],ARRAY['Trying to play an Audograph disc on a standard turntable, which cannot follow its variable-speed grooves.','Assuming the discs are ordinary vinyl records and shelving them without noting they need special equipment.','Delaying transfer, since working Audograph playback machines are increasingly rare.']::text[],ARRAY['Cataloguing a box of mid-century office dictation discs found in a collection.','Sourcing a working Audograph machine to digitize surviving recordings.','Flagging Audograph discs as high-priority because playback equipment is disappearing.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c96d832d-0e4f-530d-b781-252f69c08b9f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gray Audograph disc'),'[^a-z0-9]','','g'));
