SELECT 'c96d832d-0e4f-530d-b781-252f69c08b9f','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c96d832d-0e4f-530d-b781-252f69c08b9f' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cbb3e6e8-3771-5c54-94ba-6be78bc3002d','Groove accretion','Groove accretion is the accumulation of foreign deposits within a disc''s grooves — dust, dirt, oils and fingerprints, mould or fungal growth, plasticizer exudate, and residues from earlier cleaning. These accretions fill or bridge the groove, causing added surface noise, distortion, and mistracking, and some (such as fungus) can chemically or physically damage the playing surface.','Over time, grooves collect dirt, oils, and even mould. This build-up is called groove accretion. It adds noise and crackle, and it can harm the disc surface if left in place.','Naming and recognizing accretion guides safe cleaning decisions, since removing the right deposits improves playback while the wrong method can grind debris into the groove or damage the surface.','A technician inspects grooves for deposits and mould, then chooses an appropriate cleaning method to lift accretion without abrading the groove walls before transfer.','Disc Preservation',ARRAY['Groove wear','Fungal growth','Plasticizer exudate','Record cleaning','Surface noise']::text[],ARRAY['UNSAFE: Dry-brushing or handling mould-contaminated discs without gloves and respiratory protection, releasing spores that are a biohazard; isolate the disc and follow a conservation mould protocol.','UNSAFE: Cleaning discs with improvised solvents such as alcohols or acetone, which can dissolve or craze lacquer and shellac surfaces and may be flammable or toxic; use only conservator-approved methods.','Wiping grooves with a dry cloth, which drags grit along the groove and abrades the walls.','Assuming white exudate on a lacquer disc is mould, when plasticizer loss produces similar-looking palmitic and stearic acid deposits.']::text[],ARRAY['Assessing a dusty disc for cleaning before digitization.','Isolating a mould-affected disc from a collection to prevent spread.','Distinguishing harmless plasticizer exudate from active fungal growth on a lacquer disc.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cbb3e6e8-3771-5c54-94ba-6be78bc3002d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove accretion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cbb3e6e8-3771-5c54-94ba-6be78bc3002d','f2442389-2379-4010-8b5a-6835773b85c7',true
