INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5d41b80f-92c7-5d2b-a61c-e2ef07b864e5','Groove collapse','Groove collapse is the deformation or flowing-together of a disc''s groove walls so that the recorded modulation is partially or wholly lost. It occurs when a soft or thermoplastic disc material (such as the flexible vinyl of some dictation discs) softens under heat, sustained pressure, or aging, or when a heavy or mistracking stylus plastically deforms the groove.','Grooves hold sound in their shaped walls. If the disc gets too warm or is pressed too hard, those walls can slump and merge. This groove collapse smears or erases the sound.','Understanding groove collapse warns archivists to store soft discs cool and flat and to track them with light, correct styli, since collapsed grooves cannot be fully recovered.','A technician handling soft dictation or lacquer discs uses minimal tracking force and cool, flat storage to avoid deforming grooves that heat or pressure could collapse.','Disc Preservation',ARRAY['Groove wear','Warping','Tracking force','Thermoplastic','Vinyl']::text[],ARRAY['Storing soft vinyl or dictation discs near heat sources, letting the grooves soften and flow.','Using heavy tracking force or a worn stylus on soft discs, which plastically deforms the groove walls.','Stacking flexible discs under weight, pressing the grooves out of shape.','Assuming collapsed grooves can be fully restored, when the lost modulation is usually unrecoverable.']::text[],ARRAY['Finding smeared, low-level audio on a dictation disc left in a hot store.','Setting light tracking force before playing a soft flexible disc.','Storing flexible discs flat and cool to prevent groove deformation.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5d41b80f-92c7-5d2b-a61c-e2ef07b864e5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove collapse'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5d41b80f-92c7-5d2b-a61c-e2ef07b864e5','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5d41b80f-92c7-5d2b-a61c-e2ef07b864e5' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd2287f37-15f3-53fb-8ebd-d74033eb5077','Groove eccentricity','Groove eccentricity is the condition in which a disc''s groove spiral is not concentric with its center (spindle) hole, so the stylus is displaced back and forth once per revolution. It is usually caused by an off-center hole or off-center recording or pressing, and it produces a cyclic pitch and speed variation (wow) at the rotation rate.','A record''s grooves should sit evenly around the center hole. If they are off-center, the pitch drifts up and down once every turn. This slow pitch wobble is called wow.','Recognizing eccentricity lets an operator correct playback — for example by re-centering the disc on a turntable with a removable spindle — to remove the once-per-revolution wow it causes.','When a transfer shows a slow, once-per-turn pitch wobble, a technician suspects an off-center hole and re-centers the disc, sometimes on a turntable with a removable spindle.','Disc Preservation',ARRAY['Wow and flutter','Off-center pressing','Spindle hole','Warping','Speed stability']::text[],ARRAY['Blaming once-per-revolution wow on the turntable motor when an eccentric groove or off-center hole is the real cause.','Enlarging or forcing the spindle hole to re-center a disc, which permanently damages it.','Assuming all speed wobble is flutter, when eccentricity produces a slow wow locked to the rotation rate.']::text[],ARRAY['Diagnosing a slow, cyclic pitch wobble during a disc transfer.','Re-centering an off-center disc on a turntable with a removable spindle.','Explaining why an off-center hole causes wow but not flutter.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d2287f37-15f3-53fb-8ebd-d74033eb5077' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove eccentricity'),'[^a-z0-9]','','g'));
