INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c6ef1ef7-567e-5588-acb5-2d4c60be5f29','Groove embossing recovery','Groove embossing recovery is the process of recovering audio from embossed-groove recordings — instantaneous discs and similar media whose grooves were formed by pressing or indenting a soft base such as aluminium, rather than by cutting or engraving. Because embossed grooves are shallow, irregular, and easily deformed, recovery requires careful stylus selection and gentle, sometimes specialized, replay to extract the signal without further damage.','Some old discs had their grooves pressed in, not cut. These embossed grooves are shallow and fragile. Groove embossing recovery is the careful work of playing them back to save the sound.','It lets archivists retrieve audio from fragile embossed recordings that ordinary playback can easily distort or destroy, using matched styli and gentle tracking suited to shallow, pressed grooves.','A technician who identifies an embossed disc chooses a stylus that fits the shallow groove and tracks it gently, sometimes using optical or specialized replay to recover the signal.','Disc Preservation',ARRAY['Embossed disc','Instantaneous disc','Stylus selection','Lacquer disc','Format migration']::text[],ARRAY['Treating an embossed disc like a normal cut record and using a heavy stylus that flattens the shallow groove.','Choosing a stylus that rides the wrong part of the shallow embossed groove, losing signal or adding distortion.','Playing a fragile embossed recording many times instead of capturing it cleanly in one careful transfer.']::text[],ARRAY['Recovering audio from an embossed aluminium home-recording disc.','Selecting a stylus matched to a shallow embossed groove before transfer.','Deciding on specialized replay for an embossed disc too fragile for a standard pickup.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c6ef1ef7-567e-5588-acb5-2d4c60be5f29' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove embossing recovery'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c6ef1ef7-567e-5588-acb5-2d4c60be5f29','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c6ef1ef7-567e-5588-acb5-2d4c60be5f29' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e04e8eed-160c-5c09-9d5a-3685dad22cb8','Groove-bottom riding','Groove-bottom riding is the condition in which a playback stylus sits down onto the bottom of the groove instead of contacting the two groove walls where the modulation lies. It typically results from a stylus tip that is too small, too pointed, or worn for the groove, and it picks up bottom debris and damage, adding noise and distortion while losing signal from the walls.','In a record groove, the sound is held on the two side walls. If the stylus drops to the bottom, it misses the walls and rides on trapped grit. This groove-bottom riding adds noise and loses sound.','Understanding it guides stylus choice — often a truncated tip that rides higher on the walls and clears the debris and wear collected at the groove bottom.','Facing a noisy or worn disc, a technician fits a truncated or larger stylus so it rides the groove walls above the damaged bottom, improving the transfer.','Disc Preservation',ARRAY['Stylus selection','Truncated stylus','Groove wear','Groove accretion','Vertical cut']::text[],ARRAY['Using a small, pointed stylus on a worn lateral disc, letting it drop to the noisy, damaged groove bottom.','Assuming a stylus should reach the groove bottom, when on lateral records the signal lives on the walls.','Ignoring debris collected at the groove bottom, so the stylus tracks through grit instead of clearing it with a truncated tip.']::text[],ARRAY['Choosing a truncated stylus to lift the tip off a damaged groove bottom.','Reducing surface noise on a worn 78 by riding higher on the groove walls.','Recognizing that bottom debris, not the recording itself, is the source of distortion.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e04e8eed-160c-5c09-9d5a-3685dad22cb8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-bottom riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e04e8eed-160c-5c09-9d5a-3685dad22cb8','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e04e8eed-160c-5c09-9d5a-3685dad22cb8' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b3d564d6-d2e4-53eb-bea0-3b45532d66f5','Groove-wall fracture','The cracking or breaking of the walls of a disc''s groove — the angled surfaces whose lateral or vertical undulations carry the recorded signal. Fracturing of a groove wall, from embrittlement, shrinkage stress, delamination, or mechanical damage, destroys the modulation cut into that surface and leaves permanent dropouts, noise, and loss of audio at the fractured points.','A record groove has two side walls. The tiny wiggles cut into those walls hold the sound. A groove-wall fracture is a crack or break in a wall. Where the wall breaks, that piece of the sound is lost for good.','Naming this specific failure helps a transfer engineer tell true, unrecoverable groove damage apart from surface dirt or a mistracking stylus, and judge whether a disc can be safely played at all.','Under raking light or a microscope, a technician inspects the groove walls for fractures before playback, then chooses a stylus and tracking force that avoid catching and enlarging the cracks.','Disc Deterioration',ARRAY['Lacquer delamination','Lacquer flaking','Groove-wall selection','Lateral-cut recording','Instantaneous disc']::text[],ARRAY['Mistaking a groove-wall fracture for surface dirt and trying to clean or play through it, which widens the crack.','Assuming a normal stylus and tracking force are safe on a fractured disc, when they can snag and shatter the wall further.','UNSAFE: Handling brittle, fracturing shellac or delaminating lacquer discs bare-handed; the fragments are sharp and the nitrocellulose lacquer coating is flammable.']::text[],ARRAY['Finding cracked groove walls on a shrunken lacquer disc during condition assessment.','Choosing optical scanning over a stylus because the groove walls are fractured and fragile.','Explaining audible dropouts on a transfer as loss at fractured groove-wall sections.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b3d564d6-d2e4-53eb-bea0-3b45532d66f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-wall fracture'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b3d564d6-d2e4-53eb-bea0-3b45532d66f5','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b3d564d6-d2e4-53eb-bea0-3b45532d66f5' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '12339516-d893-52d1-922c-f85fa87020d5','Groove-wall selection','A disc-transfer technique in which the signal is derived from one wall of a lateral groove rather than the combined motion of both walls. Because each wall carries the modulation independently, a stereo pickup or an optical scanner can capture the walls separately, letting the engineer keep the better-preserved wall — or an undamaged region of a wall — when the other is worn, damaged, or delaminated.','A record groove has a left wall and a right wall. On a mono disc both walls hold the same sound. If one wall is worn or broken, you can use just the good wall. Picking the better wall this way gives a cleaner transfer.','It lets an archivist recover a cleaner signal from a damaged monophonic disc by taking audio from whichever wall survived, instead of averaging in noise and distortion from the damaged side.','Using a stereo cartridge, the engineer records both walls as separate channels, then auditions each and keeps or blends the wall that gives the least noise and distortion.','Disc Transfer',ARRAY['Lateral-cut recording','Hill-and-dale recording','Groove-wall fracture','Instantaneous disc','Lacquer flaking']::text[],ARRAY['Forgetting that a mono lateral disc puts the same signal on both walls, so a stereo pickup can be used to choose the better one.','Summing both walls to mono by habit, which reintroduces the noise from the damaged wall you were trying to avoid.','Assuming vertical hill-and-dale discs allow the same wall choice, when their signal is in the groove''s up-and-down motion, not the two walls independently.']::text[],ARRAY['Transferring a worn 78 where one groove wall is far noisier than the other.','Recovering a mono lacquer disc by keeping the undamaged wall captured on a stereo cartridge.','Comparing left-wall and right-wall channels in software to pick the cleaner transfer.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='12339516-d893-52d1-922c-f85fa87020d5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-wall selection'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
