INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '591083c3-84c5-58cc-9a1b-519961f99db7','Hill-and-dale recording','A mechanical recording method in which the signal is cut as vertical, up-and-down undulations in the depth of the groove, so the groove bottom rises and falls while its width stays roughly constant. Also called vertical-cut recording, it is the principle of all phonograph cylinders and of vertical-cut discs such as Edison Diamond Discs and Pathe records, in contrast to the side-to-side lateral cut of most gramophone discs.','In hill-and-dale recording the groove goes up and down in depth, like tiny hills and valleys. The needle bobs up and down to make the sound. Edison and Pathe discs and all cylinders work this way. Most other records instead wiggle side to side.','Vertical modulation was an early way to store sound on discs and cylinders; recognising it tells a transfer engineer the signal is in the groove''s depth, so the correct pickup and playback settings can be used.','When transferring an Edison Diamond Disc or Pathe record, the engineer sets the cartridge to vertical mode so the up-and-down modulation is read correctly instead of cancelled.','Disc Formats',ARRAY['Lateral-cut recording','Groove-wall selection','Instantaneous disc','Inside-start disc','Groove-wall fracture']::text[],ARRAY['Playing a vertical-cut hill-and-dale disc with a lateral pickup summed to mono, which cancels the signal and leaves mostly noise.','Assuming every disc is lateral-cut and using the wrong groove size and stylus for an Edison or Pathe record.','Confusing hill-and-dale (depth modulation) with lateral cut (side-to-side modulation).']::text[],ARRAY['Identifying an Edison Diamond Disc as vertical-cut before choosing a stylus.','Setting a cartridge to vertical mode to transfer a Pathe disc.','Explaining why a hill-and-dale cylinder needs different playback from a lateral 78.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='591083c3-84c5-58cc-9a1b-519961f99db7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hill-and-dale recording'),'[^a-z0-9]','','g'));
