INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '47d90e13-0411-573c-9b62-3c43597c2727','Independent understandability','In the OAIS reference model (ISO 14721), the property that preserved information can be understood by its Designated Community without help from the original producer. Achieving it requires the archive to keep sufficient Representation Information — structure and semantic metadata — alongside the content so future users can render and interpret the bit stream on their own.','A stored file should make sense to future users on its own. They should not need to ask the person who made it. So an archive keeps extra notes that explain the file''s format and meaning. This goal is called independent understandability.','It sets the real goal of digital preservation: not just keeping the bits, but keeping enough context that a defined future audience can still open and make sense of the content.','When ingesting a file, an archivist records its format specification, codec, and descriptive metadata so the material stays understandable to its Designated Community decades later.','Digital Preservation',ARRAY['Ingest validation','OAIS reference model','Designated community','Representation information']::text[],ARRAY['Thinking that saving the file bytes is enough, and leaving out the format and context notes needed to read them later.','Assuming today''s software will always open the file, instead of documenting the format for its Designated Community.','Confusing independent understandability (users need no help from the producer) with simply being able to copy the bits.']::text[],ARRAY['Deciding what metadata to attach to an audio file so future users can identify its codec and content.','Reviewing an archive against OAIS to check that ingested files are independently understandable.','Explaining why a proprietary format needs its specification preserved alongside the data.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='47d90e13-0411-573c-9b62-3c43597c2727' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Independent understandability'),'[^a-z0-9]','','g'));
