SELECT '47d90e13-0411-573c-9b62-3c43597c2727','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='47d90e13-0411-573c-9b62-3c43597c2727' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f4093336-417b-5ff6-b37b-c7adc826e1db','Ingest validation','The quality-control step in the OAIS Ingest function where a Submission Information Package (SIP) received from a producer is verified before it enters archival storage. Validation confirms the content is complete and uncorrupted — typically by checking file counts, formats, and checksums against the submission agreement — and rejects or quarantines anything that fails.','When new files arrive at an archive, they are checked before being stored. The check makes sure nothing is missing or broken. It compares the files against what the sender promised. Files that fail are held back. This step is called ingest validation.','It stops corrupt, incomplete, or wrong-format material from entering the archive, so preservation begins from a known-good copy that matches the agreed submission.','On receiving a batch of transfers, an archivist runs a tool that verifies each file''s checksum and format against the manifest, flagging any mismatch for the producer to resend.','Digital Preservation',ARRAY['Independent understandability','Integrity audit','Submission information package','Fixity check']::text[],ARRAY['Skipping checksum verification at ingest, so a file corrupted in transfer is preserved as if it were good.','Treating ingest validation as a one-time formality instead of comparing files against the submission agreement.','Confusing ingest validation (checking incoming packages) with the ongoing integrity audit of already-stored files.']::text[],ARRAY['Verifying checksums and file formats on a delivery of digitised audio before accessioning it.','Rejecting a submission package whose file count does not match its manifest.','Extracting technical metadata during ingest to build the archival package.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f4093336-417b-5ff6-b37b-c7adc826e1db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ingest validation'),'[^a-z0-9]','','g'));
