SELECT 'f4093336-417b-5ff6-b37b-c7adc826e1db','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f4093336-417b-5ff6-b37b-c7adc826e1db' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '81295629-e67a-5fe2-8d86-89fbfdde9adf','Inside-start disc','A disc whose recorded groove spirals from the inner diameter near the label outward toward the rim, so playback begins at the centre rather than the outer edge. Used on some radio transcription discs and other instantaneous recordings — for example to place a programme''s ending at the higher-surface-speed outer grooves or to synchronise multi-disc broadcasts — it is the reverse of the outside-start format of most commercial records.','Most records start at the outer edge and play inward. An inside-start disc does the opposite. Its groove begins near the centre and spirals out to the edge. So the needle is set down near the label to start. Some radio transcription discs were made this way.','Knowing a disc starts from the inside tells the transfer engineer where to cue the stylus and which way the programme runs, preventing a backwards or mis-started transfer.','Before transfer, the technician inspects the lead-in groove; if it sits near the label, they cue the stylus at the inside and play outward toward the rim.','Disc Formats',ARRAY['Instantaneous disc','Lateral-cut recording','Hill-and-dale recording','Groove-wall selection']::text[],ARRAY['Assuming every disc plays from the outside in, and cueing an inside-start transcription at the wrong groove.','Not checking where the lead-in groove sits, so the programme is transferred starting from the wrong end.','Confusing an inside-start disc with a disc merely played in reverse, when the groove was genuinely cut from the centre out.']::text[],ARRAY['Cueing a 16-inch radio transcription disc whose recording begins near the label.','Documenting play direction on an unlabelled instantaneous disc before transfer.','Recognising an inside-start side when following a two-turntable broadcast sequence.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='81295629-e67a-5fe2-8d86-89fbfdde9adf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inside-start disc'),'[^a-z0-9]','','g'));
