SELECT '81295629-e67a-5fe2-8d86-89fbfdde9adf','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='81295629-e67a-5fe2-8d86-89fbfdde9adf' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6ed2a2f8-8f14-5dd6-a7c4-4a0fea6cfd7e','Instantaneous disc','A grooved disc that is cut in real time and can be played back immediately, without the plating and pressing needed for mass-produced records. Typically a nitrocellulose (or, less often, cellulose acetate) lacquer coating on an aluminium, glass, steel, or fibre core, these direct-cut discs were used for radio transcriptions, field and home recording, and dictation.','An instantaneous disc records sound as it is cut and can be played right away. It skips the factory steps used to make store-bought records. It is usually a soft lacquer coating on a metal, glass, or card centre. Radio stations and home recorders used them.','It gave people a way to record and replay audio on the spot, before tape, which is why many unique radio broadcasts and field recordings survive only on these fragile discs.','An archivist handling an instantaneous (lacquer) disc treats it as high-priority and fragile, since the coating can crack and delaminate and the content is usually unique.','Disc Formats',ARRAY['Lacquer delamination','Lacquer flaking','Lacquer shrinkage','Inside-start disc','Lateral-cut recording']::text[],ARRAY['Calling lacquer discs ''acetate'' and assuming the coating is safe cellulose acetate, when it is usually cellulose nitrate.','Treating an instantaneous disc like a durable vinyl LP and playing it repeatedly, which speeds loss of a unique recording.','UNSAFE: Storing nitrocellulose lacquer discs near heat, sparks, or flame; the coating is flammable, so keep discs cool, dry, and away from ignition sources.']::text[],ARRAY['Prioritising a box of 1940s lacquer transcription discs for urgent digitisation.','Identifying a direct-cut lacquer disc by the metal or glass core showing at a chipped edge.','Explaining why an instantaneous disc holds a one-of-a-kind broadcast.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6ed2a2f8-8f14-5dd6-a7c4-4a0fea6cfd7e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Instantaneous disc'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6ed2a2f8-8f14-5dd6-a7c4-4a0fea6cfd7e','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6ed2a2f8-8f14-5dd6-a7c4-4a0fea6cfd7e' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dbea2d2e-0d49-5be5-a0b4-80fb79f534b4','Integrity audit','A scheduled check that stored digital objects remain unchanged and complete over time, performed by recomputing each file''s fixity value (such as a checksum) and comparing it to the value recorded at ingest. Any mismatch flags corruption or loss and triggers repair from a verified copy — a core Archival Storage responsibility in the OAIS model.','An integrity audit checks that stored files have not changed or gone bad. The archive works out a math fingerprint for each file. It compares that to the fingerprint saved earlier. If they differ, the file is damaged and is restored from a backup.','It detects silent data corruption — from disk errors, bad copies, or media decay — before it spreads through backups, so an archive can show its files are still authentic and intact.','On a set schedule, a repository runs fixity checks across its store, reviews the report for any checksum mismatch, and restores affected files from a known-good copy.','Digital Preservation',ARRAY['Ingest validation','Independent understandability','Fixity check','Checksum']::text[],ARRAY['Keeping extra copies but never re-checking their fixity, so corruption goes unnoticed until every copy is bad.','Recording checksums at ingest but never auditing them again over time.','Assuming a file is fine because it still opens, when silent bit errors can corrupt data with no obvious failure.']::text[],ARRAY['Running a monthly checksum sweep across a digital audio repository.','Detecting a corrupted preservation master and restoring it from a backup copy.','Reporting fixity results to demonstrate a trustworthy repository.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dbea2d2e-0d49-5be5-a0b4-80fb79f534b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Integrity audit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dbea2d2e-0d49-5be5-a0b4-80fb79f534b4','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dbea2d2e-0d49-5be5-a0b4-80fb79f534b4' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '78c14a28-c36f-5aba-9923-ed3715f64532','Lacquer delamination','The separation of a lacquer disc''s nitrocellulose recording coating from its rigid aluminium, glass, or fibre core. As the coating loses plasticizer and shrinks relative to the stable core, it embrittles, cracks, curls, and lifts away — carrying the grooved signal with it — causing irreversible, often sudden loss of the recording.','A lacquer disc is a soft coating on a hard centre. That coating holds the grooves. Delamination is when the coating cracks and peels off the centre. When a piece lifts away, the sound cut into it is lost for good.','Delamination is the main failure mode of lacquer discs; spotting its early signs tells an archivist a disc may fail suddenly and must be digitised urgently.','During assessment a technician looks for lifting edges, cracks, and curling flakes; a delaminating disc is flagged for immediate optical or careful stylus transfer before more coating is lost.','Disc Deterioration',ARRAY['Lacquer shrinkage','Lacquer flaking','Lacquer lifting','Instantaneous disc','Groove-wall fracture']::text[],ARRAY['UNSAFE: Handling a delaminating disc without gloves and edge support, so sharp, brittle flakes break off and stress the flammable nitrocellulose coating.','Playing a delaminating disc with a stylus, which knocks loose coating free and can destroy the remaining signal.','Storing lacquer discs in warm or humid conditions, which speeds shrinkage and delamination.']::text[],ARRAY['Finding lifted, curling coating at the edge of a glass-core wartime transcription disc.','Choosing optical scanning to recover audio from a heavily delaminating lacquer disc.','Prioritising delaminating discs at the top of a digitisation queue.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='78c14a28-c36f-5aba-9923-ed3715f64532' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lacquer delamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '78c14a28-c36f-5aba-9923-ed3715f64532','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='78c14a28-c36f-5aba-9923-ed3715f64532' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '71e2e490-df4b-5fde-a545-ea981311210b','Lacquer flaking','A stage of lacquer-disc deterioration in which small pieces of the embrittled nitrocellulose coating break loose and separate completely from the core. Driven by plasticizer loss and shrinkage, flaking removes the grooves cut into those pieces, leaving bare substrate and permanent gaps in the recording.','As a lacquer disc ages, its coating gets brittle. Small chips, or flakes, break off the hard centre. Each flake takes its grooves with it. Where a flake is gone, so is that bit of sound.','Flaking marks an advanced, active stage of delamination; recognising loose flakes warns a technician that any handling or playback may knock off more coating and audio.','Seeing flakes shed from a disc, the technician stops mechanical playback, supports the disc flat, and considers non-contact optical capture of the coating that remains.','Disc Deterioration',ARRAY['Lacquer delamination','Lacquer lifting','Lacquer shrinkage','Groove-wall fracture','Instantaneous disc']::text[],ARRAY['UNSAFE: Brushing or wiping loose flakes off by hand without gloves, breaking sharp, brittle fragments from a flammable nitrocellulose coating.','Playing a flaking disc with a stylus, which dislodges more coating and loses more of the recording.','Turning or standing a flaking disc on edge, letting gravity shed flakes instead of keeping it flat and supported.']::text[],ARRAY['Noticing coating flakes loose in the sleeve of a stored lacquer disc.','Halting a transfer when the stylus starts shedding flakes from the groove.','Documenting missing-audio gaps caused by lost flakes.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='71e2e490-df4b-5fde-a545-ea981311210b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lacquer flaking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '71e2e490-df4b-5fde-a545-ea981311210b','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='71e2e490-df4b-5fde-a545-ea981311210b' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b053ffe1-f3ef-5bd8-90aa-1ae0d9eaa9ad','Lacquer lifting','An early stage of lacquer-disc delamination in which the nitrocellulose coating loses adhesion and rises away from its core — often first at the edges or the centre hole — bubbling, curling, or tenting before it cracks and flakes off. The lifted coating still carries the grooves but is fragile and no longer flat against the substrate.','Lacquer lifting is when the coating starts to pull up off the hard centre. It often begins at the edge or the centre hole. The coating bubbles or curls up but has not fallen off yet. It is very fragile at this stage.','Lifting is a warning sign that delamination has begun; catching it early lets an archivist transfer the disc before the coating cracks and pieces are lost.','A technician spotting lifted or tented coating handles the disc flat, avoids stylus play that could catch the raised edge, and schedules urgent transfer.','Disc Deterioration',ARRAY['Lacquer delamination','Lacquer flaking','Lacquer shrinkage','Groove-wall fracture','Instantaneous disc']::text[],ARRAY['Dismissing edge lifting as harmless, when it is the start of delamination and pieces will soon break away.','UNSAFE: Pressing lifted coating back down or handling it bare-handed, cracking the brittle, flammable nitrocellulose layer.','Running a stylus across lifted coating, where the raised edge catches and tears the layer further.']::text[],ARRAY['Seeing the coating tent up around the centre hole of a lacquer disc.','Flagging a disc with edge lifting for priority digitisation.','Choosing non-contact transfer because lifted coating would snag a stylus.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b053ffe1-f3ef-5bd8-90aa-1ae0d9eaa9ad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lacquer lifting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b053ffe1-f3ef-5bd8-90aa-1ae0d9eaa9ad','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b053ffe1-f3ef-5bd8-90aa-1ae0d9eaa9ad' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15e87c3f-6f44-5e71-bfee-c2151cbce950','Lacquer shrinkage','The gradual contraction of a lacquer disc''s nitrocellulose coating as it loses plasticizer — notably castor oil, which breaks down and exudes as a white palmitic- and stearic-acid film. Because the rigid metal or glass core does not shrink with it, the coating builds internal stress that leads to cracking, lifting, and delamination.','The coating on a lacquer disc slowly shrinks as it ages and dries out. The hard centre underneath does not shrink. So the coating is pulled tight and stressed. Over time this makes it crack and peel away. A white greasy film on the surface is a warning sign.','Shrinkage is the root cause behind cracking and delamination of lacquer discs; understanding it explains why cool, stable storage slows the damage and why these discs fail.','Finding a shrunken disc with a white palmitic-acid bloom, the technician cleans it only with a preservation-validated aqueous method and prioritises transfer before cracking worsens.','Disc Deterioration',ARRAY['Lacquer delamination','Lacquer lifting','Lacquer flaking','Groove-wall fracture','Instantaneous disc']::text[],ARRAY['UNSAFE: Cleaning a shrunken lacquer disc with alcohol or other solvents, which dissolve and further damage the nitrocellulose coating; use only preservation-validated aqueous cleaners.','Mistaking the white palmitic-acid bloom of shrinkage for mould and scrubbing it away aggressively.','Storing lacquer discs warm or cycling the humidity, which speeds plasticizer loss and shrinkage.']::text[],ARRAY['Seeing a white, greasy palmitic-acid film on an old transcription disc.','Explaining edge cracks as the result of the coating shrinking on a stable core.','Setting cool, stable storage to slow shrinkage across a lacquer disc collection.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15e87c3f-6f44-5e71-bfee-c2151cbce950' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lacquer shrinkage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
