INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9eb0a56b-03f4-5fdd-9406-7247c1b3716b','Lateral-cut recording','A mechanical recording method in which the signal is cut as side-to-side (horizontal) undulations of a groove of roughly constant depth, so the groove walls swing left and right and the stylus tracks that motion. It is the standard for most gramophone discs — coarse-groove 78s, transcription discs, and microgroove LPs — as opposed to the vertical hill-and-dale cut of cylinders and Edison and Pathe discs.','In lateral-cut recording the groove wiggles side to side. The needle swings left and right to pick up the sound. Almost all normal records work this way. Cylinders and a few disc brands instead use up-and-down grooves.','Lateral cutting became the dominant disc standard because it plays back well and both groove walls can carry the signal; knowing a disc is lateral tells the engineer to use a horizontal or summed-stereo pickup.','For a 78 or LP the technician confirms lateral cut, fits a stylus of the correct size, and reads the side-to-side groove with a mono or summed-stereo cartridge.','Disc Formats',ARRAY['Hill-and-dale recording','Groove-wall selection','Groove-wall fracture','Instantaneous disc','Inside-start disc']::text[],ARRAY['Confusing lateral cut (side-to-side) with hill-and-dale (up-and-down) modulation.','Using a microgroove LP stylus on a coarse-groove lateral 78, so it rides at the wrong depth and tracks poorly.','Assuming all lateral discs share one groove size and speed, ignoring 78-versus-LP differences.']::text[],ARRAY['Selecting a coarse-groove stylus to transfer a lateral-cut 78.','Distinguishing a lateral commercial disc from a vertical-cut Pathe.','Summing a stereo cartridge to mono to play a lateral mono disc.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9eb0a56b-03f4-5fdd-9406-7247c1b3716b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lateral-cut recording'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9eb0a56b-03f4-5fdd-9406-7247c1b3716b','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9eb0a56b-03f4-5fdd-9406-7247c1b3716b' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8c965d73-7cc3-5172-8517-fc97938c7988','MD5 chunk','An optional metadata chunk in a Broadcast WAVE (BWF) audio file, tagged <MD5>, that stores a 16-byte MD5 hash calculated over the audio samples in the <data> chunk only, excluding the chunk id, size declaration, and any padding byte. It provides an embedded fixity value for confirming that the audio content has not changed.','It is a small fingerprint stored inside a sound file. The fingerprint is made only from the audio itself. Later you can recheck it to prove the sound was not changed or damaged.','It embeds a checksum of just the audio data so archivists can detect corruption or tampering over time, while still allowing descriptive metadata to be edited without invalidating the value.','A technician uses a tool such as BWF MetaEdit to compute and embed the MD5 chunk at digitization, then re-verifies it during transfers and storage audits to confirm the audio bitstream is intact.','File Fixity',ARRAY['Checksum','Fixity','Broadcast Wave Format','Originator reference','Metadata crosswalk']::text[],ARRAY['Assuming the MD5 chunk covers the whole file; it hashes only the audio data chunk, so editing metadata does not break it.','Confusing the embedded MD5 chunk with a separate sidecar checksum file; they are stored and managed differently.','Believing MD5 proves authenticity against a deliberate attack; it detects accidental corruption but is cryptographically weak against intentional collisions.']::text[],ARRAY['Embedding a checksum at the point of audio digitization so future fixity checks can detect bit rot.','Validating BWF files after migrating them to new storage to confirm no audio bytes changed.','Editing bext metadata in an archival WAV while leaving the audio checksum valid.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8c965d73-7cc3-5172-8517-fc97938c7988' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('MD5 chunk'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8c965d73-7cc3-5172-8517-fc97938c7988','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8c965d73-7cc3-5172-8517-fc97938c7988' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7ce52ad7-6130-5062-85f2-17f90082f37f','Mandrel mismatch','A condition in phonograph cylinder playback where the diameter or taper of the mandrel, the tapered spindle a cylinder is mounted on for replay, does not correctly match the cylinder''s bore, so the cylinder is loosely and eccentrically supported or, if the mandrel is oversized, is placed under mechanical stress.','A cylinder record slides onto a cone-shaped post to be played. A mismatch means the post is the wrong size for that cylinder. Too loose and it wobbles; too tight and it strains the fragile cylinder.','Correct mandrel fit is what holds a cylinder steady and safe during replay, so recognizing a mismatch helps the operator avoid unstable tracking or damage to an irreplaceable object.','Before replay a technician selects or adjusts the mandrel to the specific cylinder and checks that it seats snugly without forcing, since cylinders vary by maker and can shrink or warp with age.','Signal Extraction',ARRAY['Wax cylinder','Noncontact cylinder scanning','Signal extraction','Minimal intervention','Archéophone']::text[],ARRAY['Forcing a cylinder onto an oversized mandrel, which can crack or split a shrunken or brittle cylinder.','Using a loose, undersized mandrel so the cylinder wobbles and the stylus tracks unevenly.','Assuming one mandrel fits all cylinders and ignoring differences between makes and age-related shrinkage.']::text[],ARRAY['Setting up an unfamiliar cylinder on a player and checking mandrel fit before transfer.','Encountering a shrunken cylinder that no longer seats correctly on a standard mandrel.','Selecting the right mandrel for a specific cylinder format ahead of digitization.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7ce52ad7-6130-5062-85f2-17f90082f37f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mandrel mismatch'),'[^a-z0-9]','','g'));
