INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '489b68e1-dc68-59de-9927-e1b10987c001','Media refreshing','A digital preservation action in which stored data is copied from one storage carrier to another carrier of the same type, for example from an aging data tape or hard drive to a fresh one, before the original degrades or becomes obsolescent. The bitstream is copied unchanged, so it is a physical rather than a format change.','It means copying your files onto fresh storage before the old storage wears out. The files themselves stay exactly the same. Only the disk or tape holding them is replaced.','It counters the limited life span of physical storage media by moving the bits to reliable carriers while they can still be read, preventing loss without altering the content.','An archive on a refreshing schedule periodically copies its audio masters onto new hard drives or LTO tapes, verifies checksums, and retires carriers before they reach end of life.','Digital Preservation',ARRAY['Migration','Fixity','Checksum','Bit rot','MD5 chunk']::text[],ARRAY['Confusing refreshing (same format, new carrier) with migration (changing the file format itself).','Refreshing without verifying checksums, so silent corruption is copied onto the new carrier.','Waiting until media fails before refreshing instead of replacing carriers on a proactive schedule.']::text[],ARRAY['Copying a preservation collection from five-year-old data tapes onto a current tape generation.','Replacing aging hard drives in a storage array before their rated lifetime ends.','Cloning optical discs to new media as the originals approach known degradation limits.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='489b68e1-dc68-59de-9927-e1b10987c001' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Media refreshing'),'[^a-z0-9]','','g'));
