WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='489b68e1-dc68-59de-9927-e1b10987c001' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c6369df3-58e0-5478-be12-5d320b1b9732','Metadata crosswalk','A mapping that specifies the equivalences between the elements of one metadata schema and those of another, for example MODS to MARC, enabling records to be converted or exchanged between systems that use different standards. Because schemas differ in granularity, mappings are often not fully bidirectional without some loss of specificity.','It is a translation table between two ways of describing files. It shows which field in one system matches which field in another. This lets records move between different catalogs.','It allows records described under one standard to be shared, converted, or searched across systems using a different standard, supporting interoperability between catalogs and repositories.','When ingesting recordings into a new asset-management system, a technician uses a crosswalk to map old database fields to the new schema so titles, dates, and identifiers land in the right places.','Metadata',ARRAY['Metadata','Dublin Core','MARC','MODS','Interoperability']::text[],ARRAY['Assuming a crosswalk is loss-free; mapping between schemas of different granularity often drops specificity.','Treating a one-directional mapping as if it converts back the same way without any data loss.','Ignoring local cataloging practice, so mapped values are technically valid but semantically wrong.']::text[],ARRAY['Migrating catalog records from a legacy MARC system into a MODS-based repository.','Exchanging descriptive metadata between two archives that use different standards.','Aggregating collections into a union catalog that harvests Dublin Core.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c6369df3-58e0-5478-be12-5d320b1b9732' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Metadata crosswalk'),'[^a-z0-9]','','g'));
