WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c6369df3-58e0-5478-be12-5d320b1b9732' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aefe41da-75ea-57d8-af65-d7c8bba22a8b','Mezzanine file','An intermediate, high-quality file derived from the preservation master and used as the production source for generating access and derivative copies. It is typically lightly or losslessly compressed so it is more manageable than the master while retaining most of its quality.','It is a middle copy that sits between the top archival copy and small viewing copies. It is good enough to make other copies from. But it is easier to store and move than the master.','It gives staff a convenient, high-quality working copy so the fragile or very large preservation master does not have to be touched every time an access or distribution version is produced.','A video archive keeps an uncompressed preservation master, a lightly compressed mezzanine used for editing and repurposing, and small streaming proxies made from the mezzanine.','Preservation Files',ARRAY['Preservation master','Access copy','Proxy file','Transcoding','Normalization']::text[],ARRAY['Treating the mezzanine as the preservation master; it is a derivative, not the archival original.','Making access copies directly from the master instead of from the mezzanine, adding workload or wear.','Choosing compression so heavy that the mezzanine can no longer serve as a quality production source.']::text[],ARRAY['Producing a lightly compressed intermediate from a video preservation master to edit from.','Delivering a mezzanine to a broadcaster who then makes their own streaming versions.','Building web proxies from a mezzanine rather than repeatedly accessing the master.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aefe41da-75ea-57d8-af65-d7c8bba22a8b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mezzanine file'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
