INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5fd312b2-1f85-5ee7-a0b3-4b7d15d79aa3','Minimal intervention','A core conservation and preservation principle that any treatment or processing should be the least necessary to stabilize an object and make it accessible, avoiding unnecessary or irreversible alteration. In audio transfer it means capturing the original signal as faithfully as possible without subjective improvements such as noise reduction on the master.','It means doing as little as possible to an old item. You do only what is needed to save it and keep it usable. You avoid changes that cannot be undone.','It protects the authenticity and integrity of the original by preventing an operator from rewriting the historical document through avoidable or irreversible changes.','When transferring a disc or tape, a technician captures a flat, unmodified signal for the master and leaves any noise reduction or equalization to a separate access copy, documenting every choice made.','Preservation Ethics',ARRAY['Unmodified transfer','Reversibility','Authenticity','Preservation master','Normalization']::text[],ARRAY['Applying noise reduction or equalization to the preservation master instead of to a separate access copy.','Assuming that cleaning up the sound improves it, when it actually removes part of the historical record.','Making irreversible changes without documenting the original state or the process used.']::text[],ARRAY['Deciding not to de-noise an archival transfer so the master stays faithful to the original.','Choosing the gentlest cleaning method that will make a disc safely playable.','Documenting transfer settings so later users know exactly what was and was not altered.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5fd312b2-1f85-5ee7-a0b3-4b7d15d79aa3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Minimal intervention'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5fd312b2-1f85-5ee7-a0b3-4b7d15d79aa3','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5fd312b2-1f85-5ee7-a0b3-4b7d15d79aa3' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '681d099b-43d6-5d01-83ab-19027189d131','Mold hyphae intrusion','The growth of fungal filaments (hyphae) into and across the surface and substrate of recorded media, in which the mold secretes digestive enzymes that weaken and stain the material and physically penetrate binders, emulsions, or base layers. On magnetic tape and grooved media this can cause shedding, adhesion, and permanent loss of signal.','It is when mold grows tiny threads into a tape or disc. The threads dig in and eat away at the material. This can stain it and cause the recording to break down.','Recognizing hyphal intrusion matters because it signals active biological deterioration that can spread to other holdings and render carriers unplayable, guiding decisions to isolate, clean, and improve storage.','On inspecting media a technician who sees fuzzy or web-like growth isolates the item, puts on protective equipment, and has it cleaned by trained staff before any playback to avoid spreading spores or fouling machines.','Media Degradation',ARRAY['Relative humidity','Preventive conservation','Sticky shed syndrome','Media refreshing','Minimal intervention']::text[],ARRAY['UNSAFE: Handling or cleaning moldy media without a fitted N95 or N100 respirator, nitrile gloves, and eye protection, exposing the worker to hazardous spores.','UNSAFE: Disturbing dry, active mold in an enclosed room, releasing spores into the air and across the collection instead of working outdoors or with a HEPA-filtered vacuum.','UNSAFE: Cleaning mold from tapes or discs with household bleach or strong solvents, which damages the media and can produce hazardous fumes.','Playing a moldy tape or disc before cleaning, which spreads spores and can contaminate machine heads and other items.']::text[],ARRAY['Inspecting tapes returned from a damp store and finding web-like fungal growth.','Isolating and bagging a moldy disc to stop spores spreading to nearby holdings.','Referring heavily contaminated carriers to trained conservators for cleaning under controlled conditions.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='681d099b-43d6-5d01-83ab-19027189d131' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mold hyphae intrusion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '681d099b-43d6-5d01-83ab-19027189d131','f2442389-2379-4010-8b5a-6835773b85c7',true
