INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a9d74cc8-cf52-574c-a405-26f4891d3fe8','Noncontact cylinder scanning','A stylus-free method of recovering audio from a phonograph cylinder by optically imaging its grooved surface at high resolution, for example with the IRENE system, to build a two-dimensional photographic or three-dimensional topographic map of the grooves from which software reconstructs the sound.','It is a way to get sound off an old cylinder without ever touching the grooves. A camera takes very detailed pictures of the surface. Then software turns those pictures into sound.','It lets archives recover audio from cylinders that are too fragile, worn, or broken to survive a physical stylus, avoiding groove wear and further damage.','For a cracked or crumbling wax cylinder that a mechanical player would destroy, a lab uses an optical scanner such as IRENE to image the surface and extract the recording digitally.','Signal Extraction',ARRAY['IRENE','Optical scanning','Wax cylinder','Mandrel mismatch','Signal extraction']::text[],ARRAY['Assuming optical scanning always sounds better; mechanical playback often gives higher quality on intact cylinders.','Using it as a first resort for undamaged media instead of reserving it for fragile or broken carriers.','Underestimating the processing time and expertise needed to turn raw scans into clean audio.']::text[],ARRAY['Recovering sound from a broken cylinder that cannot be played mechanically.','Imaging a badly worn cylinder where a stylus would cause further groove loss.','Choosing optical capture for uniquely fragile field recordings.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a9d74cc8-cf52-574c-a405-26f4891d3fe8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noncontact cylinder scanning'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a9d74cc8-cf52-574c-a405-26f4891d3fe8','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a9d74cc8-cf52-574c-a405-26f4891d3fe8' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'afdca7e2-b464-51ee-9669-d4550d12fca9','Normalization','An audio process that applies a constant gain to a signal so that a chosen measure reaches a target value: peak normalization sets the highest sample to a target such as 0 dBFS, while loudness normalization sets integrated loudness to a target such as -23 LUFS per EBU R128. It changes level uniformly and does not alter the signal''s dynamics.','It turns a whole recording up or down by the same amount to hit a set level. It can match the loudest peak or the average loudness. It does not squash the sound the way a compressor does.','It brings recordings to a consistent reference level so files play back at comparable volume and use the available headroom sensibly, without applying dynamic processing.','An engineer loudness-normalizes program material to -23 LUFS for broadcast delivery, or peak-normalizes a stem to -1 dBFS to standardize levels before further work.','Signal Processing',ARRAY['LUFS','dBFS','Headroom','Compression','Peak level']::text[],ARRAY['Confusing normalization, a uniform gain change, with compression, which changes the dynamics.','Assuming peak normalization makes files sound equally loud; matching perceived loudness needs loudness normalization.','Normalizing an archival preservation master, which alters the original captured level instead of leaving it flat.']::text[],ARRAY['Setting program loudness to -23 LUFS to meet a broadcast loudness specification.','Peak-normalizing tracks so none of them clips before mastering.','Matching levels across a compilation so tracks play back at a similar volume.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='afdca7e2-b464-51ee-9669-d4550d12fca9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Normalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
