INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd34793c7-84e1-5819-a259-89dc41a6db8e','Originator reference','A field in the bext (Broadcast Audio Extension) chunk of a Broadcast WAVE file holding an ASCII string of up to 32 characters that gives an unambiguous reference to the file, allocated by the originating organization; EBU Recommendation R 99 defines a structured format for constructing this identifier.','It is a short code stored inside a broadcast sound file. The organization that made the file uses it as a unique label. It helps track exactly which file is which.','It uniquely identifies the source of a BWF file within an organization''s system, supporting tracking, exchange, and asset management across production and archival workflows.','During digitization a technician''s software writes the OriginatorReference into the bext chunk, often following the EBU R 99 pattern, so each archival WAV carries a unique, machine-readable source identifier.','Embedded Metadata',ARRAY['Broadcast Wave Format','bext chunk','MD5 chunk','Metadata','Originator']::text[],ARRAY['Exceeding the 32-character ASCII limit or omitting the terminating null so the field is malformed.','Leaving the OriginatorReference blank, discarding a key unique identifier for the file.','Confusing OriginatorReference, a unique reference code, with the Originator field, which names the producing organization or device.']::text[],ARRAY['Populating bext metadata during batch digitization of an audio collection.','Tracing an archival WAV back to the machine or session that created it.','Building unique identifiers to the EBU R 99 pattern for exchange between broadcasters.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d34793c7-84e1-5819-a259-89dc41a6db8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Originator reference'),'[^a-z0-9]','','g'));
