INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf935cbc-d21c-5492-8ab9-f769bbd45b80','Outside-start disc','A grooved disc on which the recorded spiral begins at the outer edge and runs inward toward the label, the normal arrangement for most lateral-cut discs. It is contrasted with an inside-start disc, whose groove begins near the label and spirals outward, an arrangement used on some radio transcription discs and certain vertical-cut formats.','It is a record where the needle starts at the outer edge and moves inward. That is the normal way most records play. Some special discs instead start near the middle and play outward.','Knowing whether a disc is outside-start or inside-start tells the operator where to set the stylus down and which direction the recording runs, which is essential for a correct transfer.','Before transferring an unfamiliar transcription disc, a technician checks the run-in groove to confirm it is outside-start rather than inside-start so playback begins in the right place and direction.','Grooved Media',ARRAY['Transcription disc','Lateral-cut','Vertical-cut','Lacquer disc','Signal extraction']::text[],ARRAY['Assuming every disc is outside-start and missing an inside-start transcription disc.','Cueing the stylus at the wrong edge because the start direction was not checked first.','Confusing start direction with groove cut; lateral versus vertical is a separate, independent property.']::text[],ARRAY['Transferring 16-inch radio transcription discs that may be inside-start.','Determining the correct starting edge for an unlabeled instantaneous disc.','Training staff to identify run-in grooves before playback.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf935cbc-d21c-5492-8ab9-f769bbd45b80' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Outside-start disc'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bf935cbc-d21c-5492-8ab9-f769bbd45b80','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bf935cbc-d21c-5492-8ab9-f769bbd45b80' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '70b59231-ce00-5ffb-9545-fb06d271e156','Palmitic-acid exudation','The migration of palmitic acid (usually with stearic acid) to the surface of a degrading instantaneous lacquer (acetate) disc, and less commonly some magnetic tape, appearing as a white greasy or crystalline bloom. On lacquer discs it results from hydrolysis of the castor-oil plasticizer in the nitrocellulose coating, which breaks down into free fatty acids that exude to the surface; it is an early warning that the coating is shrinking and heading toward delamination.','Old lacquer discs hold an oil that keeps the coating soft. As the disc ages, that oil breaks down. It leaves a white, greasy powder on the surface. This bloom warns that the coating is drying out and may soon crack and peel.','It is not a designed feature but a diagnostic degradation marker: its appearance tells a conservator that the plasticizer is breaking down and that the recording should be cleaned and transferred before the coating cracks and delaminates.','During condition assessment a transfer engineer inspects discs for this whitish deposit, distinguishes it from mould, gently cleans it with an approved non-ionic surfactant solution, and moves the disc to the front of the digitization queue.','Disc Degradation',ARRAY['Plasticizer loss','Lacquer disc','Delamination','Particulate occlusion','Preservation triage']::text[],ARRAY['Mistaking the white palmitic-acid bloom for mould, or the reverse; the exudate looks oily and even, while mould is dull and lattice-like.','UNSAFE: Cleaning the deposit with alcohol or other solvents; ethanol and similar solvents attack lacquer and shellac and can destroy the recording, so use only an approved non-ionic surfactant with distilled-water rinses under professional guidance.','UNSAFE: Handling a disc with suspected mould without gloves and respiratory protection; mould spores are a health hazard and professional advice should be obtained before work begins.','Assuming a bloomed disc is stable; the exudate signals active degradation and the disc should be transferred promptly.']::text[],ARRAY['Assessing a shelf of 1940s instantaneous lacquer discs and finding a greasy white film on several before playback.','Deciding, on seeing exudation, to move a disc ahead of stable items in the digitization queue.','Cleaning an exuding lacquer disc on a vacuum record-cleaning machine with non-ionic surfactant just before transfer.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='70b59231-ce00-5ffb-9545-fb06d271e156' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Palmitic-acid exudation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '70b59231-ce00-5ffb-9545-fb06d271e156','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='70b59231-ce00-5ffb-9545-fb06d271e156' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cccbfb02-ee04-5170-ad43-d4aefce01ed7','Particulate occlusion','The obstruction of a disc groove (or a tape path or head) by accumulated particulate matter — dust, dirt, fibres, mould, or exuded debris — that fills or blocks the groove so the reproducing stylus cannot accurately follow the recorded modulation, adding noise, distortion and dropouts.','Grooves on a record are tiny, so dust and grit easily settle in them. When enough builds up, it blocks the groove. The needle can no longer read the sound cleanly. You hear crackle, hiss, and dropouts until the record is cleaned.','Naming this failure mode reminds technicians that surface debris, not only physical wear, degrades playback, and that careful cleaning before transfer recovers signal that would otherwise be lost in noise.','Before transferring a disc, the engineer cleans the grooves on a vacuum record-cleaning machine to remove occluding debris, improving the signal-to-noise ratio and reducing clicks captured in the archival file.','Disc Degradation',ARRAY['Palmitic-acid exudation','Groove wear','Record cleaning','Preservation transfer','Pinch effect']::text[],ARRAY['Playing a visibly dirty disc before cleaning; the stylus drags debris through the groove and can permanently etch the groove walls.','UNSAFE: Dry-brushing or wiping grooves aggressively, or using alcohol on lacquer or shellac; this scratches the surface or dissolves the coating, so use approved wet cleaning with a soft brush and a distilled-water rinse.','Confusing removable groove occlusion with permanent groove wear or delamination, which cleaning cannot reverse.']::text[],ARRAY['A field-recorded 78 arrives caked in dust and plays with heavy crackle until it is cleaned.','Mould filaments bridging the grooves of a damp-stored lacquer disc must be removed under safe conditions before transfer.','Cleaning occluding debris from a disc to lower the noise floor of the preservation master.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cccbfb02-ee04-5170-ad43-d4aefce01ed7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Particulate occlusion'),'[^a-z0-9]','','g'));
