SELECT 'cccbfb02-ee04-5170-ad43-d4aefce01ed7','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cccbfb02-ee04-5170-ad43-d4aefce01ed7' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '253b4b75-0905-55da-aab5-7dceb07c1754','Persistent identifier','A long-lasting, unique reference assigned to a digital object or its metadata, together with a resolution service that continues to point to the object even when its storage location or URL changes. Common schemes include the Handle System, the Digital Object Identifier (DOI, ISO 26324), the Archival Resource Key (ARK), PURL and URN, distinguishing a persistent identifier from an ordinary web address that breaks when content moves.','A web link can break when a file is moved or a site is changed. A persistent identifier is a permanent name for a digital item. A lookup service always points that name to wherever the file now lives. So the reference keeps working for years.','It defeats ''link rot'' so that archived recordings and their metadata can be cited, found and retrieved reliably over the long term, which is essential to trustworthy digital preservation.','When a preservation master is ingested, the repository mints a persistent identifier such as a DOI or ARK and records it in the metadata so future users and systems can resolve to the file despite storage migrations.','Preservation Metadata',ARRAY['Preservation Description Information','Fixity','Preservation provenance','Preservation normalization','Metadata']::text[],ARRAY['Treating an ordinary URL as permanent; URLs break when servers, publishers or site structures change, whereas a persistent identifier resolves through a maintained service.','Believing the identifier alone guarantees access; persistence depends on an organisation maintaining the resolution service, which is a social as well as a technical commitment.','Confusing the identifier, which names the object, with the checksum, which is fixity that proves the object is unaltered.']::text[],ARRAY['Assigning a DOI to a digitized oral-history collection so scholars can cite a stable link.','Resolving an ARK to locate a preservation master after the archive migrated to new storage.','Recording a Handle in an item''s metadata during ingest into a digital repository.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='253b4b75-0905-55da-aab5-7dceb07c1754' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Persistent identifier'),'[^a-z0-9]','','g'));
