INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b1c0f3e-af01-5016-9151-1d579ea4cf49','Preservation normalization','The practice of converting incoming digital objects, at or before ingest, into a small set of well-supported, sustainable file formats chosen by the repository for long-term preservation. Normalization reduces format diversity so that the archive can manage obsolescence through fewer migration pathways, ideally without losing significant properties of the originals.','Archives cannot support every file type forever. Normalization means changing new files into a few trusted types the archive has chosen. Fewer types are easier to keep readable for the long term. It works best when nothing important is lost in the change.','It limits the number of formats an archive must sustain, making long-term management and future migration simpler and cheaper while lowering the risk that a file becomes unreadable.','On ingest a repository might convert assorted audio files to a preferred preservation format such as Broadcast WAV, keeping the originals alongside, so future access relies on a supported, well-documented format.','Preservation Workflow',ARRAY['Preservation Description Information','Migration','Preservation pathway','Preservation transfer','Persistent identifier']::text[],ARRAY['Deleting the original after normalizing; best practice keeps the original master in case the conversion lost significant properties.','Confusing normalization, which converts to a standard format at ingest, with migration, which converts later to escape obsolescence.','Choosing a normalization target that is popular but not open or well-documented, which undermines long-term sustainability.']::text[],ARRAY['Converting mixed digitized audio to Broadcast WAV as the repository''s preservation format at ingest.','Setting an automated ingest workflow that normalizes each accepted format to a preferred one.','Rejecting a proprietary codec as a normalization target in favour of an open standard.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b1c0f3e-af01-5016-9151-1d579ea4cf49' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation normalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8b1c0f3e-af01-5016-9151-1d579ea4cf49','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8b1c0f3e-af01-5016-9151-1d579ea4cf49' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd8d07109-aeb5-59fb-8c94-d1ce4f132eaa','Preservation pathway','A defined, documented route by which a given object or format is carried through preservation — the planned sequence of decisions and actions (selection, transfer or digitization, normalization, packaging, storage and future migration) chosen to keep its content accessible over time. Different formats or risk levels may follow different pathways set by a preservation plan.','A preservation pathway is the planned route an item takes to stay safe over time. It lists the steps in order. First pick it, then copy or digitize it. Put it in a chosen format, store it, and migrate it later. Different kinds of media can follow different routes.','It turns preservation planning into a repeatable, documented procedure so that similar items are handled consistently and no critical step is skipped.','A collection manager assigns fragile lacquer discs to an urgent pathway — clean, transfer to Broadcast WAV, checksum, package, store — that differs from the pathway used for born-digital files.','Preservation Workflow',ARRAY['Preservation transfer','Preservation normalization','Preservation triage','Preservation Description Information','Migration']::text[],ARRAY['Treating one pathway as fitting all media; carrier type, condition and risk should determine which pathway an item follows.','Confusing a pathway, which is the whole planned route, with a single step such as transfer or normalization.','Leaving the pathway undocumented, so handling becomes inconsistent and steps are missed.']::text[],ARRAY['Mapping distinct pathways for open-reel tape, lacquer discs and born-digital audio in a preservation plan.','Routing at-risk carriers onto a fast-tracked pathway ahead of stable ones.','Documenting the chosen pathway so any technician can follow the same steps.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d8d07109-aeb5-59fb-8c94-d1ce4f132eaa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation pathway'),'[^a-z0-9]','','g'));
