INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8dd1c4a6-d191-5c5d-952a-1b6a4e80ccf0','Preservation provenance','The documented history of a preserved object: its origin or source, the chain of custody, and every action or change applied to it since creation — including, for reformatted material, the original carrier, the transfer equipment and settings, and who performed each step. In OAIS it is the Provenance component of Preservation Description Information, and it underpins the authenticity and trustworthiness of the archived object.','Provenance is the life story of an item. It records where it came from, who has held it, and everything done to it since. For a digitized recording it also notes the original tape or disc and how it was copied. This history lets people trust the copy is genuine.','It gives future users evidence that a preserved object is authentic and unaltered except in documented ways, which matters when a digital surrogate stands in for a lost or fragile original.','During transfer the engineer logs the source carrier, machine, speed, alignment and any restoration, and stores that record as provenance metadata with the preservation master.','Preservation Metadata',ARRAY['Preservation Description Information','Preservation transfer','Fixity','Persistent identifier','Chain of custody']::text[],ARRAY['Recording only the final file and not the transfer chain; without provenance the surrogate''s authenticity cannot be demonstrated.','Confusing provenance, which is history and custody, with fixity, which proves the bits are unaltered; both are needed but answer different questions.','Editing or restoring a transfer without documenting it, which breaks the provenance record.']::text[],ARRAY['Logging deck, stylus, speed and equalization used to transfer a lacquer disc as provenance.','Using provenance to establish that a digital master is the authentic capture of a now-degraded original.','Tracing custody of a collection from donor to archive in the provenance record.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8dd1c4a6-d191-5c5d-952a-1b6a4e80ccf0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation provenance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8dd1c4a6-d191-5c5d-952a-1b6a4e80ccf0','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8dd1c4a6-d191-5c5d-952a-1b6a4e80ccf0' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de8064fd-37a1-54fb-9ec4-f4df7617fbd5','Preservation transfer','The controlled copying of content from an original, often obsolete or degrading carrier onto a new preservation carrier or file — for audio, typically the real-time playback of a disc, cylinder or tape and its capture as a high-resolution digital file. The aim is an unmodified, complete and accurate transfer that retrieves the best possible signal from the original for long-term preservation.','Preservation transfer means copying a recording off its old, fragile carrier onto a safe new one. For sound you usually play the tape or disc once, with care. You capture it as a high-quality digital file. The goal is to grab the best copy before the original decays.','Because every original carrier eventually degrades or becomes unplayable, transfer moves the content to a stable format while the signal can still be recovered, preserving it independently of the failing carrier.','A transfer engineer cleans and conditions a tape, plays it back on a calibrated machine, and records an unmodified Broadcast WAV preservation master that captures the fullest signal in a single pass.','Preservation Workflow',ARRAY['Preservation provenance','Preservation normalization','Preservation triage','Particulate occlusion','Preservation pathway']::text[],ARRAY['Applying noise reduction or equalization to the preservation master; the master should be an unmodified capture, with any processed versions kept separately.','UNSAFE: Playing a mould-affected or chemically degrading (acetate or nitrate) carrier without cleaning, PPE and professional advice; spores and degradation by-products are health hazards and the carrier can be damaged further.','UNSAFE: Baking or heat-treating a tape without following the documented manufacturer or archive procedure; incorrect temperatures damage the tape and mishandling hot media risks burns.','Rushing playback of a fragile carrier without conditioning, risking a ruined single-pass capture.']::text[],ARRAY['Digitizing an open-reel master to a Broadcast WAV preservation file.','Transferring a lacquer disc showing palmitic-acid bloom before it delaminates.','Capturing an unmodified master and then deriving a separate cleaned access copy.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de8064fd-37a1-54fb-9ec4-f4df7617fbd5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de8064fd-37a1-54fb-9ec4-f4df7617fbd5','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de8064fd-37a1-54fb-9ec4-f4df7617fbd5' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5fad30cd-eea5-5d20-82a3-cc9180800f68','Preservation triage','The systematic prioritisation of preservation work when resources are limited: assessing a collection''s carriers for condition, chemical stability, format obsolescence and value, then ranking them so the most at-risk and most significant recordings are transferred first. Modelled on medical triage, it accepts that not everything can be treated at once.','Archives rarely have time or money to save everything at once. Preservation triage means sorting items by urgency. Carriers that are decaying fast or hardest to play go to the front of the line. It borrows the idea from hospital triage.','It directs limited staff, equipment and funding to the recordings most likely to be lost soon, so the greatest amount of irreplaceable content is saved before it becomes unrecoverable.','A collection manager surveys carriers, scoring for degradation such as sticky-shed tape or exuding lacquer discs and for playback-format obsolescence, and schedules the highest-risk items for immediate transfer.','Preservation Workflow',ARRAY['Preservation transfer','Preservation pathway','Palmitic-acid exudation','Plasticizer loss','Preservation normalization']::text[],ARRAY['Digitizing the easiest or most-requested items first instead of the most at-risk; triage prioritises by urgency and risk, not convenience or popularity.','Assessing value but ignoring carrier chemistry; a stable-looking but chemically decaying carrier can fail suddenly and belongs high in the queue.','UNSAFE: Handling and sorting mouldy or chemically degrading carriers during a survey without gloves and respiratory protection; spores and degradation by-products are health hazards.']::text[],ARRAY['Surveying a mixed audio archive and ranking sticky-shed tapes and bloomed lacquer discs for urgent transfer.','Allocating a limited digitization budget to the most endangered formats first.','Deferring stable, easily-played carriers while prioritising obsolete, degrading ones.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5fad30cd-eea5-5d20-82a3-cc9180800f68' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation triage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5fad30cd-eea5-5d20-82a3-cc9180800f68','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5fad30cd-eea5-5d20-82a3-cc9180800f68' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c31b8456-03da-597f-b751-0c7b459deb47','Preservation watch','The ongoing, systematic monitoring of the technological, file-format, standards, and community environment around an archive''s holdings to detect changes that threaten continued access to and understandability of preserved content, such as format obsolescence, failing playback hardware, or shifts in the designated community''s knowledge. In the OAIS reference model it corresponds to the Preservation Planning functions Monitor Technology and Monitor Designated Community.','Preservation watch means keeping an eye on the outside world so old files stay usable. Staff watch for file types, playback machines, or software going out of date. Spotting a risk early lets them act before a recording can no longer be played.','It gives an archive early warning of obsolescence and other threats, turning preservation from a reactive rescue into a planned, proactive activity.','A preservation team subscribes to format registries and technology alerts, periodically reviews the formats and carriers in its collection, and flags any that are becoming obsolete for migration or fresh transfer.','Preservation Planning',ARRAY['Technology watch','File format obsolescence','Preservation planning','Migration','Designated community','Representation information']::text[],ARRAY['Treating preservation watch as a one-time survey rather than a continuous, ongoing process.','Watching only file formats while ignoring failing playback hardware and vanishing technical expertise.','Confusing preservation watch (monitoring the environment for risks) with fixity checking (verifying that stored bits are unchanged).']::text[],ARRAY['Noticing that a proprietary audio codec is no longer supported by current software and scheduling migration.','Tracking that the last working DAT machines are failing, prompting urgent transfer of DAT holdings.','Reviewing a format registry each year to reassess the obsolescence risk of files in the repository.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c31b8456-03da-597f-b751-0c7b459deb47' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Preservation watch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c31b8456-03da-597f-b751-0c7b459deb47','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c31b8456-03da-597f-b751-0c7b459deb47' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4072be49-566f-53bf-87a9-343db0858c72','Process metadata','Metadata that documents the processes applied to a digital object, especially the digitisation or transfer workflow: the signal chain and equipment used, the settings and parameters, the operators involved, dates, and any later processing. It records how the digital object was created and altered, supporting authenticity and future preservation decisions.','Process metadata is a record of how a digital file was made and changed. It lists the gear used, the settings, who did the work, and when. This history lets others trust the file and see what was done to it.','It ensures every step that creates or modifies a digital object is documented at the time it happens, preserving evidence of authenticity and giving future custodians the information they need to interpret or reprocess the file.','When transferring a tape, a technician records the make and model of the machine, the A/D converter, sample rate and bit depth, operator name, and date as process metadata, for example in the BWF coding-history field.','Metadata',ARRAY['Replay metadata','Provenance information','Coding history','Restoration metadata','Preservation master']::text[],ARRAY['Writing process metadata from memory after the fact instead of capturing it at the moment each step occurs.','Recording only the final format and omitting the signal chain, equipment, and settings that produced it.','Confusing process metadata (how the object was made and changed) with descriptive metadata (what the content is about).']::text[],ARRAY['Logging the full signal chain and converter settings during a tape-to-file transfer.','Documenting a later format migration so the file''s full processing history stays intact.','Populating the BWF coding-history field so downstream users can see how the audio was digitised.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4072be49-566f-53bf-87a9-343db0858c72' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Process metadata'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4072be49-566f-53bf-87a9-343db0858c72','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4072be49-566f-53bf-87a9-343db0858c72' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd1caa16e-db37-51c6-ad06-e84638b2be52','Provenance information','In the OAIS reference model, the component of Preservation Description Information that documents the history of the Content Information: its origin or source, any changes made to it since creation, and the chain of custody. It provides evidence supporting claims about the object''s authenticity.','Provenance information is the life story of a digital object. It says where the content came from, who has kept it, and how it has changed over time. This history is what lets people trust that the object is genuine.','It establishes trust and authenticity by showing a documented history of origin, custody, and change for the preserved content.','An archivist records the source of a recording, each institution that has held it, and every transfer or processing step, so a researcher can judge how faithful and authentic the file is.','OAIS Model',ARRAY['Preservation description information','Reference information','Representation information','Fixity','Process metadata']::text[],ARRAY['Confusing provenance information (history, custody, and changes) with reference information (identifiers used to name the content).','Starting the provenance record at ingest and losing the earlier history the producer should have supplied.','Assuming provenance alone proves authenticity, when it must be paired with fixity to show the bits are unchanged.']::text[],ARRAY['Documenting the custody chain of a donated collection from creator to archive.','Recording that a file was migrated to a new format and by whom.','Providing a researcher with the origin and handling history of a preserved recording.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d1caa16e-db37-51c6-ad06-e84638b2be52' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Provenance information'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd1caa16e-db37-51c6-ad06-e84638b2be52','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d1caa16e-db37-51c6-ad06-e84638b2be52' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ccda7542-64ee-5275-927a-8f50ec8fcbea','RF64','RF64 is an extended, 64-bit version of the RIFF/WAVE (and Broadcast Wave) file format standardised by the EBU as Tech 3306, designed to store audio files larger than the 4 GB limit of standard 32-bit RIFF. It replaces the ''RIFF'' identifier with ''RF64'' and adds a ''ds64'' chunk carrying 64-bit size and sample-count values; combined with a BWF ''bext'' chunk it is known as MBWF.','RF64 is a WAV file that can grow bigger than four gigabytes. Normal WAV files hit a size wall and stop, which is a problem for long or many-channel recordings. RF64 removes that wall while staying close to the familiar WAV format.','It lets long, high-resolution, or multichannel audio recordings exceed the 4 GB ceiling of ordinary WAV/BWF files while remaining broadly compatible with existing tools and metadata.','An archivist saving a long, high-sample-rate, or multichannel preservation master uses RF64 so a single continuous recording is not truncated or split when it passes 4 GB.','File Formats',ARRAY['Broadcast Wave Format','WAV','bext chunk','Coding history','Preservation master','Sample rate']::text[],ARRAY['Assuming a normal WAV/BWF file can exceed 4 GB, when it cannot without RF64.','Believing every audio application reads RF64, when older software may not recognise the RF64/ds64 structure.','Confusing RF64 (which removes the size limit) with simply raising bit depth or sample rate (which adds data but stays capped in plain WAV).']::text[],ARRAY['Capturing a multi-hour concert as a single uninterrupted preservation file.','Digitising many-channel material where the file would exceed 4 GB.','Choosing RF64/BWF as the archival container for high-resolution masters.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ccda7542-64ee-5275-927a-8f50ec8fcbea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('RF64'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ccda7542-64ee-5275-927a-8f50ec8fcbea','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ccda7542-64ee-5275-927a-8f50ec8fcbea' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3900c52f-09b2-59b7-a424-c70316675ee5','Radial cracking','A degradation mode of lacquer (acetate) instantaneous discs in which cracks radiate outward from the centre across the grooved surface, caused by the nitrocellulose lacquer coating shrinking as its plasticizer (castor oil) is lost while the rigid aluminium or glass base does not shrink. The resulting stress cracks the coating and can make it flake or peel away from the base (delamination).','Radial cracking is when an old lacquer record splits in lines running out from the middle. The soft top layer dries out and shrinks, but the hard base underneath does not. The strain cracks the surface, and pieces can lift or flake off.','Recognising radial cracking flags a lacquer disc that is actively failing, identifying a carrier whose audio must be transferred urgently before the coating flakes away and the recording is lost.','A transfer engineer inspecting a lacquer disc looks for radial cracks and lifting flakes, and prioritises the most cracked discs for immediate playback or touch-free optical transfer before further loss.','Carrier Degradation',ARRAY['Delamination','Lacquer disc','Palmitic acid exudate','Inherent vice','Optical scanning (IRENE)','Preservation master']::text[],ARRAY['UNSAFE: Playing a badly radially cracked lacquer disc on a turntable, where lifting flakes can catch the stylus, damage the surface, and destroy the only copy; a touch-free optical transfer is safer for such discs.','UNSAFE: Handling a disc exuding white palmitic-acid film, or its sleeve, with bare hands and no protection; wear nitrile gloves and avoid disturbing or inhaling any mould that degraded discs and housings can harbour.','Assuming cracks can be glued or flattened back down, when the shrunken coating cannot be returned to its original dimensions.','Confusing radial cracking of lacquer discs with the simple breakage of brittle shellac discs, which has a different cause.']::text[],ARRAY['Triaging a box of 1940s lacquer discs and pulling the radially cracked ones for urgent transfer.','Selecting optical (IRENE) scanning for a disc too cracked to play safely with a stylus.','Documenting radial cracks in condition metadata before attempting any transfer.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3900c52f-09b2-59b7-a424-c70316675ee5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Radial cracking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3900c52f-09b2-59b7-a424-c70316675ee5','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3900c52f-09b2-59b7-a424-c70316675ee5' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2f87bfa0-7aa0-5158-9a37-da009bbb9bff','Reference information','In the OAIS reference model, the component of Preservation Description Information that provides one or more identifiers by which the Content Information can be referred to uniquely and unambiguously, both within the archive and by external systems. Examples include assigned identifiers such as a catalogue number or a persistent identifier.','Reference information is the set of names or numbers that point to a stored object. It lets people and systems ask for exactly the right item without confusion. A book''s catalogue number is a simple everyday example.','It lets a specific preserved object be located, cited, and retrieved unambiguously, and lets outside systems link to it reliably over time.','An archivist assigns a persistent identifier to each preserved recording and records it as reference information, so catalogues, citations, and access systems all resolve to the correct object.','OAIS Model',ARRAY['Preservation description information','Provenance information','Persistent identifier','Fixity','Representation information']::text[],ARRAY['Confusing reference information (identifiers that name the content) with provenance information (its history and custody).','Relying on a file path or filename as a permanent identifier, when these change and break links.','Assigning identifiers that are not guaranteed to stay unique or persistent over the long term.']::text[],ARRAY['Minting a DOI or ARK for a digitised recording.','Cross-referencing an archival object to its catalogue record by a stable identifier.','Ensuring an external database can cite a preserved item unambiguously.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2f87bfa0-7aa0-5158-9a37-da009bbb9bff' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference information'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2f87bfa0-7aa0-5158-9a37-da009bbb9bff','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2f87bfa0-7aa0-5158-9a37-da009bbb9bff' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '720f0cb8-f855-53c0-9334-6424f3ec5ea1','Replay metadata','Metadata that documents the replay of an original carrier during transfer: the playback equipment used and its settings — such as turntable or tape machine, stylus or head, playback speed, and the replay equalisation curve — together with any alignment or corrections applied to recover the signal accurately. It records the objectively determined choices made to play an obsolete carrier.','Replay metadata records how an old recording was played back during transfer. It notes the machine, the speed, the equalisation setting, and the stylus or head used. This tells others the choices made to get the sound off the carrier.','It documents the parameters used to recover a signal from an obsolete carrier so the transfer is repeatable, letting future users judge it or redo it with different choices.','Transferring a disc, the engineer records the chosen playback speed, the replay equalisation curve, and the stylus size and profile as replay metadata alongside the audio file.','Metadata',ARRAY['Process metadata','Replay equalisation','Playback speed','Restoration metadata','Provenance information']::text[],ARRAY['Guessing replay parameters instead of determining them objectively and recording the values actually used.','Omitting the replay equalisation curve, without which the transfer''s tonal balance cannot be judged or corrected later.','Confusing replay metadata (how the carrier was played) with restoration metadata (later signal processing of the transferred file).']::text[],ARRAY['Recording the stylus profile and equalisation used to play a coarse-groove 78 rpm disc.','Noting the playback speed and equalisation chosen for an unlabelled tape.','Documenting head-alignment corrections made to recover a misaligned recording.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='720f0cb8-f855-53c0-9334-6424f3ec5ea1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Replay metadata'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '720f0cb8-f855-53c0-9334-6424f3ec5ea1','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='720f0cb8-f855-53c0-9334-6424f3ec5ea1' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9198367b-1cdb-5892-9937-550482c96558','Replication','In digital preservation, the practice of maintaining multiple independent copies of digital content on different systems and in geographically separated locations, so that no single failure, disaster, or corruption can destroy the content. It is typically paired with regular fixity checking so a corrupted copy can be detected and rebuilt from an intact one.','Replication means keeping several copies of a file in different places. If one copy is lost, damaged, or destroyed, another survives. Regular checks find a bad copy so it can be replaced from a good one.','It protects against data loss from hardware failure, disaster, human error, and corruption by removing any single point of failure.','A repository stores at least three copies of each preservation file on independent media in separate locations, checks their checksums on a schedule, and replaces any failed copy from a verified good one.','Digital Preservation',ARRAY['Fixity','Checksum','Bit preservation','Preservation master','Preservation watch','Repository succession plan']::text[],ARRAY['Keeping several copies in the same building or on the same system, so one fire or failure destroys them all.','Assuming copies stay intact without periodic fixity checks to catch silent corruption.','Confusing replication (independent copies for safety) with a single backup that is rarely tested or verified.']::text[],ARRAY['Storing preservation masters in three locations with different disaster risks.','Running scheduled checksum audits and repairing a corrupted copy from an intact one.','Joining a distributed digital preservation network so copies are held by multiple institutions.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9198367b-1cdb-5892-9937-550482c96558' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Replication'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
