INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f62d2205-523c-599b-9c47-d5c9c96ee7ac','Repository succession plan','A formal plan setting out what will happen to a digital repository''s holdings if the repository ceases to operate or its governing or funding body substantially changes scope, including contingency plans, escrow arrangements, and explicit agreements to transfer the content and responsibility for it to a named successor custodian. It is a core requirement for trustworthy digital repositories under ISO 16363.','A repository succession plan is a backup plan for the archive itself. It says who will take over the collection if the archive has to close. This makes sure the saved material is handed on safely instead of being lost.','It guarantees the long-term survival of preserved content beyond the life of any single institution by arranging in advance for an orderly transfer of custody.','A trusted repository names a successor organisation and signs an agreement covering how its digital holdings and related assets would be transferred if it shut down, and reviews this plan periodically.','Digital Preservation',ARRAY['Trustworthy digital repository','Designated community','Preservation planning','Custody','Replication','Provenance information']::text[],ARRAY['Treating a succession plan as optional, when it is a formal requirement for a trustworthy repository.','Naming a successor without a documented, agreed arrangement for the actual transfer of content and responsibility.','Writing the plan once and never reviewing it as funding, partners, or holdings change.']::text[],ARRAY['A grant-funded archive documenting who will inherit its collection when funding ends.','An institution auditing against ISO 16363 demonstrating its succession and contingency arrangements.','Transferring a closing repository''s holdings to a partner institution under a pre-agreed plan.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f62d2205-523c-599b-9c47-d5c9c96ee7ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Repository succession plan'),'[^a-z0-9]','','g'));
