SELECT '534c0f2a-a224-5dbe-a862-74571e036097','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='534c0f2a-a224-5dbe-a862-74571e036097' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b11c0cf2-6153-5527-b1b6-a004a14c9d42','Reversible intervention','A conservation principle holding that any treatment applied to an object should, as far as possible, be removable later without damage to the original, preserving future custodians'' options. Because few treatments are fully reversible, the related idea of re-treatability — not foreclosing future treatment — is applied alongside minimal intervention.','A reversible intervention is a fix you can undo later. It should not harm the original object. The goal is to keep future options open, in case a better method appears. Since a true undo is rare, staff at least try not to block later work.','It protects an object''s long-term integrity and future choices, ensuring today''s treatment does not permanently lock in a decision or damage the original.','When rehousing or treating a carrier, a technician chooses methods and materials that can be removed later, such as reversible adhesives and non-permanent labels, and avoids any step that permanently alters the original.','Conservation Principles',ARRAY['Minimal intervention','Preservation master','Restoration metadata','Inherent vice','Provenance information']::text[],ARRAY['UNSAFE: Using harsh or unapproved solvents to clean a carrier without ventilation, gloves, or eye protection, which can harm both the object and the worker; follow the tested, standards-based cleaning method and the solvent''s safety data sheet.','Assuming a treatment is fully reversible, when cleaning, consolidation, and many chemical treatments actually remove or absorb material permanently.','Altering the original carrier when the same goal could be met on a copy, breaking the reversibility principle.']::text[],ARRAY['Choosing a removable enclosure and non-permanent labelling for an archival tape.','Preferring signal processing on a copy over any permanent change to the original carrier.','Selecting a disc-cleaning method that leaves no lasting residue or alteration.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b11c0cf2-6153-5527-b1b6-a004a14c9d42' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reversible intervention'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b11c0cf2-6153-5527-b1b6-a004a14c9d42','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b11c0cf2-6153-5527-b1b6-a004a14c9d42' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3d8a5a85-bfff-5400-b46c-90e74e1e4bb9','Schema validation','The process of checking that a structured data file — typically XML or a metadata record — conforms to the rules declared in a formal schema, such as an XML Schema Definition (XSD). Validation confirms that required elements and attributes are present, correctly nested and ordered, and that their values match the declared data types and constraints.','A schema is a rulebook for how a data file must be built. Schema validation checks a file against that rulebook. It flags any part that breaks the rules. Archives use it to catch bad metadata early.','It enforces a shared, machine-readable specification for a file''s structure and content, so that metadata and data objects stay consistent, complete, and reliably exchangeable between systems.','During ingest an archivist runs metadata records (for example METS or PREMIS XML) through a validator against their schema, and corrects any records reported as invalid before they enter the repository.','Digital Preservation',ARRAY['Significant properties','Silent corruption','System dependency','Fixity check','Metadata']::text[],ARRAY['Confusing well-formedness (correct XML syntax) with schema validation (conformance to a specific schema''s rules).','Assuming a file that passes schema validation is also accurate or complete in meaning, when validation only checks structure against the rules.','Not recording which schema version a file was validated against, so later checks use the wrong rules.']::text[],ARRAY['Validating METS or PREMIS metadata against its schema before ingesting an item into a repository.','Rejecting a batch of records whose date fields do not match the schema''s required date type.','Checking a finding aid against its schema before publishing it online.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3d8a5a85-bfff-5400-b46c-90e74e1e4bb9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Schema validation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3d8a5a85-bfff-5400-b46c-90e74e1e4bb9','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3d8a5a85-bfff-5400-b46c-90e74e1e4bb9' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '900264a3-ef5b-58be-8420-f5b5107c3501','Signal extraction','The recovery of the encoded audio (or other) signal from a physical carrier by reading the modulation stored in it. For grooved media this increasingly includes non-contact optical methods that image the groove''s shape and mathematically reconstruct the waveform, rather than tracing it with a stylus.','Old records store sound as wiggles in a groove. Signal extraction means turning those wiggles back into an audio signal. New tools can even do this from photos of the groove. So a broken record can still be recovered.','It converts the information physically stored on an obsolete or damaged carrier back into a usable signal, letting content be recovered even from media too fragile or broken to play conventionally.','A preservation lab images a cracked lacquer disc with an optical scanner such as IRENE, then processes the images to extract an audio file without a stylus ever touching the surface.','Signal Recovery',ARRAY['Stylus-radius optimization','Stylus truncation','Surface crazing','Substrate corrosion','Significant properties']::text[],ARRAY['Believing a broken or delaminating disc is unrecoverable, when non-contact optical signal extraction can often read it.','Assuming stylus playback and optical extraction give identical results, when each handles damage and noise differently.','Extracting the signal but failing to document the transfer settings, so the result cannot be judged or repeated.']::text[],ARRAY['Recovering audio from a shattered lacquer disc by imaging the fragments and reconstructing the groove.','Extracting sound from a wax cylinder too fragile to survive a stylus.','Comparing an optical extraction with a stylus transfer to choose the cleaner result.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='900264a3-ef5b-58be-8420-f5b5107c3501' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Signal extraction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '900264a3-ef5b-58be-8420-f5b5107c3501','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='900264a3-ef5b-58be-8420-f5b5107c3501' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1f28cf27-6367-5c78-9646-6abce7e05acc','Significant properties','The characteristics of a digital object that must be preserved over time to ensure its continued accessibility, usability, and meaning. They are commonly grouped as content, context, structure, appearance, and behaviour, and they guide decisions when a file is migrated or reformatted.','A digital file has traits that give it meaning, like its text, layout, or links. Significant properties are the traits you must keep so the file still makes sense later. When you convert a file, you protect these first.','They define what actually has to survive a preservation action, so that migrations and format changes keep the essential meaning of an object rather than every incidental bit.','Before migrating a word-processing document to a preservation format, an archivist decides which significant properties — such as text, structure, and layout — must carry over, then checks the result against them.','Digital Preservation',ARRAY['System dependency','Schema validation','Storage diversity','Silent corruption','Signal extraction']::text[],ARRAY['Trying to preserve every property of a file equally, instead of identifying the ones essential to its meaning.','Assuming appearance is always significant, when for some records only content and context truly matter.','Deciding significant properties without consulting the records'' creators or users, and losing meaning that mattered to them.']::text[],ARRAY['Choosing which properties of an email — sender, date, body, attachments — must survive migration.','Deciding whether the exact font and layout of a document are essential or incidental.','Setting acceptance criteria for a format migration based on agreed significant properties.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1f28cf27-6367-5c78-9646-6abce7e05acc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Significant properties'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1f28cf27-6367-5c78-9646-6abce7e05acc','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1f28cf27-6367-5c78-9646-6abce7e05acc' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '68a58b7f-03af-5eed-af0b-3417508563b8','Silent corruption','The undetected alteration or loss of stored data that occurs without any error being reported by the storage system — for example bits changing through media decay, hardware faults, or transfer errors. Because nothing signals the change, it can spread into backups and go unnoticed until the data is needed.','Files can go bad on a drive with no warning. This is called silent corruption. Nothing tells you it happened. Archives run regular checks that compare a file''s fingerprint to catch it early.','Naming the risk drives routine fixity checking, so that corruption is caught and repaired from a good copy before every copy is affected.','An archive stores a checksum for each file and re-computes it on a schedule; a mismatch reveals silent corruption, and the file is restored from a verified backup.','Digital Preservation',ARRAY['Storage diversity','Schema validation','Fixity check','System dependency','Significant properties']::text[],ARRAY['Assuming a file is safe simply because it opened last time, when corruption can occur at any point in storage.','Overwriting good backups with a copy that already contains silent corruption because fixity was never checked.','Relying on a single copy, so a corrupted file has no verified version to restore from.']::text[],ARRAY['A yearly fixity check flags a master file whose checksum no longer matches its stored value.','Discovering during a restore that a backup was already corrupted and no clean copy exists.','Scrubbing a storage array so bad blocks are found and rewritten from good copies.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='68a58b7f-03af-5eed-af0b-3417508563b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Silent corruption'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '68a58b7f-03af-5eed-af0b-3417508563b8','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='68a58b7f-03af-5eed-af0b-3417508563b8' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '46d6da4d-8925-5621-8796-fa1c608208ec','Storage diversity','A digital-preservation strategy of holding multiple copies of content across different geographic locations and different, independent storage technologies or media. Diversity ensures that a single failure, disaster, or common-mode defect cannot destroy every copy at once.','Do not keep all your copies in one place or on one kind of drive. Storage diversity means spreading copies across different places and media. If one fails, the others survive.','It removes single points of failure, so a fire, flood, vendor collapse, or a flaw shared by one type of medium cannot take out all copies at the same time.','A repository keeps several copies of each object — on different media in separate buildings, mixing online and offline storage — and monitors each so a lost copy can be rebuilt from the others.','Digital Preservation',ARRAY['Silent corruption','System dependency','Fixity check','Significant properties','Schema validation']::text[],ARRAY['Keeping several copies but storing them in one building or on one type of drive, so one event destroys them all.','Assuming a cloud provider''s internal redundancy removes the need for independent copies you control.','Ignoring correlated failure, where identical drives bought together fail at about the same time.']::text[],ARRAY['Storing masters on spinning disk, on data tape, and at an offsite location for geographic separation.','Mixing online and offline copies so an error cannot propagate automatically to every copy.','Planning a migration off a storage vendor before its product or company becomes unsupported.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='46d6da4d-8925-5621-8796-fa1c608208ec' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Storage diversity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '46d6da4d-8925-5621-8796-fa1c608208ec','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='46d6da4d-8925-5621-8796-fa1c608208ec' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eea9523a-afaa-52ae-8673-d1856782b22f','Stylus truncation','The use of a stylus whose tip is truncated — ground with a small flat or blunted end — so that it rides on the groove walls and does not reach the bottom of the groove. In lateral coarse-groove disc replay this avoids worn or damaged groove bottoms and the debris that collects there, giving a cleaner signal and lower noise.','A worn record often has damage at the very bottom of its groove. A truncated stylus has a flat-tipped end. It rides higher on the groove walls and skips the damaged bottom. That gives cleaner sound.','It keeps the contact point on the undamaged, information-bearing groove walls rather than the vulnerable groove bottom, recovering a cleaner signal from worn discs.','A transfer engineer playing a worn 78 selects a truncated stylus of the right radius so the tip sits on the groove walls and skips the damaged bottom.','Groove Replay',ARRAY['Stylus-radius optimization','Signal extraction','Surface crazing','Substrate corrosion','Surface bloom']::text[],ARRAY['Using a truncated stylus on vertically cut media such as cylinders, where a truncated tip can ride on and damage the groove.','Assuming truncation removes the need to choose the correct tip radius, when both profile and radius still matter.','Expecting a truncated stylus to fix a badly worn disc completely, when it only avoids the groove bottom, not wall wear.']::text[],ARRAY['Playing a worn shellac 78 with a truncated stylus to avoid debris in the groove bottom.','Selecting a conical truncated tip for a visually poor lateral disc to reduce surface noise.','Deciding against a truncated stylus for a cylinder transfer because it would damage the vertical groove.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eea9523a-afaa-52ae-8673-d1856782b22f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stylus truncation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
