WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='eea9523a-afaa-52ae-8673-d1856782b22f' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa10435f-d822-5d03-8a32-8d108243f16f','Stylus-radius optimization','The practice of selecting the stylus tip radius, and profile, that best fits a particular disc''s groove so the tip contacts undamaged groove wall and recovers the cleanest signal. Archival replay keeps a range of styli — for lateral coarse-groove discs roughly 38 to 102 micrometres (1.5 to 4 mil) — and matches one to each record rather than using a single standard size.','Records come in many groove sizes. Stylus-radius optimization means picking a stylus tip that fits the groove best. The right size sits on good, unworn wall. It then picks up the most sound with the least noise.','Different eras and formats cut different groove dimensions, so choosing the right radius minimises surface noise and distortion and can lift the playback point above worn or damaged areas.','Before transferring an unfamiliar disc, an engineer tries several tip radii and profiles, listening for the one that gives the lowest noise and cleanest sound, and logs the stylus used.','Groove Replay',ARRAY['Stylus truncation','Signal extraction','Surface crazing','Substrate corrosion','Surface bloom']::text[],ARRAY['Using one standard stylus for every disc, instead of matching the tip radius to each record''s groove.','Choosing an elliptical tip for a badly worn disc, when a conical tip may track a poor groove better.','Not documenting the stylus radius and profile used, so a transfer cannot be judged or repeated.']::text[],ARRAY['Trying 2.6 mil and 3 mil tips on an early electric 78 to find the quieter playback.','Selecting a wider radius for a coarse-groove cylinder than for a microgroove LP.','Choosing an elliptical stylus for a clean disc and a conical one for a noisy, worn disc.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa10435f-d822-5d03-8a32-8d108243f16f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stylus-radius optimization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aa10435f-d822-5d03-8a32-8d108243f16f','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa10435f-d822-5d03-8a32-8d108243f16f' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6911b5d6-2821-5bf7-af39-457f393be4c9','Substrate corrosion','Corrosion of the metallic base layer of a recording carrier — most commonly the aluminium core beneath the recorded coating of a lacquer (acetate) instantaneous disc. Moisture and pollutants attack the metal, which can lift, crack, or delaminate the information-bearing layer above it and permanently degrade the recording.','Many old discs have a metal core under the recorded layer. Damp air can rust or corrode that metal. This is substrate corrosion. It can lift or crack the recorded layer and ruin the sound.','Recognising substrate corrosion tells an archivist that damage starts in the base metal, not just the surface, which affects how urgently a disc must be reformatted and how it should be stored.','An archivist inspecting lacquer and aluminium-core discs looks for dull, spotted, or lifting areas that signal corrosion of the metal base, and prioritises those discs for transfer.','Carrier Degradation',ARRAY['Surface bloom','Surface crazing','Signal extraction','Stylus truncation','Stylus-radius optimization']::text[],ARRAY['Blaming only the surface coating for damage, when corrosion of the metal core beneath is driving the failure.','Storing metal-core discs in damp conditions, which accelerates corrosion of the base.','UNSAFE: Handling corroded, mouldy, or crumbling discs without gloves and, where mould is present, a respirator; treat mould as a biohazard and follow the institution''s health-and-safety guidance.']::text[],ARRAY['Finding a spotty, dull aluminium-core disc and flagging it for urgent transfer.','Storing metal-based discs in cool, dry, stable conditions to slow corrosion.','Distinguishing base-metal corrosion from surface bloom during a condition survey.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6911b5d6-2821-5bf7-af39-457f393be4c9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Substrate corrosion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6911b5d6-2821-5bf7-af39-457f393be4c9','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6911b5d6-2821-5bf7-af39-457f393be4c9' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '84478672-45c4-5331-b665-e997c007ae98','Surface bloom','A whitish, greasy, crystalline film that forms on the surface of a grooved disc as fatty acids — chiefly palmitic acid — exude from the deteriorating coating. On lacquer (acetate) discs the bloom signals breakdown of the coating and is associated with the drying and delamination that follow.','Some old discs grow a white, greasy, powdery film on top. This is called surface bloom. It comes from chemicals leaking out of the disc. The film muffles sound and can harm the record if left.','The bloom is a visible warning of chemical breakdown, telling an archivist a disc is deteriorating and should be assessed, cleaned appropriately, and prioritised for transfer.','During a condition survey an archivist spots the greasy white film, recognises palmitic-acid bloom, and flags the disc for careful cleaning and prompt digitisation.','Carrier Degradation',ARRAY['Surface crazing','Substrate corrosion','Signal extraction','Stylus-radius optimization','Stylus truncation']::text[],ARRAY['Mistaking palmitic-acid bloom for mould or dust and cleaning it in a way that harms the coating.','UNSAFE: Cleaning lacquer discs with alcohol or other harsh solvents, which can dissolve or craze the nitrocellulose coating; follow published archival cleaning methods and use only approved agents with proper ventilation.','Leaving the bloom on the disc, allowing it to muffle the signal and contribute to further deterioration.']::text[],ARRAY['Seeing a white greasy film on a 1940s lacquer disc during accessioning.','Deciding on a safe cleaning method after identifying palmitic-acid bloom.','Prioritising a blooming disc for transfer before delamination sets in.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='84478672-45c4-5331-b665-e997c007ae98' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Surface bloom'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '84478672-45c4-5331-b665-e997c007ae98','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='84478672-45c4-5331-b665-e997c007ae98' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '28ff6594-b9f8-5055-8aaa-b3f0bfc3b9ac','Surface crazing','A fine network of cracks that develops across the surface coating of a disc — characteristically the lacquer layer of an instantaneous (acetate) disc — as the coating loses plasticiser, shrinks, and becomes brittle. The cracks disrupt the groove surface, raise surface noise, and can progress to flaking and delamination of the coating from its core.','As a lacquer disc ages, its coating shrinks and hardens. Tiny cracks then spread across the surface in a web. This is surface crazing. It adds noise and can lead to the coating flaking off.','Crazing is an early visible sign that a lacquer coating is drying and shrinking, warning that the disc is heading toward delamination and should be transferred while still playable.','An archivist examining a lacquer disc under raking light looks for the crazed crack pattern and prioritises a crazing disc for transfer before the coating begins to lift.','Carrier Degradation',ARRAY['Surface bloom','Substrate corrosion','Signal extraction','Stylus truncation','Stylus-radius optimization']::text[],ARRAY['Assuming a crazed disc is merely dirty and can be scrubbed clean, when the cracks are structural damage in the coating.','Delaying transfer of a crazing disc, allowing the cracks to progress to flaking and total loss of the recording.','UNSAFE: Attempting to flatten or repair a brittle, crazed disc with heat or solvents, which can shatter it or dissolve the coating; leave stabilisation to trained conservators.']::text[],ARRAY['Spotting a web of fine cracks on a lacquer disc during a preservation survey.','Choosing optical signal extraction for a crazed disc too fragile for a stylus.','Prioritising crazed lacquers for digitisation ahead of stable shellac discs.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='28ff6594-b9f8-5055-8aaa-b3f0bfc3b9ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Surface crazing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '28ff6594-b9f8-5055-8aaa-b3f0bfc3b9ac','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='28ff6594-b9f8-5055-8aaa-b3f0bfc3b9ac' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b492bdb4-c073-59ec-8bd1-02d75bfe39c2','System dependency','The reliance of a digital object or format on particular hardware, an operating system, or software in order to be rendered or used. Strong system dependencies make content vulnerable to technological obsolescence, because when the required system is no longer available the object can become inaccessible.','Some files only open with certain software or hardware. That reliance is a system dependency. When the old system dies, the file may become unreadable. Archives plan ahead to avoid this trap.','Identifying system dependencies shows what must be kept working, emulated, or migrated away from, so content does not become unreadable when its original environment disappears.','When accessioning a database or interactive work, an archivist records the software, versions, and hardware it needs, then plans migration or emulation to reduce that dependency.','Digital Preservation',ARRAY['Significant properties','Storage diversity','Silent corruption','Schema validation','Signal extraction']::text[],ARRAY['Saving only the data file while forgetting the software or hardware needed to open it.','Assuming today''s common software will still exist and open the file decades from now.','Choosing a proprietary format with heavy system dependencies when an open, well-supported one would serve.']::text[],ARRAY['Documenting the exact software and version a scientific dataset needs to be read.','Building an emulator so a work tied to obsolete hardware can still run.','Migrating records off a proprietary format before its software is discontinued.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b492bdb4-c073-59ec-8bd1-02d75bfe39c2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('System dependency'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b492bdb4-c073-59ec-8bd1-02d75bfe39c2','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b492bdb4-c073-59ec-8bd1-02d75bfe39c2' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3b8144ca-06c8-5adf-ad8a-98cd277e91cc','Technological diversity','A digital-preservation strategy of deliberately spreading a collection''s stored copies across heterogeneous storage media, hardware, software, file formats and geographic locations, so that no single technology, fault or event can compromise every copy at once. It reduces the risk of common-mode (correlated) failure by ensuring that a defect or disaster affecting one technology leaves copies on other, dissimilar systems intact.','Do not keep every copy on the same kind of gear in one place. Spread copies across different drives, systems, and sites. Then one fault or disaster cannot wipe out all of them at once.','It exists to remove single points of failure from long-term storage, so a bug, format obsolescence, hardware defect, cyber-attack or local disaster that hits one technology does not destroy all copies of the content.','An archive stores its master files on more than one storage system and medium, in separate locations under separate administration, rather than trusting a single vendor, drive model or data centre.','Digital Preservation',ARRAY['Technology watch','Redundancy','Migration','Refreshing','Fixity check','Storage diversity (copies spread across places and media; technological diversity is the broader spread that also includes dissimilar hardware, software and file formats)']::text[],ARRAY['Assuming that simply making several copies is enough, when identical copies on identical systems all share the same failure modes.','Confusing technological diversity (using dissimilar systems to avoid correlated failure) with mere redundancy (making more copies of the same kind).','Keeping all copies in one building or on one storage platform, so a single fire, flood or vendor fault can destroy every copy.']::text[],ARRAY['Designing a preservation repository that keeps one copy on spinning disk and another on LTO data tape at a remote site.','Choosing two different checksum and storage stacks so a software bug cannot silently corrupt every replica.','Reviewing a storage plan and rejecting it because all three copies live on identical drives in the same rack.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3b8144ca-06c8-5adf-ad8a-98cd277e91cc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Technological diversity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3b8144ca-06c8-5adf-ad8a-98cd277e91cc','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3b8144ca-06c8-5adf-ad8a-98cd277e91cc' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d80520f-b937-5f78-b1b6-9d4f75556b00','Technology watch','An ongoing digital-preservation activity in which an archive systematically monitors developments in file formats, software, hardware, storage media and standards to detect obsolescence and other threats to continued access. Its findings act as trigger points for preservation planning and action, such as format migration, before content becomes unreadable.','Technology changes fast, and old formats and gear stop working. Technology watch means keeping an eye on those changes. It warns the archive in time to move files to a safe new format before they become unreadable.','It exists so obsolescence is caught early, giving staff time to plan and carry out migration or other action while the tools to read the old content still exist.','A repository keeps a register of the formats and systems it depends on and reviews it against industry developments, flagging any format or device heading toward obsolescence for a preservation decision.','Digital Preservation',ARRAY['Technological diversity','Migration','Refreshing','File format obsolescence','Preservation planning']::text[],ARRAY['Treating preservation as a one-time act of copying files, rather than an ongoing watch for obsolescence.','Watching only file formats while ignoring the software, hardware and media needed to read them.','Detecting obsolescence too late, once the tools or devices needed to migrate the content are already gone.']::text[],ARRAY['Maintaining a watch list of audio codecs and flagging one whose decoder is no longer maintained.','Noticing that LTO tape drives read only a limited number of generations back, and scheduling migration before that window closes.','Reviewing whether a proprietary field-recorder format is still supported before it becomes unreadable.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d80520f-b937-5f78-b1b6-9d4f75556b00' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Technology watch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d80520f-b937-5f78-b1b6-9d4f75556b00','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d80520f-b937-5f78-b1b6-9d4f75556b00' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8431b9a8-6ce2-523c-9117-94935de620e6','Time reference','In a Broadcast Wave Format (BWF) file, the Time Reference is a 64-bit value carried in the broadcast audio extension (bext) chunk that records the position of the file''s first audio sample as a count of samples since midnight (00:00:00), interpreted using the file''s sampling rate. It provides a sample-accurate timestamp for placing the audio at the correct point on a timeline.','A Broadcast Wave audio file can store where it belongs in time. The time reference counts how many samples have passed since midnight, up to the first sample. That lets software drop the clip back onto a timeline in the right spot.','It exists so audio can be exchanged between systems and placed back on a timeline sample-accurately, without relying on separate paperwork or manual line-up.','During transfer or editing, an engineer relies on the bext Time Reference so a recovered take lands at the correct timecode position when imported into a workstation.','Preservation Metadata',ARRAY['Broadcast Wave Format','bext chunk','Timecode','WAVE64','Sample rate']::text[],ARRAY['Reading the Time Reference as clock time or timecode directly, when it is a sample count that must be divided by the sampling rate.','Assuming the value survives when a BWF file is exported to a plain WAV that drops the bext chunk.','Ignoring that a wrong sampling-rate assumption makes the derived time position wrong.']::text[],ARRAY['Importing archival BWF transfers into a DAW so each clip auto-aligns to its original timecode.','Reconstructing the running order of a multi-file location recording from each file''s Time Reference.','Diagnosing why clips land in the wrong place after the bext chunk was stripped.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8431b9a8-6ce2-523c-9117-94935de620e6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Time reference'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8431b9a8-6ce2-523c-9117-94935de620e6','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8431b9a8-6ce2-523c-9117-94935de620e6' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31a2fe5a-d8d5-5faa-9697-333fe2373ee4','Tracing distortion','A form of harmonic distortion inherent to grooved-record reproduction, arising because the finite, rounded tip of the playback stylus cannot exactly retrace the waveform cut by the sharp, chisel-edged cutting stylus. It grows as recorded wavelengths shorten, so it is worst at high frequencies and toward the inner grooves where linear groove speed is lowest, and it is reduced by a smaller effective tip contact such as an elliptical stylus.','A record is cut with a sharp, chisel-like tool but played back with a rounded tip. The rounded tip cannot follow the tiny wiggles exactly, so it adds distortion. This gets worse for high notes and near the middle of the disc.','Understanding tracing distortion shows a transfer engineer that some distortion is built into groove replay, guiding the choice of stylus shape and size to keep it as low as possible.','When transferring discs, an engineer selects an elliptical or otherwise small-contact stylus and handles inner-groove material carefully to keep tracing distortion low.','Disc Reproduction',ARRAY['Truncated elliptical stylus','Inner-groove distortion','Lateral-cut recording','Stylus tip radius','Turntable rumble']::text[],ARRAY['Confusing tracing distortion (from the tip not retracing the cut waveform) with tracking distortion or tracking error (from tonearm geometry and force).','Blaming a worn record for distortion that is actually inherent to the replay geometry.','Assuming a larger, more robust conical tip sounds cleaner, when a smaller elliptical contact usually lowers tracing distortion.']::text[],ARRAY['Choosing an elliptical stylus to reduce distortion when transferring a 78-rpm disc.','Explaining why the songs nearest a record''s centre sound harsher than the outer tracks.','Comparing conical and elliptical styli on the same disc during an archival transfer.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31a2fe5a-d8d5-5faa-9697-333fe2373ee4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tracing distortion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '31a2fe5a-d8d5-5faa-9697-333fe2373ee4','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='31a2fe5a-d8d5-5faa-9697-333fe2373ee4' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b75d074a-0342-5efd-b501-891a62258d67','Transcription disc','A disc sound recording produced for radio-broadcast and professional use rather than home sale, commonly called an electrical transcription. Typical examples are sixteen-inch discs played at 33 1/3 rpm, giving roughly fifteen minutes per side, issued as instantaneous lacquer discs or as pressed vinyl or shellac; some early examples were cut vertically and/or played from the inside out.','A transcription disc is a record made for radio stations, not for the public. They were often big sixteen-inch discs that played about fifteen minutes a side. Stations used them to record and share programmes.','It existed to let broadcasters record, distribute and replay complete programmes, syndicated shows and announcements before magnetic tape became standard.','An archivist meets transcription discs when digitising radio collections and must identify diameter, speed, groove type and cut direction before choosing a stylus and playback speed.','Obsolete Media',ARRAY['Lacquer disc','Vertical-cut recording','Lateral-cut recording','Variable-pitch cutting','Instantaneous disc']::text[],ARRAY['Assuming every transcription disc plays at 78 rpm, when most run at 33 1/3 rpm and some at other speeds.','Assuming all are lateral-cut and play outside-in, when some are vertically cut or start at the centre.','UNSAFE: Treating a lacquer transcription disc as sturdy shellac and cleaning it with alcohol, which corrodes the lacquer coating; lacquers need conservator-approved methods.']::text[],ARRAY['Digitising a station''s archive of sixteen-inch electrical transcriptions of live broadcasts.','Identifying whether a transcription disc is inside-start before cueing it.','Selecting the correct playback speed and stylus for a syndicated-programme transcription.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b75d074a-0342-5efd-b501-891a62258d67' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transcription disc'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b75d074a-0342-5efd-b501-891a62258d67','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b75d074a-0342-5efd-b501-891a62258d67' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b49d155-602d-5e9f-b67c-195b8a9f5de5','Truncated elliptical stylus','A playback stylus whose tip is ground to an elliptical (bi-radial) profile and then truncated, with its very bottom removed or flattened, so it makes contact on the groove walls rather than reaching the groove bottom. In archival disc transfer it is used to ride on undamaged wall surfaces and avoid debris and wear at the bottom of the groove, while keeping the small front-to-back contact of an elliptical tip for good high-frequency retrieval.','This is a record needle shaped like a narrow oval with its very tip flattened off. Because the bottom is removed, it rests on the groove walls, not the worn groove floor. That can give a cleaner sound from old or damaged records.','It exists to let a transfer engineer read the least-worn part of a groove, the walls, and skip the debris and damage at the bottom, improving signal recovery from lateral-cut discs.','During transfer an engineer keeps a range of stylus shapes and reaches for a truncated elliptical tip on lateral discs whose groove bottoms are worn or dirty.','Playback Hardware',ARRAY['Tracing distortion','Stylus tip radius','Conical stylus','Lateral-cut recording','Turntable rumble']::text[],ARRAY['Using a truncated stylus on cylinders or vertical-cut grooves, where it tracks on the groove edge and can damage the groove; truncated tips suit lateral discs.','Assuming one stylus size and shape fits every disc, instead of matching the tip to the groove''s width and condition.','Believing a truncated tip removes surface noise, when it only avoids the worn groove bottom and does not clean the record.']::text[],ARRAY['Selecting a truncated elliptical stylus to transfer a worn 78 whose groove bottom is damaged.','Building a stylus kit that covers different groove widths and wall conditions.','Comparing full and truncated tips to find which reads a damaged disc with least noise.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b49d155-602d-5e9f-b67c-195b8a9f5de5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Truncated elliptical stylus'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8b49d155-602d-5e9f-b67c-195b8a9f5de5','f2442389-2379-4010-8b5a-6835773b85c7',true
