INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7dd86756-6b9d-5081-97e0-d37749f60739','Turntable rumble','Low-frequency mechanical noise generated by a turntable''s bearing, motor and drive system and coupled through the platter into the pickup, where it is reproduced as a low rumbling beneath the audio. Its level is quantified by rumble measurement standards such as DIN 45539 (weighted and unweighted) and IEC 98; IASA guidance calls for transfer turntables with unweighted rumble better than 50 dB below the reference level.','A turntable''s motor and bearing vibrate a little as they spin. Those vibrations reach the needle and come out as a low rumble under the music. A good transfer turntable is built and measured to keep this rumble very low.','The measure exists to rate how quiet a turntable''s mechanics are, so archival transfers are not contaminated by low-frequency noise from the deck itself.','When choosing a deck for transfers, an engineer checks its rumble specification and may apply a rumble (subsonic) filter to remove low-frequency mechanical noise.','Disc Reproduction',ARRAY['Wow and flutter','Warp wow','Subsonic filter','Tracing distortion','Signal-to-noise ratio']::text[],ARRAY['Confusing rumble (low-frequency noise from the turntable mechanics) with wow and flutter (pitch variation) or with warp noise from the disc.','Assuming rumble comes from the record, when it originates in the deck''s bearing and motor.','Comparing rumble figures without noting whether they are weighted or unweighted, which changes the number a lot.']::text[],ARRAY['Specifying a low-rumble transfer turntable for an archival digitisation station.','Applying a subsonic filter to remove rumble before analogue-to-digital conversion.','Diagnosing a persistent low-frequency noise floor traced to a worn platter bearing.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7dd86756-6b9d-5081-97e0-d37749f60739' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Turntable rumble'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7dd86756-6b9d-5081-97e0-d37749f60739','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7dd86756-6b9d-5081-97e0-d37749f60739' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '45e92291-4dc7-5281-9089-cab9e56b5262','Variable-pitch cutting','A disc-mastering technique in which the cutting lathe continuously varies the groove pitch, the spacing between adjacent grooves, in response to the programme signal, widening the spacing for loud low-frequency passages that need large excursions and narrowing it for quiet passages. Driven by a preview (advance) signal read ahead of the cutter, it maximises both the playing time and the recordable level on a side.','When a record is cut, the grooves do not have to be evenly spaced. Loud, bassy parts need more room, so the machine spreads those grooves out and packs quiet parts closer. This fits more music on a side and lets it play louder.','It exists to get the longest playing time and the highest safe level onto a disc without adjacent grooves colliding during loud passages.','A mastering engineer sets up the lathe''s preview head and pitch control so the disc uses space efficiently, a fact a transfer engineer should know when judging why groove spacing varies across a side.','Disc Cutting',ARRAY['Vertical-cut recording','Lateral-cut recording','Transcription disc','Groove pitch','Tracing distortion']::text[],ARRAY['Confusing variable pitch (varying groove spacing) with variable depth (varying how deep the groove is cut).','Assuming groove spacing is always constant, so mistaking normal variable-pitch spacing for a fault.','Thinking variable pitch changes playback speed, when it only changes how grooves are spaced on the disc.']::text[],ARRAY['Explaining why groove spacing looks uneven across a long-playing side.','Mastering a long programme to a single disc side using variable pitch to fit the running time.','Assessing a transcription disc whose spacing tightens during quiet dialogue.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='45e92291-4dc7-5281-9089-cab9e56b5262' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Variable-pitch cutting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '45e92291-4dc7-5281-9089-cab9e56b5262','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='45e92291-4dc7-5281-9089-cab9e56b5262' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '170dba0a-49a0-5727-8cea-9f50324999c7','Vertical-cut recording','A mechanical sound recording in which the audio is cut as variations in the depth of the groove, so the stylus moves vertically (up and down); this is the hill-and-dale method. It is the format of phonograph cylinders and of vertical-cut discs such as Edison Diamond Discs and Pathe discs, in contrast to lateral-cut recording, where the modulation is side-to-side.','In a vertical-cut recording the sound is stored as up-and-down bumps in the bottom of the groove. The needle bounces up and down to read it. Edison cylinders and some old discs work this way, unlike normal records that wiggle side to side.','Recognising vertical cut matters because it needs a pickup and stylus set up for vertical motion and the correct equalisation, or the transfer will be wrong or noisy.','Before transfer an engineer checks whether a disc or cylinder is vertically cut, then configures the cartridge for vertical playback and selects a stylus that fits the groove bottom.','Disc Recording',ARRAY['Lateral-cut recording','Transcription disc','Wax-cylinder shaving','Truncated elliptical stylus','Groove pitch']::text[],ARRAY['Playing a vertical-cut disc or cylinder with a cartridge wired only for lateral motion, which loses or degrades the signal.','Assuming all discs are lateral-cut, and so misjudging Pathe or Edison Diamond Discs.','Using a truncated stylus on a vertical or cylinder groove, where it rides the edge and can damage the groove.']::text[],ARRAY['Configuring a stereo cartridge to sum for vertical playback of an Edison Diamond Disc.','Identifying a Pathe disc as vertically cut before choosing a stylus.','Transferring wax cylinders, which carry their signal as hill-and-dale modulation.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='170dba0a-49a0-5727-8cea-9f50324999c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vertical-cut recording'),'[^a-z0-9]','','g'));
