SELECT '170dba0a-49a0-5727-8cea-9f50324999c7','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='170dba0a-49a0-5727-8cea-9f50324999c7' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a92fdad5-1d5a-5e99-af16-a2b01adebac8','WAVE64','A WAV-derived uncompressed audio file format that stores the same linear PCM audio as a standard RIFF/WAVE file but uses 64-bit fields for its container and chunk sizes in place of the 32-bit size fields of RIFF. Because RIFF/WAVE size fields limit a file to about four gigabytes, WAVE64 lets a single file grow well beyond that limit, suiting long or high-channel-count recordings.','A normal WAV audio file cannot go past about four gigabytes. WAVE64 is a WAV-like format that uses bigger internal size counters, so the file can keep going. That helps with very long or many-channel recordings.','It exists to overcome the roughly four-gigabyte size ceiling of standard WAV, so long field recordings and high-track-count sessions can be stored in one continuous file.','A recordist or archivist uses WAVE64, or the related RF64/BW64, when a session''s audio would exceed the four-gigabyte WAV limit, avoiding a forced file split.','File Formats',ARRAY['Broadcast Wave Format','RF64','Time reference','Linear PCM','Sample rate']::text[],ARRAY['Assuming any WAV-family file can exceed four gigabytes, when standard RIFF/WAVE is capped near that size and needs WAVE64, RF64 or BW64 to go larger.','Expecting every editor and archive to accept WAVE64, when support varies and RF64/BW64 is the standards-based large-file choice.','Confusing WAVE64''s larger file capacity with higher audio quality, which it does not change.']::text[],ARRAY['A long unattended location recording that runs past four gigabytes and is captured as a single WAVE64 file.','Deciding between WAVE64 and RF64 for storing a large multichannel session.','Ingesting a WAVE64 field recording and checking the archive''s tools can read it.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a92fdad5-1d5a-5e99-af16-a2b01adebac8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('WAVE64'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a92fdad5-1d5a-5e99-af16-a2b01adebac8','f2442389-2379-4010-8b5a-6835773b85c7',true
