INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'faa5941b-e6d8-55e4-b53f-0a879f3ffa91','Warp wow','The slow, roughly once-per-revolution pitch fluctuation (a form of wow) produced when a warped or non-flat disc rises and falls under the stylus during playback. The warp displaces the stylus and tonearm vertically and alters the groove-to-stylus geometry each revolution, modulating the reproduced pitch.','If a record is warped and not flat, it rises and falls as it spins. The needle goes along for the ride, and the pitch wavers slightly once each turn. That slow wobble in pitch is called warp wow.','Naming warp wow helps a transfer engineer separate a fault in the disc, its warp, from faults in the turntable, so the right fix is applied.','Hearing a once-per-revolution pitch wobble, an engineer inspects the disc for warp and may flatten it or use a clamp or outer ring before transferring.','Disc Reproduction',ARRAY['Wow and flutter','Turntable rumble','Eccentricity','Disc warp','Subsonic filter']::text[],ARRAY['Blaming the turntable for a pitch wobble that is actually caused by a warped disc.','Confusing warp wow (from a bent disc) with eccentric wow (from an off-centre pressing or spindle hole).','Trying to flatten a warped disc with uncontrolled household heat, such as an oven, a car dashboard or direct sun, which can melt or permanently deform it; only controlled conservation flattening should be used.']::text[],ARRAY['Diagnosing a slow pitch wobble on transfer and tracing it to a dished LP.','Using an outer stabiliser ring or clamp to reduce warp wow during digitisation.','Deciding whether a warped acetate can be safely flattened before playback.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='faa5941b-e6d8-55e4-b53f-0a879f3ffa91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Warp wow'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'faa5941b-e6d8-55e4-b53f-0a879f3ffa91','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='faa5941b-e6d8-55e4-b53f-0a879f3ffa91' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '36aafe02-b58c-510a-b5b2-de65f88d61a6','Wax-cylinder shaving','The removal of a thin outer layer from the surface of a wax phonograph cylinder by paring it with a knife or shaving blade. Historically, office dictation systems shaved the recorded surface off so a cylinder could be reused for a new recording, and manufacturers shaved blanks to prepare a fresh recording surface; the process erases whatever was recorded and is irreversible.','Wax cylinders record sound in a soft wax surface. Shaving means scraping off the top layer with a blade. Old dictation machines did this to wipe a cylinder clean so it could be recorded on again.','Shaving existed to give a wax cylinder a fresh, smooth surface, either to reuse a dictation cylinder or to prepare a new blank, at the cost of destroying any earlier recording.','An archivist treats shaving as a warning: a surviving dictation cylinder may have been shaved and re-recorded many times, and must never be shaved again, only cleaned and transferred with conservation methods.','Cylinder Media',ARRAY['Vertical-cut recording','Wet-play transfer','Truncated elliptical stylus','Groove wear','Lacquer disc']::text[],ARRAY['Believing shaving is a cleaning or restoration step, when it removes the recorded surface and permanently erases content.','Assuming a dictation cylinder is a unique original, when many were shaved and re-recorded repeatedly.','UNSAFE: Handling mould-affected or degraded cylinders without protection; mould spores on cylinders can cause serious health problems and need proper precautions.']::text[],ARRAY['Assessing a batch of office dictation cylinders that were routinely shaved for reuse.','Explaining to a collector why a cylinder''s surface must never be shaved to clean it.','Documenting shave marks as evidence of a cylinder''s reuse history.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='36aafe02-b58c-510a-b5b2-de65f88d61a6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wax-cylinder shaving'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '36aafe02-b58c-510a-b5b2-de65f88d61a6','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='36aafe02-b58c-510a-b5b2-de65f88d61a6' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c96f9703-12a5-5167-95f5-084abca13fd2','Wet-play transfer','A disc-transfer technique in which a record is played while a fluid, traditionally purified (distilled or deionised) water, sometimes with a trace of wetting agent, is held in the groove, so the stylus tracks through liquid. The fluid floats out loose debris and fills fine scratches, lowering surface noise such as clicks and crackle and improving stylus contact; it is used mainly on worn or noisy shellac and vinyl discs during digitisation.','Some old records are played wet on purpose. A little clean fluid sits in the groove while the needle tracks through it. The liquid floats out grit and fills tiny scratches, so the record hisses and crackles less.','It exists to recover the cleanest possible signal from noisy or worn grooved discs by reducing surface noise at the moment of transfer, when the best single pass is being captured.','For a badly worn shellac disc, a transfer engineer may flood the groove with purified fluid and play it wet, capturing the quieter result, while keeping the disc wet through the whole pass.','Transfer Technique',ARRAY['Truncated elliptical stylus','Turntable rumble','Tracing distortion','Lacquer disc','Transcription disc']::text[],ARRAY['Wet-playing lacquer (acetate) discs or wax cylinders, whose surfaces water and solvents can corrode or dissolve; wet play is for shellac and vinyl and needs conservator-approved fluids.','Letting a wet-played disc dry with fluid residue left in the groove, which leaves deposits and attracts dirt.','UNSAFE: Using alcohol or other solvents as a play fluid without proper ventilation and testing; solvents are a chemical hazard and, on lacquers, a corrosion hazard, so follow conservation and safety guidance.']::text[],ARRAY['Wet-playing a heavily worn 78 to lower crackle before analogue-to-digital capture.','Choosing wet transfer for a noisy shellac disc while ruling it out for a lacquer.','Preparing purified water and a clean groove for a single wet transfer pass.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c96f9703-12a5-5167-95f5-084abca13fd2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wet-play transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c96f9703-12a5-5167-95f5-084abca13fd2','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c96f9703-12a5-5167-95f5-084abca13fd2' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6dce16f2-7905-58e7-9bd1-8b68e6da1651','Absolute speed error','The difference between the true average speed at which a tape or its playback machine runs and the nominal standard speed it is meant to run at, expressed as an absolute deviation. Because reproduced pitch rises and falls directly with speed while running time varies inversely with it, a constant absolute speed error shifts the whole recording uniformly in pitch and correspondingly alters its duration.','Tape is meant to run at a set speed. Absolute speed error is how far the real speed sits from that target. If the speed is off, the whole recording plays a little high or low in pitch.','Quantifying absolute speed error tells a transfer engineer whether a machine or a recording is running at the correct pitch, so the transfer can be reset to the intended speed.','During transfer an engineer measures speed against a known reference, such as a recorded tone or the frequency of recorded mains hum, then trims playback to remove any absolute speed error before capture.','Tape Speed',ARRAY['Actual tape speed','Wow and flutter','Reference tone','Beat-frequency interference','Brake drag']::text[],ARRAY['Confusing absolute speed error, a steady offset from the correct speed, with wow and flutter, which are short-term fluctuating speed variations.','Assuming the playback machine is at fault, when the original recorder may have run off-speed so the tape itself carries the error.','Correcting pitch by ear alone instead of referencing a known tone or the recorded mains-hum frequency.']::text[],ARRAY['Restoring an interview that sounds slightly sharp because the original recorder ran fast.','Using a recorded 50 or 60 Hz mains-hum component as a reference to reset the correct playback speed.','Documenting the measured speed offset in a transfer''s technical metadata.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6dce16f2-7905-58e7-9bd1-8b68e6da1651' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Absolute speed error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6dce16f2-7905-58e7-9bd1-8b68e6da1651','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6dce16f2-7905-58e7-9bd1-8b68e6da1651' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '826327b8-dc66-54cc-86fe-53a8f1ad010d','Actual tape speed','The real linear speed at which magnetic tape passes the heads during recording or replay, as distinct from the nominal (standard) speed marked on the machine. It can differ from nominal because of the original recorder''s calibration, motor or capstan wear, tape-pack effects, or a deliberately non-standard recording speed.','Actual tape speed is how fast the tape really moves past the heads. Machines have set speeds printed on them, but the true speed can drift. Knowing the real speed lets you play a tape at the right pitch.','Establishing the actual tape speed lets an engineer reproduce a recording at its true pitch and timing, rather than assuming the machine is exactly on speed.','An engineer verifies actual speed with a strobe, a reference tone, or the pitch of recorded mains hum, then trims playback so the transfer matches the original.','Tape Speed',ARRAY['Absolute speed error','Wow and flutter','Reference tone','Capstan','Brake drag']::text[],ARRAY['Assuming a machine set to 7.5 ips actually runs at exactly 7.5 ips without checking against a reference.','Ignoring that the original recording may have been made off-speed, so matching the standard speed still gives the wrong pitch.','Confusing a steady actual-speed offset with wow and flutter, which vary moment to moment.']::text[],ARRAY['Measuring a deck''s true speed with a strobe disc before an archival transfer.','Recovering the correct pitch from a field recording made on a battery machine whose speed sagged.','Matching actual speed for a 3.75 ips home recording captured on non-professional gear.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='826327b8-dc66-54cc-86fe-53a8f1ad010d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Actual tape speed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '826327b8-dc66-54cc-86fe-53a8f1ad010d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='826327b8-dc66-54cc-86fe-53a8f1ad010d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de91f0ea-6cc1-56d1-9cbc-cb85f367878d','Adaptive dehum','A hum-removal process that continuously analyses the signal and automatically tracks and suppresses power-line hum and its harmonics as their frequency or level drift over time, rather than relying on fixed notch filters set at preset frequencies. In iZotope RX the De-hum module offers such adaptive and dynamic operation, using large banks of dynamically variable notch filters.','Electrical hum from mains power can drift in pitch and loudness. Adaptive dehum listens as it goes and follows that drifting hum. It keeps removing the hum even when it does not sit at one steady pitch.','It exists to clean recordings whose hum wanders, so the filtering follows the interference instead of leaving gaps or cutting wanted audio at a fixed frequency.','An engineer uses adaptive dehum on a recording whose mains-hum frequency drifts, letting the tool track the hum instead of manually re-tuning notch filters.','Noise Reduction',ARRAY['Notch filter','Ground loop','Mains hum','De-noise','Beat-frequency interference']::text[],ARRAY['Setting a fixed notch and assuming it will keep removing hum that slowly drifts in frequency.','Removing the hum fundamental but leaving its harmonics, so a thin buzz remains.','Applying heavy hum removal that also carves out wanted low-frequency musical content.']::text[],ARRAY['Cleaning a lecture recording where 60 Hz hum drifts as the building''s power load changes.','Treating archival tape whose hum wanders because the original mains supply was unstable.','Removing wandering interference from a wireless-microphone recording before mixing.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de91f0ea-6cc1-56d1-9cbc-cb85f367878d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adaptive dehum'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de91f0ea-6cc1-56d1-9cbc-cb85f367878d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de91f0ea-6cc1-56d1-9cbc-cb85f367878d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4438d2f8-daf8-5333-9597-0557411a9e65','Asymmetric declipping','A declipping process that treats the positive and negative sides of a waveform independently, detecting a separate clip threshold for each and reconstructing the flattened peaks accordingly. It suits real-world clipping that is asymmetric, where positive and negative excursions were limited at different levels, as can happen with tape saturation, a DC offset, or single-ended overload.','When audio is too loud, its peaks get chopped flat. Sometimes the top and the bottom are chopped at different levels. Asymmetric declipping handles each side on its own and rebuilds both, so the repaired peaks match what was lost.','It exists so a declipper can correctly rebuild clipping that is not symmetrical, instead of assuming the same clip level top and bottom and mis-repairing one side.','Facing a transfer whose waveform is clipped harder on one polarity, an engineer uses a declipper that finds each side''s clip point and reconstructs both.','Distortion Repair',ARRAY['De-clip','Clipping','DC offset','Autoregressive interpolation','Tape saturation']::text[],ARRAY['Assuming all clipping is symmetric, so a single threshold mis-detects one polarity''s clipped peaks.','Declipping without first correcting a DC offset that is causing the asymmetry.','Pushing reconstruction so hard that rebuilt peaks overshoot and clip again.']::text[],ARRAY['Repairing a live recording whose positive peaks clipped before the negative ones.','Restoring an over-saturated tape transfer where one polarity flattened first.','Fixing a converter overload combined with a DC offset that skewed the clip levels.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4438d2f8-daf8-5333-9597-0557411a9e65' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Asymmetric declipping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4438d2f8-daf8-5333-9597-0557411a9e65','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4438d2f8-daf8-5333-9597-0557411a9e65' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4def9d0c-8a56-5cee-94d1-9433d8192963','Auto-stop foil','A short strip of electrically conductive metallic foil attached to or spliced into magnetic tape, commonly at the leader or ends, that completes or breaks a sensing circuit as it passes contacts in the transport and so triggers the machine''s automatic stop. It lets a deck detect the physical end of the tape and halt the reels without an audio signal being present.','A strip of metal foil is fixed onto the tape near its end. When it passes a sensor, it closes an electrical contact. That tells the machine the tape has run out, so it stops the reels by itself.','It exists to stop the transport automatically at the end of a tape, protecting the tape and machine from running off the reel or spilling.','When rehousing or splicing archival tape, a technician preserves or replaces the sensing foil so the deck still stops correctly at the ends.','Tape Transport',ARRAY['Leader tape','Block splice','Brake drag','Splicing tape','Actual tape speed']::text[],ARRAY['Removing or omitting the sensing foil during a splice, so the machine no longer stops at the tape''s end.','Confusing the conductive auto-stop foil with plain paper or plastic leader, which does not conduct.','Placing the foil in the wrong spot, so the transport stops in the middle of the programme.']::text[],ARRAY['Rehousing an open-reel tape and re-attaching sensing foil to the new leader.','Diagnosing a deck that will not stop at the tape end because the foil is missing.','Splicing fresh leader with a foil sensing strip onto a fragile archival reel.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4def9d0c-8a56-5cee-94d1-9433d8192963' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Auto-stop foil'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4def9d0c-8a56-5cee-94d1-9433d8192963','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4def9d0c-8a56-5cee-94d1-9433d8192963' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5f59861-d095-53d2-ae8b-a9c3ed61a1e8','Autoregressive interpolation','A model-based method for reconstructing missing or corrupted audio samples in which the signal is modelled as an autoregressive process, each sample a linear combination of preceding samples plus noise, and the unknown samples are estimated as the values that best fit that model to the surrounding good audio. It underpins click concealment and short-gap filling in audio restoration, using coefficients derived from the clean data on either side of the damage.','Sound usually follows a pattern. Each moment is close to the ones just before it. This method learns that pattern from the good audio next to a gap. Then it fills the missing part with values that fit the pattern.','It exists to fill short damaged or missing sections so convincingly that the repair follows the recording''s own local behaviour, avoiding an audible hole or click.','A restoration tool uses autoregressive interpolation to replace the samples under a detected click or a brief dropout with a modelled fit to the neighbouring audio.','Signal Reconstruction',ARRAY['Bidirectional interpolation','De-click','Broadband impulse','Spectral repair','Linear prediction']::text[],ARRAY['Expecting autoregressive interpolation to rebuild long gaps, when it is reliable only for short damaged sections.','Using too short a surrounding window, so the model fails to capture the signal''s behaviour and the fill sounds wrong.','Confusing model-based interpolation with a simple straight-line join between the gap''s endpoints.']::text[],ARRAY['Concealing a click on a transferred 78 rpm disc by modelling the audio around the damaged samples.','Filling a brief digital dropout in a recovered file.','Repairing a scratch-induced tick on a vinyl transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5f59861-d095-53d2-ae8b-a9c3ed61a1e8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Autoregressive interpolation'),'[^a-z0-9]','','g'));
