SELECT 'd5f59861-d095-53d2-ae8b-a9c3ed61a1e8','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5f59861-d095-53d2-ae8b-a9c3ed61a1e8' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '33a220a7-920b-52e4-bea1-598469a34195','Beat-frequency interference','Interference produced when two signals close in frequency combine, so their sum shows a slow amplitude pulsation at the difference (beat) frequency; if that difference falls within the audible range it is heard as a rising-and-falling tone or whistle. In restoration it arises from sources such as two nearby hum or tone components, or two bias or carrier oscillators, beating together.','When two tones are very close in pitch, they clash and make a slow throb. The throb happens at the gap between their two frequencies. If that gap is in our hearing range, you hear a wavering tone or whistle.','Recognising beat-frequency interference helps an engineer trace an unstable whistle or throb to two close sources, rather than treating it as one fixed tone.','Hearing a wavering whistle on a dub, an engineer suspects two oscillators or hum sources beating and addresses the source frequencies rather than notching one tone.','Interference',ARRAY['Bias whistle','Adaptive dehum','Heterodyne','Notch filter','Mains hum']::text[],ARRAY['Treating a beat as one steady tone and notching a single frequency, when two close sources cause it.','Confusing the audible beat, which is the difference frequency, with either of the two original tones.','Assuming the throb is tape wow, when it is actually two frequencies interfering.']::text[],ARRAY['A slow whistle heard when two tape machines with slightly different bias are dubbed together.','Two mains-hum sources at slightly different frequencies producing a slow throb.','Diagnosing a wavering tone that shifts as one interfering source drifts.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='33a220a7-920b-52e4-bea1-598469a34195' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Beat-frequency interference'),'[^a-z0-9]','','g'));
