SELECT '33a220a7-920b-52e4-bea1-598469a34195','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='33a220a7-920b-52e4-bea1-598469a34195' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da05edf0-a207-5143-8c21-011761ae4ab0','Bias whistle','An audible whistle caused by a recorder''s high-frequency bias signal, or a product of it, entering the audio band, typically when the bias of one machine beats with the bias or signal of another during dubbing, or when bias leakage heterodynes with another high-frequency component. Because the bias itself is ultrasonic, the whistle heard is usually the lower difference frequency created by two such signals beating.','Tape recorders add a steady high tone called bias that is too high to hear. If two machines'' bias tones mix, they can create a lower tone you can hear. That unwanted tone is the bias whistle.','Naming the bias whistle helps an engineer trace an intermittent high-pitched tone to bias interaction, especially during tape-to-tape copying, and fix it at the source.','When a whistle appears only while dubbing between two decks, an engineer checks bias interaction and machine setup rather than assuming the source tape is at fault.','Interference',ARRAY['Beat-frequency interference','Record bias','Heterodyne','Notch filter','Adaptive dehum']::text[],ARRAY['Assuming a whistle on the copy is on the original tape, when it appears only from bias interaction during dubbing.','Trying to hear the bias itself, which is ultrasonic; only the beat product is audible.','Notching the whistle after the fact instead of correcting the bias interaction at the source.']::text[],ARRAY['A faint whistle that shows up only when copying one open-reel tape to another.','Interference when a mistuned machine''s bias leaks into the signal path.','Checking machine grounding and bias setup after a whistle appears in a dub.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da05edf0-a207-5143-8c21-011761ae4ab0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias whistle'),'[^a-z0-9]','','g'));
