SELECT 'da05edf0-a207-5143-8c21-011761ae4ab0','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da05edf0-a207-5143-8c21-011761ae4ab0' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0fb9d96e-cf32-5623-b121-079baaf1f93d','Bidirectional interpolation','Interpolation that reconstructs a missing or damaged segment using known samples from both sides of the gap, the audio before and after it, rather than extrapolating from one side only. Using data on both sides constrains the estimate at each end, giving a smoother, more accurate fill than a one-sided, forward-only prediction.','To fill a gap in audio, you can use the sound on both sides of it. This method looks before and after the gap. Matching both ends gives a smoother repair than guessing from just one side.','It exists to make gap repairs match the audio on either side, avoiding the drift or mismatch that comes from predicting a fill from one direction only.','A de-click or gap-filling tool uses bidirectional interpolation so the reconstructed samples line up with both the pre-gap and post-gap audio.','Signal Reconstruction',ARRAY['Autoregressive interpolation','De-click','Broadband impulse','Spectral repair','Linear prediction']::text[],ARRAY['Using one-sided extrapolation for a gap that has good audio on both sides, giving a worse fill.','Applying it to gaps so long that even both-sided data cannot support a good estimate.','Assuming bidirectional means simply averaging the two endpoints, ignoring the signal''s shape.']::text[],ARRAY['Filling a short dropout that has clean audio immediately before and after it.','Reconstructing the samples under a click using the audio on both sides.','Repairing a brief tape-crease glitch bracketed by good signal.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0fb9d96e-cf32-5623-b121-079baaf1f93d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bidirectional interpolation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0fb9d96e-cf32-5623-b121-079baaf1f93d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0fb9d96e-cf32-5623-b121-079baaf1f93d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13891040-777f-5b78-8d0c-c4d6cba733d4','Block splice','A tape splice made with a splicing block: a grooved metal or plastic jig that holds the tape flat and provides an angled cutting guide, so the two ends are trimmed to a matching diagonal, butted together, and joined with splicing tape. The diagonal, butted (non-overlapping) join keeps the tape''s thickness even and reduces the audible thump as the splice passes the heads.','A splicing block is a small holder with a groove and an angled slot. Tape is laid in the groove and cut cleanly at an angle. The two ends meet edge to edge and are joined with splicing tape, making a neat, quiet join.','The block exists to make splices accurate and repeatable, with a clean diagonal butt join that passes the heads smoothly and does not add thickness.','When repairing a break or editing, a technician seats the tape in a splicing block, cuts both ends at the guide angle, butts them, and applies splicing tape.','Tape Editing',ARRAY['Splicing tape','Leader tape','Auto-stop foil','Butt splice','Tape transport']::text[],ARRAY['Overlapping the two ends instead of butting them, which doubles thickness and causes a bump at the heads.','Using ordinary sticky tape or the wrong cut angle instead of proper splicing tape and the block''s guide.','Letting adhesive squeeze out past the join, so it fouls the heads and guides.','UNSAFE: Handling the splicing-block razor carelessly across the open cutting channel, which can cut fingers; keep hands clear of the blade path.']::text[],ARRAY['Repairing a clean break in an archival open-reel tape before transfer.','Attaching fresh leader to a reel using a splicing block.','Editing out a damaged section and rejoining the good tape.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13891040-777f-5b78-8d0c-c4d6cba733d4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Block splice'),'[^a-z0-9]','','g'));
