SELECT '13891040-777f-5b78-8d0c-c4d6cba733d4','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='13891040-777f-5b78-8d0c-c4d6cba733d4' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '74d44e08-1f69-5c00-90cf-e40405a388ba','Brake drag','A fault or condition in which a tape transport''s reel brakes do not fully release, so residual braking friction drags on the reels during play or wind. The extra drag disturbs tape tension and can slow or modulate the tape''s speed, cause wow and uneven winding, and in severe cases stretch or damage the tape.','Tape machines have brakes that should let go fully when the tape plays. If a brake still rubs, it drags on the reel. That extra drag can pull the tape too tight, wobble the speed, or even stretch the tape.','Recognising brake drag helps a technician separate a transport fault from a tape or recording problem, so tension and speed issues are fixed at the machine.','Seeing uneven winding or hearing wow, a technician checks whether the brakes are dragging and services the transport before trusting a transfer.','Tape Transport',ARRAY['Wow and flutter','Tape transport','Actual tape speed','Auto-stop foil','Tape tension']::text[],ARRAY['Blaming wow on the tape when a dragging brake is disturbing tension and speed.','UNSAFE: Running a valuable or fragile archival tape through a machine with known brake drag, risking stretch, creasing or tape loss.','Adjusting playback speed to mask the symptom instead of servicing the sticking brake.']::text[],ARRAY['Diagnosing wow that clears up after the deck''s brakes are serviced.','Finding uneven tape packs caused by one reel''s brake not releasing.','Refusing to transfer a fragile tape until a brake-drag fault is fixed.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='74d44e08-1f69-5c00-90cf-e40405a388ba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Brake drag'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '74d44e08-1f69-5c00-90cf-e40405a388ba','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='74d44e08-1f69-5c00-90cf-e40405a388ba' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b505a1f5-b192-5d28-927d-698edd4b74b2','Broadband impulse','A very short-duration noise event whose energy is spread across a wide band of frequencies, heard as a click, tick or pop. Because a near-ideal impulse is brief in time, its spectrum is broad, so the disturbance contaminates a wide frequency range rather than sitting at a single tone; such events are the target of de-click and impulse-removal processing.','A broadband impulse is a very short burst of noise, like a click or pop. Because it is so brief, it splashes energy across many frequencies at once. That is why a single click can be heard right across the sound.','Understanding broadband impulses guides how they are removed: because they are short and wide-band, tools detect them in time and repair the affected samples rather than filtering one frequency.','An engineer treats clicks, ticks and pops on a disc or tape transfer as broadband impulses, using de-click detection and interpolation to remove them.','Noise Types',ARRAY['De-click','Autoregressive interpolation','Bidirectional interpolation','Spectral repair','Broadband noise']::text[],ARRAY['Trying to remove a click with a notch filter, when a broadband impulse is not a single frequency.','Confusing a broadband impulse, a brief wide-band click, with steady broadband hiss.','Setting de-click detection so aggressively that it also cuts sharp musical transients.']::text[],ARRAY['Removing ticks and clicks from a 78 rpm disc transfer.','Cleaning static-discharge pops from a location recording.','Distinguishing wanted drum transients from unwanted impulsive clicks.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b505a1f5-b192-5d28-927d-698edd4b74b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Broadband impulse'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b505a1f5-b192-5d28-927d-698edd4b74b2','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b505a1f5-b192-5d28-927d-698edd4b74b2' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d871393-3fc2-5de8-bd43-01cef04ff5f8','Butt splice','A tape splice in which two cut tape ends are joined end-to-end with no overlap, held together by adhesive splicing tape applied to the back (non-oxide) side of the join. The abutting ends are usually cut at a diagonal angle in a splicing block to smooth the transition, distinguishing it from an overlap splice.','It is a way to join two pieces of recording tape. You cut both ends and lay them end to end, with no overlap. A thin sticky tape on the back holds the join together.','It joins two tape ends for editing or repair without the doubled thickness and adhesive squeeze-out of an overlap, keeping the splice thin enough to pass cleanly over the heads and preserve signal continuity.','An archivist uses a butt splice made in a splicing block with proper splicing tape to rejoin a broken preservation tape or to remove damaged sections before transfer.','Tape Editing',ARRAY['Splicing tape','Splicing block','Leader tape','Overlap splice','Tape baking']::text[],ARRAY['Cutting the tape ends square (90 degrees) instead of at a diagonal, which makes the join more abrupt, more audible, and mechanically weaker.','Using ordinary office or pressure-sensitive tape rather than proper splicing tape, whose adhesive is made not to bleed or leave residue.','Placing the splicing tape on the oxide (recorded) side instead of the shiny back side, contaminating the magnetic surface.']::text[],ARRAY['Rejoining a preservation master tape that snapped during rewind, before making an archival transfer.','Removing a section of tape damaged by mould or shed oxide so the surrounding recording can still be played.','Attaching fresh leader tape to the head and tail of an archival reel to protect the recorded portion.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d871393-3fc2-5de8-bd43-01cef04ff5f8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Butt splice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d871393-3fc2-5de8-bd43-01cef04ff5f8','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d871393-3fc2-5de8-bd43-01cef04ff5f8' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ad20d712-c617-5685-8a4b-84964f1f3db7','Buzz burst','A short-lived episode of buzz, meaning electrical interference made up of a low-frequency fundamental (typically the mains frequency of 50 or 60 Hz) plus a dense series of strong upper harmonics, that appears intermittently rather than continuously in a recording.','Buzz is a harsh electrical noise. It has a low hum tone with many sharp higher tones stacked on top. A buzz burst is just a short spell of that noise, not a steady one.','Naming the artifact a buzz burst distinguishes brief, harmonic-rich mains interference from continuous hum or broadband hiss, which points the technician toward time-selective, harmonic-based removal rather than steady-state filtering.','On a spectrogram the technician sees a burst of horizontal harmonic bands, isolates that time region, and applies de-hum or de-buzz notch or comb filtering only where the buzz occurs.','Noise & Artifacts',ARRAY['Hum','De-hum','Comb-notch dehum','Ground loop','Harmonic']::text[],ARRAY['Treating a buzz that is rich in harmonics as if it were a pure hum and notching only the fundamental, leaving the audible upper harmonics untouched.','Applying broadband noise reduction across the whole file for a problem that occurs in short bursts, needlessly degrading the clean sections.','Confusing an intermittent buzz burst with a click or crackle, which are impulsive events needing de-click rather than harmonic filtering.']::text[],ARRAY['A dimmer or fluorescent fixture switching on introduces a short buzz into an otherwise clean location recording.','A momentary ground fault during an archival transfer injects a burst of mains buzz onto the digitized signal.','A poorly shielded cable picks up interference only while a nearby motor runs, producing recurring buzz bursts.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ad20d712-c617-5685-8a4b-84964f1f3db7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Buzz burst'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
