WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ad20d712-c617-5685-8a4b-84964f1f3db7' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd7d59c07-e725-555c-935e-1858f03b07c8','Capstan-rate component','A periodic speed-variation (wow-and-flutter) or modulation component in a tape reproduction whose repetition rate corresponds to the rotational frequency of the capstan, or an integer multiple of it, arising from capstan eccentricity, bearing runout, or motor cogging.','The capstan is the spinning shaft that pulls tape past the heads at a steady speed. If it is worn or slightly off-center, it makes the speed wobble once per turn. That regular wobble is the capstan-rate component.','Labelling a flutter component by its source rate lets an engineer trace unwanted pitch or speed modulation to the capstan specifically, so the right mechanical fault can be found or the artifact modelled and reduced.','When analysing wow and flutter, the technician looks for a spectral peak at the capstan rotation frequency to decide whether to service the transport or apply software wow-and-flutter correction.','Tape Transport',ARRAY['Capstan','Wow and flutter','Scrape flutter','Pinch roller','Pitch stability']::text[],ARRAY['Assuming all speed wobble comes from the capstan, when reel eccentricity, guides, or scrape flutter add components at other rates.','Confusing slow wow below a few hertz with faster flutter, and so misidentifying which moving part is responsible.','Trying to fix a mechanical capstan fault entirely in software instead of first cleaning or servicing the capstan and pinch roller.']::text[],ARRAY['A restorer hears a regular cyclic pitch waver on a transferred tape and measures a peak at the capstan''s turning frequency.','A maintenance technician diagnoses a worn capstan bearing by identifying flutter at the capstan rate.','Software wow-and-flutter repair is tuned by targeting the periodic component that matches the capstan rotation.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d7d59c07-e725-555c-935e-1858f03b07c8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capstan-rate component'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd7d59c07-e725-555c-935e-1858f03b07c8','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d7d59c07-e725-555c-935e-1858f03b07c8' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd4ceef3a-31f3-552f-99fb-57f76d68b77d','Capstanless recording','A recording produced on a tape transport that has no capstan-and-pinch-roller metering of speed, so linear tape speed is governed only by the driven reel or motor. Because linear speed then changes as the tape pack diameter grows, such recordings tend to exhibit speed and pitch drift across the reel.','Most tape decks use a capstan, a shaft that keeps tape moving at one steady speed. Some cheaper or older machines skip it and just wind tape onto the reel. Then the speed slowly changes as the reel fills, so the pitch drifts.','Recognising a source as capstanless warns the archivist that its speed is inherently unstable and drifts with reel diameter, so a constant-speed assumption during transfer would reproduce the wrong pitch.','When transferring a capstanless recording, the technician expects pitch to drift between the start and end of the reel and may use a reference tone or software to correct the speed.','Tape Transport',ARRAY['Capstan','Wow and flutter','Pitch drift','Speed correction','Reel-to-reel']::text[],ARRAY['Assuming a capstanless recording plays at a single fixed speed, and so not checking for pitch drift across the reel.','Correcting the pitch at only one point rather than along the whole recording, leaving the ends off-pitch.','Blaming the playback deck for speed error that was actually baked into the original capstanless recording.']::text[],ARRAY['Digitising a dictation or field recording made on a simple reel machine that lacked a capstan.','A collection tape shows drifting pitch across the reel because the original recorder was capstanless.','An engineer applies variable-speed correction to compensate for drift in a capstanless source.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d4ceef3a-31f3-552f-99fb-57f76d68b77d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capstanless recording'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd4ceef3a-31f3-552f-99fb-57f76d68b77d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d4ceef3a-31f3-552f-99fb-57f76d68b77d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '99cb2dce-03c4-5369-ab64-d116ad4d187b','Carrier leakage','Unwanted passage of a high-frequency carrier signal, such as the recorder''s ultrasonic bias oscillator or the FM/modulation carrier of a frequency-modulated medium, into the audio output path, where it appears as residual ultrasonic energy or, through intermodulation, as audible artifacts.','Tape machines use a very high, silent tone called bias while recording. If some of that tone leaks into the output, it can add noise or spoil the sound. That unwanted leakage is called carrier leakage.','The term flags that ultrasonic carrier energy is contaminating the signal, so the transfer chain must low-pass filter or trap it to prevent aliasing and intermodulation when the audio is digitized.','During transfer a technician may measure strong ultrasonic content and insert a low-pass or bias-trap filter so the carrier does not alias into the audible band on digitization.','Noise & Artifacts',ARRAY['Bias','Bias trap','Intermodulation distortion','Aliasing','Low-pass filter']::text[],ARRAY['Digitizing without an anti-alias or bias-trap filter, so ultrasonic carrier leakage folds down into the audible band as spurious tones.','Mistaking intermodulation products from carrier leakage for faults in the original recording.','Assuming carrier energy above the hearing range is harmless, and ignoring the intermodulation and aliasing it can cause.']::text[],ARRAY['A tape transfer shows strong energy near the bias frequency, prompting the engineer to add a bias trap.','Hi-fi videotape or an FM-based medium leaks its modulation carrier into the audio output during capture.','Ultrasonic carrier leakage aliases into audible spurious tones after analog-to-digital conversion.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='99cb2dce-03c4-5369-ab64-d116ad4d187b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Carrier leakage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '99cb2dce-03c4-5369-ab64-d116ad4d187b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='99cb2dce-03c4-5369-ab64-d116ad4d187b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d9390ea-2cee-5c68-a6b1-047222e81c9e','Cassette skew','In compact cassette reproduction, skew is deviation of the tape from perpendicular alignment as it passes the head, so the head gap no longer sits at the correct azimuth angle to the recorded track. It produces high-frequency loss and time (phase) differences between the two channels.','In a cassette, the tape should meet the play head at a right angle. Skew is when the tape leans or twists a little instead. This dulls the high notes and can throw the two stereo channels out of step.','Understanding skew tells the operator that dull, phasey sound may come from tape-to-head geometry rather than the recording itself, so it is corrected by adjusting azimuth or the tape path, not by equalization.','Transferring a cassette, the technician adjusts head azimuth and checks the shell and guides while watching a phase meter, minimizing skew to restore high-frequency response.','Tape Transport',ARRAY['Azimuth','Azimuth error','Head alignment','Phase (stereo)','High-frequency loss']::text[],ARRAY['Trying to cure skew-induced dullness with treble boost, which lifts hiss but does not recover the lost high frequencies.','Setting azimuth by one channel''s level alone while ignoring the phase relationship between the two channels.','Blaming the tape or recording when a warped cassette shell or worn guides are actually causing the skew.']::text[],ARRAY['A dubbed cassette sounds muffled because it was recorded on a machine with a different head azimuth.','During transfer the stereo image collapses when summed to mono, revealing inter-channel skew to correct.','Re-shelling a cassette into a precision housing to reduce tape skew before archival capture.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d9390ea-2cee-5c68-a6b1-047222e81c9e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cassette skew'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7d9390ea-2cee-5c68-a6b1-047222e81c9e','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7d9390ea-2cee-5c68-a6b1-047222e81c9e' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0cac597b-574f-5884-99b4-97a26ab3dfe2','Channel substitution','A restoration technique in which a damaged, missing, or heavily degraded channel of a multichannel recording is replaced with content copied from another channel, for example substituting a clean channel for its damaged counterpart in a stereo pair, or duplicating one good channel to both outputs.','Sometimes one side of a stereo recording is ruined while the other is fine. Channel substitution copies the good side to replace the bad one. You may even use the good channel for both sides.','It recovers a usable result when one channel is beyond repair, trading true stereo separation for the intelligibility and cleanliness of the surviving channel.','Facing a stereo tape whose left channel is destroyed by dropout, the engineer routes the intact right channel to both outputs, or patches in the good channel for the damaged span.','Restoration Techniques',ARRAY['Dropout','Mono fold-down','Channel-selective transfer','Stereo separation','Spectral repair']::text[],ARRAY['Collapsing to a substituted mono channel across the whole piece when only a short span is actually damaged.','Forgetting to document that a channel was substituted, misleading later users about the recording''s true stereo content.','Substituting a channel that is itself out of phase or delayed, creating comb-filtering when the channels are summed.']::text[],ARRAY['One channel of a stereo cassette is lost to severe dropout, so the good channel is copied across the gap.','A tape''s second track is unrecorded or corrupted, and the usable track is duplicated to both outputs.','A brief burst of damage on one channel is patched from the corresponding clean channel.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0cac597b-574f-5884-99b4-97a26ab3dfe2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Channel substitution'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0cac597b-574f-5884-99b4-97a26ab3dfe2','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0cac597b-574f-5884-99b4-97a26ab3dfe2' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2687f9f1-8597-5b2c-9511-5d718c3047fc','Channel-selective transfer','An archival transfer approach in which individual channels or tracks of a multichannel or multitrack carrier are captured selectively, one or a chosen subset at a time, rather than digitizing all channels together, so each can be optimized or only the wanted tracks retained.','Some tapes hold several tracks side by side. Channel-selective transfer captures only the tracks you want, or handles each one on its own. This lets you set the best playback for each track.','It lets the engineer capture only the recorded or wanted tracks of a carrier and set azimuth, level, and noise-reduction decoding correctly for each track, avoiding crosstalk or unwanted blank tracks.','Playing a half-track tape or a multitrack master, the technician selects and transfers each recorded track separately, aligning the head and levels for that track.','Archival Transfer',ARRAY['Track configuration','Channel substitution','Crosstalk','Azimuth','Multitrack']::text[],ARRAY['Transferring all tracks with one head setting, when azimuth or level differs between tracks recorded on different machines.','Capturing blank or erased tracks as if they were content, wasting storage and confusing the record.','Ignoring crosstalk from an adjacent track that bleeds into the selected channel.']::text[],ARRAY['Digitizing only the two recorded tracks of a quarter-inch tape that also has unused track positions.','Transferring each track of a multitrack master separately to set optimal alignment per track.','Selecting the correct track pair on a tape recorded in an unusual or mixed format.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2687f9f1-8597-5b2c-9511-5d718c3047fc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Channel-selective transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2687f9f1-8597-5b2c-9511-5d718c3047fc','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2687f9f1-8597-5b2c-9511-5d718c3047fc' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23b57a69-c525-532e-9350-64f0dab7ce1c','Characteristic uncertainty','The condition, common with undocumented archival carriers, in which the original recording''s technical characteristics (playback speed, equalization curve, track or channel format, and any noise-reduction encoding) are unknown and must be inferred, introducing uncertainty into how the item should be reproduced.','To play an old tape or disc correctly, you need to know things like its speed and tone settings. Often no one wrote these down. Characteristic uncertainty means you are not sure of those settings and must work them out.','Naming this uncertainty reminds the engineer that playback parameters are assumptions to be tested, so choices about speed, equalization, and decoding are documented and, where possible, verified against internal evidence rather than guessed silently.','Facing an unlabeled reel, the technician tries standard speeds and equalization curves, listens for correct pitch and tonal balance, and records which settings were chosen and why.','Archival Transfer',ARRAY['Playback equalization','Tape speed','Track configuration','Noise reduction','Provenance']::text[],ARRAY['Assuming a default speed or equalization curve without testing, and so transferring the item at the wrong pitch or tone.','Failing to document the assumed characteristics, so later users cannot tell measured fact from an educated guess.','Treating one plausible setting as certain when internal evidence such as pitch, tone, or reference tones was never checked.']::text[],ARRAY['An unlabeled reel arrives with no note of its recording speed or equalization.','A disc of unknown origin could follow one of several groove standards, so the correct curve is uncertain.','A tape may or may not carry Dolby encoding, and no documentation confirms which.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23b57a69-c525-532e-9350-64f0dab7ce1c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Characteristic uncertainty'),'[^a-z0-9]','','g'));
