SELECT '23b57a69-c525-532e-9350-64f0dab7ce1c','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23b57a69-c525-532e-9350-64f0dab7ce1c' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23a1acac-d8fd-5ad4-82f1-e1593248fb9b','Click tail','The brief decaying portion of an impulsive click that follows its initial sharp onset, meaning the short ring-out or residual energy trailing the transient; in de-click processing it also refers to the leftover fragment of a click that remains when interpolation does not span the click''s full duration.','A click is a tiny, sharp pop in the sound. It often has a short ringing bit right after the sharp part. That trailing bit is the click tail, and it can be left behind if the repair is too short.','Recognising that a click has a tail tells the restorer to detect and interpolate the whole event, not just its peak, so no audible residual is left after de-click processing.','After running de-click, the technician zooms into the waveform or spectrogram to check for leftover click tails and widens the interpolation region or re-treats them if found.','Noise & Artifacts',ARRAY['Click','De-click','Interpolation','Crackle','Transient']::text[],ARRAY['Setting the de-click region to cover only the click''s peak, which leaves an audible tail behind.','Raising sensitivity so aggressively to catch tails that clean transients in the music get damaged too.','Mistaking a natural short resonance in the recording for a click tail and removing wanted signal.']::text[],ARRAY['A de-clicked vinyl transfer still ticks faintly because click tails were not fully interpolated.','The engineer manually extends a repair region to capture the ring-out after each click.','Checking a restored 78 rpm transfer for residual click tails before delivery.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23a1acac-d8fd-5ad4-82f1-e1593248fb9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Click tail'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '23a1acac-d8fd-5ad4-82f1-e1593248fb9b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23a1acac-d8fd-5ad4-82f1-e1593248fb9b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2f28865a-e7db-572a-8e54-a04eb3415b6f','Comb-notch dehum','Removal of hum or buzz using a comb filter built from narrow notch filters placed at the interference''s fundamental frequency (typically 50 or 60 Hz mains) and at each of its harmonics, so the whole harmonic series is attenuated while the frequencies between the notches are preserved.','Mains hum is not one tone but a low tone plus copies stacked up the scale. This method drops a narrow notch on each of those tones at once, like the teeth of a comb. It removes the hum while keeping the sound in between.','Because electrical hum and buzz are made of related, evenly spaced tones, a single comb of notches tuned to the fundamental and its harmonics removes the whole series efficiently while doing little damage to the wanted audio between notches.','In a de-hum module the technician sets the base frequency to the mains fundamental and enables harmonic notches, then trims the number and depth of notches to erase the hum without thinning the tone.','Restoration Processing',ARRAY['Hum','Notch filter','Harmonic','De-hum','Ground loop']::text[],ARRAY['Notching only the fundamental and leaving the harmonics, so a buzzy hum remains audible.','Setting the base frequency slightly off the true mains frequency, so the notches miss and the hum persists.','Using notches so deep or wide that music energy near those frequencies is hollowed out.']::text[],ARRAY['Removing 60 Hz hum and its harmonics from a dialogue recording made near mains equipment.','Cleaning ground-loop buzz from an archival transfer using a harmonic comb of notches.','Suppressing lighting-dimmer buzz that spans the mains fundamental and many harmonics.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2f28865a-e7db-572a-8e54-a04eb3415b6f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Comb-notch dehum'),'[^a-z0-9]','','g'));
