SELECT '2f28865a-e7db-572a-8e54-a04eb3415b6f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2f28865a-e7db-572a-8e54-a04eb3415b6f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '55709f46-f5cf-5fd0-815a-d6897b489ada','Compander breathing','An audible artifact of companding noise-reduction systems, such as dbx or Dolby, in which the background noise floor rises and falls in sympathy with the program level, because the expander raises gain during quiet passages and lowers it during loud ones, modulating the residual hiss so it seems to breathe.','Some noise-reduction systems turn the sound up in quiet moments and down in loud ones. This can make the background hiss swell up and then fade with the music. That slow rise and fall of hiss is called breathing.','The term names a specific failure mode of companders, alerting the engineer that audible hiss modulation comes from the noise-reduction system''s gain action, often mistracking, rather than from the source, so it is addressed at the decoding stage.','Hearing hiss swell up under quiet dialogue on a Dolby or dbx tape, the technician checks that the correct decoder and calibration level are used, since mismatched decoding worsens breathing.','Noise Reduction',ARRAY['Companding','Compander pumping','Noise reduction','Dolby','Noise floor']::text[],ARRAY['Blaming the recording or tape for breathing that is actually the noise-reduction decoder mistracking.','Decoding with the wrong noise-reduction type or reference level, which exaggerates the breathing.','Trying to mask breathing with more noise reduction instead of fixing the decoding or calibration.']::text[],ARRAY['A dbx-encoded tape decoded at the wrong level shows the hiss floor pumping up in the pauses.','Transferring a Dolby B cassette without decoding, so the noise behaviour breathes unnaturally.','Quiet passages of an archival recording reveal the noise floor swelling and fading with the music.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='55709f46-f5cf-5fd0-815a-d6897b489ada' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compander breathing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '55709f46-f5cf-5fd0-815a-d6897b489ada','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='55709f46-f5cf-5fd0-815a-d6897b489ada' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '800072d6-2786-5ee4-8da4-0273898697db','Compander pumping','An audible artifact of companding systems in which the overall signal level surges and dips audibly as the compressor and expander act on program dynamics, typically faster and more obvious than breathing, often caused by a loud transient forcing a rapid gain change or by encode/decode mistracking.','A compander squeezes the sound up and down to fight noise. If it reacts too fast or is set up wrong, you can hear the loudness jump and drop. This audible surging is called pumping.','Naming pumping identifies rapid, audible level modulation as a compander behaviour, guiding the engineer to correct the decoding, timing, or calibration rather than treating the surges as part of the recording.','When loud notes make the level lurch on a companded transfer, the technician verifies the matching decoder and alignment level, since mismatches make the gain pump.','Noise Reduction',ARRAY['Companding','Compander breathing','Noise reduction','Attack and release','dbx']::text[],ARRAY['Confusing pumping, which is audible level surging, with breathing, which is noise-floor modulation, and so mis-diagnosing the cause.','Using the wrong decoder or alignment level, which makes a companded transfer pump on loud passages.','Assuming the pumping is a performance dynamic rather than a noise-reduction tracking error.']::text[],ARRAY['A dbx tape decoded without proper level calibration pumps on loud drum hits.','A companded broadcast recording surges in level whenever the speech gets loud.','Mismatched encode and decode chains make an archival transfer''s loudness lurch audibly.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='800072d6-2786-5ee4-8da4-0273898697db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compander pumping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '800072d6-2786-5ee4-8da4-0273898697db','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='800072d6-2786-5ee4-8da4-0273898697db' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25cd3e94-b03e-5a0e-8ede-25849b89d8bb','Composite restoration','A restoration approach in which a single best version of a recording is assembled from more than one source copy or transfer pass, splicing together the least-damaged segments of each so that damage in one source is covered by cleaner material from another. The result is a composite master more complete or higher in quality than any individual surviving source.','Sometimes no single copy of an old recording is perfect. You take the best parts from several copies. Then you join them into one clean version. Each copy covers the damaged spots in the others.','It exists to reconstruct the most complete, highest-quality version possible when every surviving source is damaged, incomplete, or noisy in different places.','An engineer restoring a disc or tape aligns two or more copies and edits between them, using each source to fill dropouts, skips, or noise bursts that the others lack.','Restoration Method',ARRAY['Differential groove recovery','Declicking','Decrackling','Diagonal splice','Provenance']::text[],ARRAY['Assuming the newest or cleanest-looking copy is automatically the best source for every passage, rather than comparing all copies section by section.','Editing between sources without matching level, speed/pitch, and equalisation, so the joins are audible.','Failing to document which source each segment came from, destroying the provenance of the composite master.']::text[],ARRAY['Reconstructing a complete disc side by taking clean passages from two worn pressings of the same recording.','Combining two tape copies of a broadcast so a dropout on one is covered by the other.','Filling a skip or lock-groove gap on a damaged LP using a second copy transferred at the same speed.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25cd3e94-b03e-5a0e-8ede-25849b89d8bb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Composite restoration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '25cd3e94-b03e-5a0e-8ede-25849b89d8bb','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25cd3e94-b03e-5a0e-8ede-25849b89d8bb' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '455b039e-41e8-56ee-a805-a2f4ea6a95fc','Conductive leader','Leader tape made from, or treated to be, electrically conductive (antistatic), spliced to the ends of or between sections of a magnetic tape. Its conductivity drains static charge that builds as tape moves over guides and heads, reducing static-attracted dust, static-discharge clicks, and layer-to-layer sticking.','Tape rubbing over the machine builds up static, like a balloon on your hair. Static pulls in dust and can cause crackle. Conductive leader tape is the special non-recording tape on the ends. It lets that static drain away safely.','It exists to bleed off static electricity generated during winding and playback, protecting the recording from dust attraction, static clicks, and static-related handling problems.','When repairing or re-leadering a reel, an archivist splices fresh conductive (antistatic) leader onto the head and tail so charge dissipates and the first and last program material is protected.','Tape Materials',ARRAY['Leader tape','Timing leader','Diagonal splice','Splice','Print-through']::text[],ARRAY['Replacing conductive antistatic leader with ordinary plastic leader, which can build static and attract dust.','Expecting leader tape to carry audio; it is non-magnetic and stores no signal.','Attaching leader with a sloppy or overlapping splice that catches on guides and heads.']::text[],ARRAY['Re-leadering a fragile archival reel before playback so static does not pull dust onto the oxide.','Adding conductive leader to mark and protect the start of each program section on a reel.','Diagnosing recurring static clicks during winding and tracing them to missing or non-conductive leader.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='455b039e-41e8-56ee-a805-a2f4ea6a95fc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Conductive leader'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '455b039e-41e8-56ee-a805-a2f4ea6a95fc','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='455b039e-41e8-56ee-a805-a2f4ea6a95fc' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3751ac30-f77d-5ab9-acc6-f6cb71567e1a','Contemporaneous transfer note','Documentation created at the same time as (contemporaneous with) a preservation transfer, recording the equipment, settings, carrier condition, decisions, and anomalies observed during the transfer. Because it is made in the moment rather than reconstructed later, it carries strong evidentiary and provenance value for the resulting file.','While you copy an old tape or disc, you write down what you did as you go. You note the machine, the settings, and any problems. Writing it in the moment, not from memory later, makes the record trustworthy.','It exists to capture the technical history and human decisions of a transfer while they are fresh, so future users can judge how faithful the digital copy is to the original.','During a transfer the operator logs playback speed, equalisation curve, noise-reduction decoding, machine and serial number, and any dropouts or damage, saving the note with the preservation master.','Archival Documentation',ARRAY['Provenance','Preservation metadata','Dolby lineup','Composite restoration','Transfer']::text[],ARRAY['Writing the transfer note from memory hours or days later, which weakens its accuracy and evidentiary value.','Recording only the file name and date while omitting the playback settings needed to interpret the transfer.','Storing the note separately from the file so the two become disconnected over time.']::text[],ARRAY['Logging the equalisation curve, speed, and noise-reduction settings chosen for a tape as it is being transferred.','Noting a visible splice, mould spot, or dropout at a specific timecode during a disc transfer.','Recording which noise-reduction system was decoded so a later engineer can reproduce or reverse the choice.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3751ac30-f77d-5ab9-acc6-f6cb71567e1a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Contemporaneous transfer note'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3751ac30-f77d-5ab9-acc6-f6cb71567e1a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3751ac30-f77d-5ab9-acc6-f6cb71567e1a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0693ab78-e943-5e55-b96e-c2d920c4384f','Crosstalk print','An unwanted contamination in which a faint copy of the signal from one track or channel appears in another, arising from inter-track bleed at the head and/or magnetic print-through between adjacent layers of wound tape. It is heard as a low-level ghost of neighbouring program material beneath the wanted signal.','On tape, sound from one track can leak faintly into another. It can bleed at the playback head, or print through between wound layers. Either way you hear a soft ghost of the wrong track underneath the real sound.','As a diagnostic term it lets technicians distinguish faint ghosting as track-to-track contamination from echo or noise, guiding head alignment and storage that minimise it.','When a technician hears a faint duplicate of an adjacent track, they check head alignment, test for print-through, and store the reel to limit further printing.','Tape Defect',ARRAY['Print-through','Crosstalk','Azimuth','Pre-echo','Post-echo','Tape storage']::text[],ARRAY['Mistaking a faint ghost of another track for tape echo or reverb rather than crosstalk or print-through.','Trying to remove it with heavy noise reduction, which damages the wanted signal while barely touching the ghost.','Storing reels in warm conditions or wound incorrectly, which increases print-through over time.']::text[],ARRAY['Hearing a quiet copy of the left channel inside the right channel of an old master tape.','Detecting a faint pre-echo of loud program material a moment before it arrives.','Assessing a multitrack reel where one track bleeds faintly into its neighbour.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0693ab78-e943-5e55-b96e-c2d920c4384f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crosstalk print'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0693ab78-e943-5e55-b96e-c2d920c4384f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0693ab78-e943-5e55-b96e-c2d920c4384f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9430d083-078a-536f-97c5-94e6531d16c4','Cue foil','A short strip of metallic (usually aluminium) foil adhered to magnetic tape that triggers an automatic transport function when it passes a sensor, typically by bridging sensing contacts or by reflecting or interrupting a photocell, to stop the transport, switch modes, or mark a cue or locate point.','A small metal foil sticker is stuck onto the tape. When it passes a sensor on the machine, it triggers an action. It can auto-stop the tape or mark a spot to find later. It works like a bookmark the machine can feel.','It exists to let a tape machine detect specific points on the tape automatically, so it can stop, switch modes, or locate cues without an operator watching.','An engineer places sensing foil at the end of program material or at a cue so the transport auto-stops or auto-locates; an archivist must recognise and document these markers before transfer.','Tape Materials',ARRAY['Leader tape','Conductive leader','Timing leader','Splice','Diagonal splice']::text[],ARRAY['Confusing sensing or cue foil with a splice or a fault and removing it, losing an original cue marker.','Assuming the foil carries signal; it is non-magnetic and only triggers the machine.','Leaving old foil in place during transfer so it wrongly auto-stops a machine that still reads it.']::text[],ARRAY['Finding metal foil on an archival reel and documenting its position before playback.','A tape machine auto-stopping unexpectedly because it sensed a cue foil mid-reel.','Adding sensing foil so a duplicator stops at the end of program material.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9430d083-078a-536f-97c5-94e6531d16c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue foil'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9430d083-078a-536f-97c5-94e6531d16c4','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9430d083-078a-536f-97c5-94e6531d16c4' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d3493b9-a633-5b38-84e2-ae6e7c8ec64e','Cyclic speed error','A speed, and therefore pitch, variation that repeats at a regular period, typically synchronised to a rotating component such as an eccentric capstan, pinch roller, reel hub, or turntable spindle. Unlike random speed error, its periodic nature, often once per revolution, makes it both diagnosable and, in software, correctable.','This is a wobble in playback speed that repeats on a steady beat. It usually comes from a spinning part that is slightly off-centre. Because the wobble is regular, you can spot its pattern and often fix it. Random speed changes are much harder.','Identifying speed error as cyclic points to a mechanical cause and lets restorers track and cancel the repeating pitch movement using a stable reference tone.','A restorer measures the pitch of a sustained tone or a bias or pilot frequency, sees a repeating rise and fall, and applies pitch-tracking correction locked to that period.','Speed Defect',ARRAY['Wow and flutter','Capstan','Pinch roller','Pitch correction','Pilot tone']::text[],ARRAY['Confusing cyclic (periodic) speed error with random wow and flutter, which need different correction approaches.','Assuming all speed error is a recording fault when a worn or dirty capstan and pinch roller on the replay machine may cause it.','Correcting pitch by ear on music alone, when a steady reference tone reveals the true repeating error.']::text[],ARRAY['Hearing a once-per-revolution wow on a disc caused by an off-centre spindle hole.','Measuring a repeating pitch wobble on a tape traced to an eccentric capstan.','Using software pitch tracking to remove a regular flutter locked to reel rotation.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d3493b9-a633-5b38-84e2-ae6e7c8ec64e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cyclic speed error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7d3493b9-a633-5b38-84e2-ae6e7c8ec64e','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7d3493b9-a633-5b38-84e2-ae6e7c8ec64e' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '982362f4-39ff-5c76-98d1-93ce198b5c7d','Declicking','An audio-restoration process that detects short, high-amplitude impulsive events, such as clicks, pops, and ticks, and repairs them by interpolating replacement samples from the surrounding waveform. It targets isolated transient defects such as disc ticks, scratches, digital errors, and edit clicks without altering the continuous underlying signal.','Old records and edits can add sharp clicks and pops. Declicking finds each quick click. It then patches that tiny spot using the sound just before and after it. The steady music underneath is left alone.','It exists to remove short impulsive noises heard as clicks or ticks, restoring clean playback without dulling or thinning the wanted audio.','An engineer runs a de-click module over a disc transfer or damaged file, adjusting sensitivity so genuine clicks are removed while sharp musical transients are preserved.','Digital Restoration',ARRAY['Decrackling','Declip reconstruction','Spectral repair','Interpolation','De-noise']::text[],ARRAY['Setting sensitivity so aggressively that sharp musical transients such as drums or consonants are mistaken for clicks and dulled.','Using de-click to remove steady broadband hiss, which is the job of de-noise, not de-click.','Applying heavy de-click in one pass instead of gentler, repeated passes, creating audible artifacts.']::text[],ARRAY['Cleaning ticks and pops from a vinyl LP transfer before mastering a reissue.','Removing edit clicks left at splice points in a digitised tape.','Repairing isolated digital dropouts or clicks in a recovered file.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='982362f4-39ff-5c76-98d1-93ce198b5c7d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Declicking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '982362f4-39ff-5c76-98d1-93ce198b5c7d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='982362f4-39ff-5c76-98d1-93ce198b5c7d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '136c5d6d-f7df-5197-ac6e-1343787b2cc9','Declip reconstruction','A restoration process that repairs clipping distortion by reconstructing the waveform peaks flattened when a signal exceeded the maximum level of a recorder, converter, or channel. The algorithm detects clipped, flat-topped regions and estimates and rebuilds the missing peak shape, lowering overall level to make headroom for the restored peaks.','When sound is recorded too loud, the tops of the waves get chopped flat. That flattening sounds harsh and distorted. De-clip finds the flat tops and rebuilds the missing peaks. It also turns the level down to make room for them.','It exists to reduce the harshness of clipping by restoring plausible peak shapes, recovering clarity from over-recorded material that cannot be re-recorded.','An engineer applies de-clip to an over-level recording or a hot transfer, setting the clip threshold where flattening begins and checking that rebuilt peaks sound natural.','Digital Restoration',ARRAY['Declicking','Clipping','Headroom','Spectral repair','De-noise']::text[],ARRAY['Expecting de-clip to fully restore badly clipped audio; it estimates the lost peaks and cannot recover true detail.','Setting the clipping threshold wrongly so unclipped audio is altered or real clipping is missed.','Forgetting that de-clip lowers level, then allowing the signal to clip again later in the chain.']::text[],ARRAY['Rescuing an interview recorded too hot on a handheld recorder.','Reducing clipping distortion on a live board-feed transfer.','Repairing over-modulated peaks on an archival broadcast tape.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='136c5d6d-f7df-5197-ac6e-1343787b2cc9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Declip reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '136c5d6d-f7df-5197-ac6e-1343787b2cc9','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='136c5d6d-f7df-5197-ac6e-1343787b2cc9' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1ddbf85f-73de-5071-b00f-efd790cb5eda','Decrackling','A restoration process that removes dense, low-level crackle, large numbers of small, closely spaced impulsive events, such as the surface noise of shellac and vinyl discs or the crackle of degraded optical film sound. It detects and interpolates many minute transients that are too numerous and small to treat individually as clicks.','Old discs often have a fine, busy crackle under the music. It is made of many tiny clicks too small to remove one by one. Decrackling smooths out that whole layer of little crackles. It leaves the music sitting on top.','It exists to clear the continuous fine crackle that de-click leaves behind, reducing surface-noise texture without dulling the recording.','After de-clicking a disc transfer, an engineer applies de-crackle to thin the residual surface crackle, balancing noise reduction against loss of high-frequency detail.','Digital Restoration',ARRAY['Declicking','De-noise','Spectral repair','Surface noise','Interpolation']::text[],ARRAY['Pushing de-crackle too hard, which removes high-frequency detail and dulls the recording.','Using de-crackle instead of de-noise to fight steady hiss, which it is not designed to do.','Skipping de-click first, so large clicks overwhelm the de-crackle process.']::text[],ARRAY['Reducing the fine crackle of a shellac disc after removing the big clicks.','Cleaning surface-noise crackle from a worn LP reissue transfer.','Treating crackle on a degraded optical film soundtrack.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1ddbf85f-73de-5071-b00f-efd790cb5eda' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decrackling'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1ddbf85f-73de-5071-b00f-efd790cb5eda','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1ddbf85f-73de-5071-b00f-efd790cb5eda' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b24fb21a-cc42-5152-9ab0-9ac3117de9a1','Deplosive processing','A restoration process that detects and attenuates plosives, the brief bursts of low-frequency energy produced when breath from consonants such as p and b strikes a microphone at close range. It reduces the low-frequency thump of each plosive while leaving the rest of the speech or vocal intact.','Say a hard P close to a mic and a puff of air hits it. That makes a low thump called a plosive. De-plosive finds each thump and turns it down. The rest of the voice stays normal.','It exists to fix distracting low-frequency pops in recorded speech and vocals after the fact, when a pop filter or better microphone technique was not used.','A dialogue or vocal editor runs de-plosive over problem words, or targets individual plosives, dialling in low-frequency attenuation so the pop softens without thinning the voice.','Digital Restoration',ARRAY['De-noise','Spectral repair','High-pass filter','Declicking','Pop filter']::text[],ARRAY['Using a broad high-pass filter that thins the whole voice instead of targeting only the plosive.','Over-processing so plosive consonants lose their natural punch and clarity.','Confusing plosives (breath pops) with sibilance (harsh s sounds), which needs de-essing instead.']::text[],ARRAY['Softening p pops in a close-mic voiceover recorded without a pop filter.','Cleaning plosives from an archival radio interview.','Fixing breath thumps on a lead vocal during restoration for reissue.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b24fb21a-cc42-5152-9ab0-9ac3117de9a1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Deplosive processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b24fb21a-cc42-5152-9ab0-9ac3117de9a1','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b24fb21a-cc42-5152-9ab0-9ac3117de9a1' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4ba4d5f1-0637-5931-be2e-93a3561e2ab4','Diagonal splice','A tape splice in which the cut and join run at a diagonal, commonly around 45 degrees or a shallower angle, across the tape rather than at 90 degrees to its length. The angled join crosses the recorded tracks gradually, softening the level and phase discontinuity so the splice passes the head with less audible click, and it increases the bonding surface area.','To join two pieces of tape, you cut and tape them together. A diagonal cut crosses the tape at a slant, not straight across. The slant makes the join pass the playback head smoothly. That means less of a click, and a stronger bond.','It exists to make edits and repairs on magnetic tape as inaudible and mechanically strong as possible, by spreading the join across the tracks instead of hitting them all at once.','Using a splicing block, an editor cuts both tape ends in the block''s diagonal channel, butts them together, and bonds them with splicing tape for music edits and reel repairs.','Tape Editing',ARRAY['Splice','Splicing block','Butt splice','Leader tape','Conductive leader']::text[],ARRAY['Using ordinary sticky tape or too much adhesive instead of proper splicing tape, which oozes and fouls heads and guides.','Overlapping the two tape ends rather than butting them edge to edge, causing a bump and a dropout.','UNSAFE: handling the razor blade or single-edge cutter carelessly in the splicing block, risking cuts.']::text[],ARRAY['Making an inaudible music edit between two takes on quarter-inch tape.','Repairing a broken archival reel before transfer.','Splicing fresh leader onto the head and tail of a reel.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4ba4d5f1-0637-5931-be2e-93a3561e2ab4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Diagonal splice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4ba4d5f1-0637-5931-be2e-93a3561e2ab4','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4ba4d5f1-0637-5931-be2e-93a3561e2ab4' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c8d83f2e-6069-50ad-9756-3f3222891f88','Differential groove recovery','A disc-restoration technique that treats the two walls of a record groove as separate signals and combines or selects between them to recover audio and reject noise. For a laterally cut mono groove played with a stereo pickup, both walls carry the same wanted signal in phase but wall-specific damage and vertical noise out of phase, so summing the channels reinforces the signal and cancels much of the noise; where one wall is more damaged, the cleaner wall can be favoured.','A record groove has two walls, left and right. On a mono record both walls hold the same music. Damage and rumble often sit on just one wall. By adding the two walls together, the music adds up and a lot of the noise cancels out. You can also lean on the cleaner wall.','It exists to pull the best possible signal from a worn or damaged disc by exploiting the physical fact that wanted signal and much groove-wall damage behave differently across the two walls.','An engineer transfers a mono disc with a stereo cartridge, then sums to mono to reject vertical noise or blends the two channels, choosing the cleaner wall through damaged passages.','Disc Restoration',ARRAY['Composite restoration','Stylus','Declicking','Decrackling','Vertical modulation']::text[],ARRAY['Assuming a mono disc must be played with a mono cartridge, which throws away the ability to compare the two walls.','Summing to mono without checking channel phase and balance, so the signal partly cancels instead of the noise.','Treating one damaged wall as unusable when it may still hold the cleaner signal in some passages.']::text[],ARRAY['Transferring a scratched mono disc with a stereo cartridge and summing to reject vertical noise.','Choosing the less-damaged groove wall through a section where one side is worn.','Blending two groove-wall channels to minimise surface noise on a lateral disc.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c8d83f2e-6069-50ad-9756-3f3222891f88' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Differential groove recovery'),'[^a-z0-9]','','g'));
