INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b3826954-d85d-5164-9998-58f554e1ff6d','Dolby level','A defined reference recording level (magnetic flux level) used to calibrate Dolby noise-reduction systems so the replay chain reproduces the same level the encoder assumed. A distinctive recorded reference tone, the Dolby tone, is placed on the tape at Dolby level so an operator can set replay gain for correct decoding.','Dolby noise reduction only works if playback volume matches what recording assumed. Dolby level is that agreed reference loudness on the tape. A special Dolby tone is recorded at that level. The operator lines up playback to it so decoding tracks correctly.','It exists to give encoder and decoder a shared level reference, because Dolby processing is level-dependent and mis-set gain makes the noise reduction mistrack and dull or pump the sound.','Before transferring a Dolby-encoded tape, the engineer plays the Dolby tone at the head and adjusts replay gain until the meter reads Dolby level, then engages the matching decoder.','Noise Reduction',ARRAY['Dolby lineup','Reference fluxivity','Calibration tone','Dolby A','dbx']::text[],ARRAY['Decoding a Dolby tape without first matching replay gain to Dolby level, so the decoder mistracks.','Confusing Dolby level (a reference flux level) with the tape''s operating level or an arbitrary meter zero.','Assuming every noise-reduction tape uses the same reference; the correct system and tone must be identified first.']::text[],ARRAY['Setting replay gain to a tape''s Dolby tone before decoding a Dolby A master.','Checking that an archival reel''s head tones include a Dolby reference before transfer.','Troubleshooting dull, pumping playback caused by replay level not set to Dolby level.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b3826954-d85d-5164-9998-58f554e1ff6d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dolby level'),'[^a-z0-9]','','g'));
