SELECT 'b3826954-d85d-5164-9998-58f554e1ff6d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b3826954-d85d-5164-9998-58f554e1ff6d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0a6bf195-93b7-5992-ba5f-8f0a413938a5','Dolby lineup','The alignment procedure that sets a tape machine''s replay (and record) gain using the recorded Dolby tone, so reproduced level matches Dolby level and the Dolby decoder tracks the original encoding. It is part of lining up a machine to a tape before transfer, alongside speed, azimuth, and equalisation checks.','Dolby lineup is the setup step before playing a Dolby tape. You play the Dolby tone and adjust playback gain to hit the reference level. Do this and the decoder follows the recording correctly. Skip it and the sound comes out wrong.','It exists to guarantee the decoder sees the same levels the encoder used, because Dolby noise reduction is level-sensitive and only decodes cleanly when replay gain is correctly lined up.','The engineer locates the Dolby tone at the head of the tape, adjusts replay gain to Dolby level, verifies against the tape''s documentation, then decodes and transfers the program.','Noise Reduction',ARRAY['Dolby level','Reference fluxivity','Azimuth','Calibration tone','Contemporaneous transfer note']::text[],ARRAY['Skipping Dolby lineup and simply engaging the decoder, which mistracks and colours the sound.','Lining up to the wrong tone or level reference, so the whole transfer is offset.','Failing to note the noise-reduction system and lineup used, leaving the transfer undocumented.']::text[],ARRAY['Lining up a studio recorder to a tape''s Dolby tone before a preservation transfer.','Setting replay gain during a batch transfer of Dolby-encoded broadcast reels.','Diagnosing mistracking that turns out to be an incorrect Dolby lineup.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0a6bf195-93b7-5992-ba5f-8f0a413938a5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dolby lineup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0a6bf195-93b7-5992-ba5f-8f0a413938a5','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0a6bf195-93b7-5992-ba5f-8f0a413938a5' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '002776da-df2b-5a8e-8b46-0544f48feeae','Dolby tone','A reference alignment tone recorded at the head of a Dolby-encoded tape at Dolby (reference) level, used on replay to set machine gain so the decoder tracks the level at which the tape was encoded. For professional Dolby A, Dolby level corresponds to a magnetic reference fluxivity of 185 nWb/m, to which the replay level is matched before the decoder is engaged.','It is a steady test tone put at the start of a Dolby tape. The engineer sets the playback level to match it. That helps the Dolby decoder undo the recording correctly.','It provides a known level reference captured when the tape was encoded, so that on replay the machine and Dolby decoder can be calibrated to the exact level used during recording, which the companding decoder needs to reverse the process accurately.','Before transferring a Dolby-encoded tape, the technician plays the Dolby tone and adjusts replay level until it reads the decoder''s Dolby reference mark, then engages the matching decoder.','Noise Reduction',ARRAY['Dolby tracking error','Encode/decode mistracking','Fixed-band companding','Flat encoded capture','Reference fluxivity']::text[],ARRAY['Treating the Dolby tone as an ordinary line-up tone and setting level by ear or to 0 VU instead of to the unit''s Dolby reference mark.','Decoding with the wrong Dolby type, for example decoding a Dolby A tape as Dolby B, which the tone alone does not identify.','Ignoring the tone and transferring without matching replay level, so the decoder mistracks.']::text[],ARRAY['Digitising an older Dolby A master reel that begins with a Dolby tone ahead of the programme.','Calibrating a cassette deck''s Dolby level to a reference cassette before dubbing.','Confirming that an archival tape is Dolby-encoded when a Dolby tone is found at the head.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='002776da-df2b-5a8e-8b46-0544f48feeae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dolby tone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '002776da-df2b-5a8e-8b46-0544f48feeae','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='002776da-df2b-5a8e-8b46-0544f48feeae' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'abd08353-8762-57e7-a6f7-68758d02903a','Dolby tracking error','An error in a Dolby-encoded transfer where the playback decoder fails to accurately reverse the record-side companding because replay level and/or frequency response do not match the encode reference. The mismatch causes tonal errors such as dullness or brightness and audible modulation (''breathing'') of the noise floor.','Dolby works by matching record and playback settings. If the playback level or tone is off, the decoder does not undo the recording right. You then hear dull or bright sound and the hiss seems to pump.','Naming this fault helps technicians recognise that a poor-sounding Dolby transfer is usually a calibration problem, not tape damage, so it can be fixed by correcting replay level and equalisation.','When a decoded transfer sounds muffled or its hiss pumps up and down, the technician suspects tracking error and rechecks Dolby level, azimuth and replay equalisation.','Noise Reduction',ARRAY['Dolby tone','Encode/decode mistracking','Fixed-band companding','Replay equalisation','Azimuth']::text[],ARRAY['Blaming the tape or transfer chain for dull, pumping audio when the real cause is a level or equalisation mismatch feeding the decoder.','Adjusting tone controls after decoding to mask the sound instead of correcting the replay level that caused the mistracking.','Assuming any Dolby unit tracks correctly without first matching its reference level to the tape''s Dolby tone.']::text[],ARRAY['A decoded cassette transfer sounds dull because the deck''s Dolby level was never calibrated.','High-frequency breathing appears on a Dolby A reel when replay equalisation is set to NAB instead of IEC.','Comparing a flat, undecoded capture with a decoded one to confirm the decoder is tracking.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='abd08353-8762-57e7-a6f7-68758d02903a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dolby tracking error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'abd08353-8762-57e7-a6f7-68758d02903a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='abd08353-8762-57e7-a6f7-68758d02903a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '55a4054a-1139-5a09-b6a5-96e618859d2f','Drift rate','The rate at which a tape machine''s reproduced speed, or a recovered reference frequency, slowly departs from its nominal value over time, expressed as a change per unit time. Drift is the slow, long-term component of speed instability, distinct from the faster periodic variations of wow and flutter.','Drift is a slow change in tape speed over minutes, not the fast wobble of wow and flutter. Drift rate is how fast that slow change grows. It shows up as pitch that creeps up or down.','Quantifying drift rate lets a transfer engineer decide whether pitch stability is acceptable or whether speed correction, referenced to a stable signal, is needed.','By tracking a captured reference tone or mains hum, the technician measures how fast pitch drifts and applies matching speed correction during or after transfer.','Speed & Timebase',ARRAY['Drift-compensated alignment','Absolute speed error','Wow and flutter','Actual tape speed','Capstan']::text[],ARRAY['Confusing slow drift with wow and flutter, which are faster, periodic speed variations measured differently.','Assuming a stated tape speed is exact and never checking for drift across a long reel.','Correcting a single average speed offset while ignoring drift that changes through the recording.']::text[],ARRAY['Pitch slowly rises across a long reel as the capstan or motor speed drifts while the machine warms up.','A recovered pilot or mains-hum frequency is used to chart drift through a transfer.','Comparing start and end pitch of a tape to estimate its drift rate.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='55a4054a-1139-5a09-b6a5-96e618859d2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drift rate'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '55a4054a-1139-5a09-b6a5-96e618859d2f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='55a4054a-1139-5a09-b6a5-96e618859d2f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '18241e6f-f330-5cb7-beee-3e8f1379bd58','Drift-compensated alignment','A transfer and correction approach that compensates for a tape''s speed drift by referencing a stable signal captured with the audio, such as a pilot tone, bias residue, or mains hum, so reproduced pitch and timing are held to the original despite slow speed variation. The reference frequency, whose original value is known, is used to derive a time-varying speed correction.','This method fixes slow speed changes during transfer. It uses a steady signal on the tape, like a hum or pilot tone, as a yardstick. When that signal drifts, the same correction is applied to the audio.','It exists to restore correct, stable pitch from tapes whose speed wandered during recording or playback, using a known reference rather than guesswork.','The technician extracts a captured reference frequency, compares it to its known value moment by moment, and applies the resulting variable speed correction to the digitised audio.','Speed & Timebase',ARRAY['Drift rate','Absolute speed error','Actual tape speed','Wow and flutter','Pilot tone']::text[],ARRAY['Applying a single fixed speed change when the drift actually varies through the recording.','Trusting a reference signal that is itself unstable, which passes its own errors into the corrected audio.','Skipping documentation of the reference used and the correction applied, so the work cannot be checked later.']::text[],ARRAY['Correcting a field recording whose battery-powered recorder ran at a drifting speed, using its 50 or 60 Hz hum as reference.','Stabilising pitch on a pilot-tone film-sync tape during transfer.','Removing slow pitch wander from a slipping tape by locking to a captured bias reference.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='18241e6f-f330-5cb7-beee-3e8f1379bd58' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drift-compensated alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '18241e6f-f330-5cb7-beee-3e8f1379bd58','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='18241e6f-f330-5cb7-beee-3e8f1379bd58' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '34e2a304-0870-55c2-a5c4-73744634b168','Dropout interpolation','A restoration technique that reconstructs audio lost during a dropout, a brief fall in replay level caused by oxide shedding, debris, creasing, or poor head contact, by estimating the missing or attenuated samples from the surrounding undamaged signal. Short gaps are filled by interpolation across the affected region so the waveform continues smoothly.','A dropout is a short drop or gap in the sound. It often comes from a bare or dirty spot on the tape. Interpolation fills that gap. It rebuilds the missing bit from the good audio on either side.','It restores continuity to a recording by repairing brief losses that would otherwise be heard as a dip, mute, or click, without altering the surrounding good audio.','After transfer, the technician marks each dropout and uses a restoration tool''s interpolation or spectral-repair function to rebuild the missing audio from adjacent samples.','Restoration Processing',ARRAY['Dropout','De-click','Spectral repair','Print-through','Sticky-shed syndrome']::text[],ARRAY['Interpolating across gaps that are too long, which invents audio and can sound worse than the original fault.','Reaching for interpolation after transfer when many dropouts could have been reduced by cleaning the tape and heads first.','Treating a genuine musical transient as a dropout and repairing real signal.']::text[],ARRAY['Repairing brief signal losses on an old tape that has shed oxide in places.','Filling a momentary gap where a crease or splice crossed the playback head.','Rebuilding short sections lost to debris on a cassette during digitisation.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='34e2a304-0870-55c2-a5c4-73744634b168' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dropout interpolation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '34e2a304-0870-55c2-a5c4-73744634b168','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='34e2a304-0870-55c2-a5c4-73744634b168' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9cd451c9-f155-5c03-8604-16fdfda70ff0','Edit angle','The angle at which a splice cut crosses the width of the tape when two pieces are joined, set by the guide slot in a splicing block. A diagonal cut, commonly 45 degrees, spreads the join across a short span of time to soften the transition and reduce the level and azimuth discontinuity, whereas a 90-degree vertical (butt) cut gives the tightest, most precise edit point.','It is the slant of the cut where two tape pieces are joined. A slanted cut spreads the join over a moment of time, so it sounds smoother. A straight square cut is tighter but more likely to click.','Choosing the edit angle trades precision against smoothness: a diagonal join blends the two sounds and hides the seam, while a vertical join places the edit at an exact instant.','Using a splicing block, the editor cuts both tape ends in the chosen angled slot, butts them together, and joins them with splicing tape.','Editing & Splicing',ARRAY['Edit pop','Edit sliver','Butt splice','Splicing block','Azimuth']::text[],ARRAY['Using a square 90-degree cut where a diagonal one is needed, so the abrupt join produces an audible click or pop.','Cutting the two ends at mismatched angles so they do not butt cleanly and leave a gap.','Assuming the angle affects only appearance and not the sound of the transition.']::text[],ARRAY['Splicing music together where a 45-degree cut is used to make the join inaudible.','Making a tight speech edit with a near-vertical cut for exact timing.','Repairing a broken tape and matching the original splice angle.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9cd451c9-f155-5c03-8604-16fdfda70ff0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edit angle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9cd451c9-f155-5c03-8604-16fdfda70ff0','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9cd451c9-f155-5c03-8604-16fdfda70ff0' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8a906307-92c7-5135-b2eb-91bb3c133390','Edit pop','A brief click or thump heard at an edit or splice point, caused by a discontinuity in the waveform where two sections meet, such as a join made at a moment of non-zero signal, a level or DC offset between sections, or a butt join with no crossfade. The sudden step in the waveform contains high-frequency energy heard as a click.','It is a click or thump you hear right at an edit. It happens when the join lands where the sound is not at zero. The sudden jump in the wave makes the click.','Recognising an edit pop tells the technician the join is abrupt and needs a better cut point or a short crossfade, rather than being a fault in the source recording.','When a click appears exactly at a cut, the editor moves the edit to a zero crossing or applies a short crossfade to remove it.','Editing & Splicing',ARRAY['Edit angle','Edit sliver','Zero crossing','Crossfade','Butt splice']::text[],ARRAY['Placing an edit at a loud part of the waveform instead of at a zero crossing, creating a click.','Trying to remove the pop with broadband de-click when a crossfade or a better edit point is the real fix.','Confusing an edit pop at the join with a dropout or tape click elsewhere in the material.']::text[],ARRAY['A click appears at every hard cut in a speech edit made off a zero crossing.','Butt-splicing two tape sections produces a thump at the join.','Assembling segments in a workstation where edits that are not crossfaded pop on playback.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8a906307-92c7-5135-b2eb-91bb3c133390' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edit pop'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8a906307-92c7-5135-b2eb-91bb3c133390','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8a906307-92c7-5135-b2eb-91bb3c133390' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee9e0e0c-3c0e-5da0-b0fc-0450649a572d','Edit sliver','An extremely short fragment of tape or audio left between two closely spaced edits, sometimes only a few milliseconds long. Slivers are usually unintended byproducts of tight editing and can cause clicks, stutters, or awkward transitions because they are too brief to play cleanly.','A sliver is a tiny scrap of sound left between two edits made very close together. It is so short it can click or stutter. Editors usually remove it or merge the edits.','Naming slivers helps editors spot and remove these tiny leftover pieces, which otherwise create clicks or glitches at busy edit points.','When cleaning up a densely edited passage, the technician zooms in to find and delete slivers or joins the edits so no fragment remains.','Editing & Splicing',ARRAY['Edit pop','Edit angle','Crossfade','Butt splice','Zero crossing']::text[],ARRAY['Leaving a one- or two-frame sliver between edits that then clicks or stutters on playback.','Deleting a sliver without rejoining or crossfading the surrounding edits, leaving a new gap.','Overlooking slivers because they are too small to see at a normal zoom level.']::text[],ARRAY['A tiny fragment left between two tight speech edits clicks on every playback.','Zooming in on a comp of many takes reveals slivers to clean up.','A near-butt tape edit leaves a sliver that must be trimmed away.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee9e0e0c-3c0e-5da0-b0fc-0450649a572d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edit sliver'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ee9e0e0c-3c0e-5da0-b0fc-0450649a572d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee9e0e0c-3c0e-5da0-b0fc-0450649a572d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bdd9a7ca-d82b-5b14-8ded-4ed15691cf4b','Encode/decode mistracking','A fault in companded (noise-reduced) recordings where the playback expander (decoder) does not accurately mirror the record-side compressor (encoder), because replay level and/or frequency response differ from the values used at encode time. The result is level and frequency-response errors and audible modulation (''breathing'') of the noise floor.','Noise reduction squeezes the sound on recording and expands it on playback. If the playback settings do not match the recording, the two do not line up. You then hear tone changes and hiss that pumps up and down.','Understanding mistracking tells the technician that matching replay level and equalisation to the encode reference is essential for any Dolby, dbx or telcom transfer to sound correct.','The technician sets replay level to the tape''s reference tone, selects the correct decoder and equalisation, then listens for steady, non-pumping hiss to confirm tracking.','Noise Reduction',ARRAY['Dolby tone','Dolby tracking error','Fixed-band companding','Flat encoded capture','Replay equalisation']::text[],ARRAY['Engaging a decoder without first matching replay level to the recording''s reference tone.','Using the wrong noise-reduction type or equalisation, so the decoder cannot track the encoder.','Judging tracking by overall loudness instead of listening for a steady, non-pumping noise floor.']::text[],ARRAY['A dbx-encoded tape decoded at the wrong level shows pumping hiss and wrong dynamics.','Matching a Dolby A decoder to a reel using its line-up tone before transfer.','Deciding to capture flat when the correct noise-reduction type cannot be identified.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bdd9a7ca-d82b-5b14-8ded-4ed15691cf4b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Encode/decode mistracking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bdd9a7ca-d82b-5b14-8ded-4ed15691cf4b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bdd9a7ca-d82b-5b14-8ded-4ed15691cf4b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c586717-d85d-5c9c-a268-159acda104b9','Ferrichrome tape','A dual-layer magnetic tape, standardised as IEC Type III and marketed as FeCr, that coats a lower layer of ferric oxide with a thin upper layer of chromium dioxide. The design aims to combine the strong low-frequency output of ferric oxide with the extended high-frequency performance of chromium dioxide, and it was produced in both reel and compact-cassette forms.','Ferrichrome tape has two magnetic layers stacked together. A ferric oxide layer handles low sounds well. A thin chrome layer on top handles high sounds well. It was one of the cassette tape types.','The two-layer coating was intended to give a wider, more even frequency response than a single ferric or chrome layer alone, chiefly on early high-fidelity cassettes.','When transferring a Type III cassette, the technician selects the bias and equalisation the format calls for so the tape reproduces with correct tonal balance.','Tape Formulations',ARRAY['Chromium dioxide tape','Ferric oxide tape','Bias','Replay equalisation','Compact cassette']::text[],ARRAY['Assuming a Type III ferrichrome cassette uses the same bias and equalisation as ordinary ferric (Type I) tape.','Confusing dual-layer ferrichrome with single-layer chrome (Type II) tape.','Setting the deck''s tape-type switch by guesswork rather than by the cassette''s actual formulation.']::text[],ARRAY['Digitising an older FeCr cassette and choosing the correct tape-type setting.','Identifying an unlabelled cassette''s formulation before transfer.','Comparing tonal balance of ferrichrome against ferric and chrome tapes.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c586717-d85d-5c9c-a268-159acda104b9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ferrichrome tape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9c586717-d85d-5c9c-a268-159acda104b9','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c586717-d85d-5c9c-a268-159acda104b9' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31d7c0f4-231c-5bb0-98eb-095267f89b47','Fixed-band companding','A noise-reduction method in which the audio is split into fixed frequency bands, each with its own compressor on record and matching expander on playback, so companding acts within predetermined frequency limits rather than sliding with the signal. Dolby A, with its four fixed bands, is the classic professional example; Dolby SR, by contrast, uses adaptive sliding-band filtering rather than fixed bands. It contrasts with sliding-band systems such as Dolby B and C and with broadband systems such as dbx.','This kind of noise reduction splits the sound into set frequency bands. Each band is squeezed on recording and expanded on playback on its own. The bands stay fixed, unlike some other systems.','Working in separate fixed bands lets the system reduce hiss where it is audible without letting a loud sound in one part of the spectrum release the noise reduction across the whole signal.','To transfer a Dolby A tape, the technician uses a matching fixed-band decoder, calibrated to the tape''s reference level, so each band expands exactly as it was compressed.','Noise Reduction',ARRAY['Encode/decode mistracking','Dolby tone','Dolby tracking error','Flat encoded capture','Sliding-band companding']::text[],ARRAY['Assuming all noise reduction is broadband and missing that fixed-band systems act independently in each band.','Decoding a fixed-band Dolby A tape with a sliding-band Dolby B decoder, which cannot track it.','Skipping per-band level calibration and still expecting correct tracking.']::text[],ARRAY['Setting up a Dolby A unit to decode a multitrack master.','Explaining why a Dolby A tape needs an A-type, not a B-type, decoder.','Choosing to capture flat when no matching fixed-band decoder is available.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31d7c0f4-231c-5bb0-98eb-095267f89b47' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fixed-band companding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '31d7c0f4-231c-5bb0-98eb-095267f89b47','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='31d7c0f4-231c-5bb0-98eb-095267f89b47' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95109989-319b-57ed-bbda-5f39ebc59e37','Flat encoded capture','A preservation transfer made without applying noise-reduction decoding, so the companded (encoded) signal is digitised flat, exactly as it sits on the tape. It is used when the correct decoder or reference level is uncertain, preserving the encoded signal so decoding can be done later, though with the risk that alignment errors compound if decoding is not carried out at transfer time.','This means copying a noise-reduced tape without decoding it first. You save the encoded sound just as it is. It is done when you are not sure which decoder or level is right, so decoding can wait.','It safeguards the original encoded signal when correct decoding cannot be assured at transfer time, keeping open the option to decode accurately once the right settings are known.','If a cassette''s noise-reduction type cannot be confirmed, the technician captures flat (undecoded), documents this, and leaves decoding for later analysis.','Noise Reduction',ARRAY['Encode/decode mistracking','Dolby tone','Dolby tracking error','Fixed-band companding','Reference tone']::text[],ARRAY['Forgetting to document that a capture is flat/encoded, so a later user decodes it wrongly or not at all.','Assuming later decoding will be as accurate as decoding at transfer time, when alignment errors can compound.','Capturing flat by default when the correct decoder and level are in fact known and should be applied.']::text[],ARRAY['A cassette of unknown noise-reduction type is captured flat and flagged for later decoding.','Preserving a Dolby-encoded reel flat because no matching decoder is on hand.','Providing both a flat and a decoded version so future users can choose.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95109989-319b-57ed-bbda-5f39ebc59e37' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flat encoded capture'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '95109989-319b-57ed-bbda-5f39ebc59e37','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
