INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26e3dbd4-564b-503d-a516-a86ec70e7fe6','Flutter spectrum','A frequency-domain representation of a playback machine''s short-term speed variations (flutter), plotting the amplitude of speed-modulation components against their modulation rate. Discrete peaks correspond to specific mechanical sources such as capstan, pinch-roller and guide-roller rotation, bearing eccentricity, or scrape flutter.','Flutter is fast, tiny wobble in tape speed. A flutter spectrum is a chart of how much wobble happens at each wobble rate. Each bump on the chart points to one part, like a roller, that is causing it.','It lets an engineer diagnose the mechanical source of speed instability by matching spectral peaks to the rotation rates of transport parts, guiding both machine servicing and corrective pitch processing.','A transfer engineer analyzes the flutter spectrum of a reference tone to trace a worn pinch roller or bearing before dubbing, or to set up de-flutter software on the transfer.','Speed Stability',ARRAY['Wow and flutter','Scrape flutter','Pitch stabilization','Capstan drive','Speed calibration']::text[],ARRAY['Confusing flutter (fast speed variation, roughly above 4 Hz) with wow (slow variation below about 4 Hz) and reading the spectrum in the wrong band.','Assuming every spectral peak is a fault, when some flutter is inherent to the transport and within specification.','Measuring flutter on a machine that still needs servicing, so the transport adds its own errors to the reading.']::text[],ARRAY['Measuring a reel-to-reel deck''s flutter spectrum with a reference tone before transferring irreplaceable masters.','Identifying a spectral peak that matches a pinch-roller rotation rate and scheduling roller replacement.','Using the residual flutter spectrum to configure de-wow/de-flutter software after a transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26e3dbd4-564b-503d-a516-a86ec70e7fe6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flutter spectrum'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26e3dbd4-564b-503d-a516-a86ec70e7fe6','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='26e3dbd4-564b-503d-a516-a86ec70e7fe6' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '33fea593-831b-5373-b911-3402a32bd31f','Fracture registration','The process of spatially aligning the separate pieces of a physically broken disc or other grooved carrier so that the groove path is continuous across each fracture, allowing the fragments to be played or optically scanned as a single reconstructed surface.','When an old record breaks, the pieces must be lined up just right. Fracture registration means matching the broken edges so the groove flows across the crack. Then the whole record can be read as one.','It exists to recover audio from broken discs that cannot be played normally, re-establishing groove continuity in scanning software or on the playback bed so little or no audio is lost at the breaks.','An archivist optically scanning a shattered lacquer registers each fragment''s groove to its neighbours so the software can follow the spiral across the fractures.','Physical Restoration',ARRAY['Fragment stitching','Groove-centerline extraction','Groove-topography reconstruction','Optical scanning','Vertical modulation']::text[],ARRAY['Forcing broken pieces together with adhesive under pressure, chipping the fragile groove walls at the break and destroying audio.','Registering fragments only by their outer edges rather than by the groove itself, so the spiral is misaligned across the break.','Discarding small fragments as unrecoverable instead of scanning and registering them with the rest.']::text[],ARRAY['Recovering a unique broken 78 rpm disc by imaging and registering its pieces for optical playback.','Aligning the halves of a cracked instantaneous lacquer disc before optical scanning.','Reassembling the groove path of a fractured disc or cylinder in imaging software.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='33fea593-831b-5373-b911-3402a32bd31f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fracture registration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '33fea593-831b-5373-b911-3402a32bd31f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='33fea593-831b-5373-b911-3402a32bd31f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25a45bc5-22e1-553e-a72e-fa78517ec9e4','Fragment stitching','The restoration step of joining separately captured audio fragments — such as the pieces of a broken disc, damaged tape sections, or multiple partial transfers — into a single continuous programme, aligning them at the boundaries so the joins are inaudible.','Sometimes a recording is captured in several broken pieces. Fragment stitching joins those pieces back into one smooth track. The goal is joins you cannot hear.','It reassembles a complete performance from partial captures, letting each fragment be transferred under its own best settings and then combined without gaps or audible seams.','After optically scanning a broken disc piece by piece, an engineer stitches the fragment recordings together, crossfading at each join to hide the transition.','Restoration Process',ARRAY['Fracture registration','Groove-topography reconstruction','Spectral repair','Crossfade','Waveform editing']::text[],ARRAY['Butt-joining fragments without a crossfade or phase match, producing an audible click or level jump at every seam.','Stitching in the wrong order or duplicating overlapping audio because fragment boundaries were not logged.','Editing the stitched master destructively so the original fragment transfers can no longer be re-checked.']::text[],ARRAY['Combining the individually scanned pieces of a broken lacquer into one continuous transfer file.','Joining two overlapping tape passes taken at different settings into a single clean master.','Reassembling a cylinder recording captured in several optical passes.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25a45bc5-22e1-553e-a72e-fa78517ec9e4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fragment stitching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '25a45bc5-22e1-553e-a72e-fa78517ec9e4','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25a45bc5-22e1-553e-a72e-fa78517ec9e4' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'be392446-212a-5f58-ab5c-fd16dc7f973f','Generation identification','The process of determining where a given recording sits in a chain of copies — original/master, first-generation copy, safety, or a later dub — using documentary evidence, box and leader annotations, physical characteristics of the carrier, and audible signs of accumulated copying.','Old recordings are often copies of copies. Generation identification works out how far a tape is from the first one. Clues include the box notes, the tape itself, and how much quality is lost.','Knowing a recording''s generation tells an archive which source is closest to the original, and therefore best to preserve, and prevents mistaking a later dub for a master.','Before digitizing, a technician compares candidate tapes and identifies the earliest generation by its lower noise and wider bandwidth, choosing it as the preservation source.','Provenance & Generations',ARRAY['Generation loss assessment','Master tape','Safety copy','Print-through','Provenance']::text[],ARRAY['Assuming the best-looking or newest-sounding tape is the earliest generation, when a later dub may simply be in better condition.','Ignoring box, leader and log annotations that record the copying history.','Treating a first-generation copy as the master when the true original still exists elsewhere in the collection.']::text[],ARRAY['Selecting the preservation master from several reels of the same programme in an archive accession.','Distinguishing an original studio master from a broadcast dub by bandwidth and noise floor.','Documenting the generation of each carrier during a collection survey.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='be392446-212a-5f58-ab5c-fd16dc7f973f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Generation identification'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'be392446-212a-5f58-ab5c-fd16dc7f973f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='be392446-212a-5f58-ab5c-fd16dc7f973f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b8c830a9-dd20-571e-9516-4efebc6e199a','Generation loss assessment','The evaluation of cumulative signal degradation introduced each time an analog recording is copied — added noise, reduced high-frequency response, increased distortion and compounded speed errors — used to judge how many copying generations separate a carrier from the original and how much fidelity has been lost.','Every analog copy is a little worse than the one before. This check measures how much was lost through repeated copying. It is like copying a photocopy again and again.','It helps an archive choose the least-degraded source for preservation and set realistic restoration goals, since losses baked in by earlier copying cannot be fully undone.','An engineer compares noise floor and high-frequency content across candidate copies to rank them by generation and select the cleanest for transfer.','Provenance & Generations',ARRAY['Generation identification','Signal-to-noise ratio','High-frequency dropout','Print-through','Master tape']::text[],ARRAY['Believing restoration software can restore detail that was never captured because it was lost in earlier copying.','Judging generation from loudness rather than from noise, bandwidth and distortion.','Adding another analog copying step during preservation instead of transferring the earliest generation directly to digital.']::text[],ARRAY['Ranking three dubs of a lost session by measured noise and bandwidth to pick a transfer source.','Explaining to a client why a fourth-generation cassette cannot sound like the master.','Documenting fidelity loss in a preservation condition report.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b8c830a9-dd20-571e-9516-4efebc6e199a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Generation loss assessment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b8c830a9-dd20-571e-9516-4efebc6e199a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b8c830a9-dd20-571e-9516-4efebc6e199a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd432dd9a-cbe6-55c2-acd1-68debb622ee1','Grease-pencil edit mark','A soft wax (chinagraph/grease) pencil mark made on the base (non-oxide) side of magnetic tape, aligned to the reproduce head, to indicate the exact point at which the tape is to be cut when splice editing.','To edit reel tape, you find the spot to cut by ear. You mark it with a soft wax pencil on the shiny back of the tape. That mark shows where to slice the tape.','It records the precise edit point located by rocking the tape across the playback head, without damaging the recording, so the cut can be made accurately in the splicing block.','An engineer rocks the reels to find a downbeat at the head, marks the tape back with a grease pencil, then moves it to the splicing block to cut and join.','Tape Editing',ARRAY['Splicing block','Splicing tape','Razor edit','Reproduce head','Leader tape']::text[],ARRAY['Marking the oxide (dull) side, where the pencil can shed wax onto heads and guides and contaminate the recording surface.','Using an ordinary graphite or ink pen instead of a soft wax pencil, scratching the tape or leaving abrasive debris.','Marking at the record head instead of the reproduce head, so the mark is offset from the point actually heard.']::text[],ARRAY['Editing a music master on a 1/4-inch analog machine to tighten a song''s intro.','Marking splice points to remove a bad take from a spoken-word recording.','Teaching tape-splicing technique in an archival transfer lab.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d432dd9a-cbe6-55c2-acd1-68debb622ee1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Grease-pencil edit mark'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd432dd9a-cbe6-55c2-acd1-68debb622ee1','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d432dd9a-cbe6-55c2-acd1-68debb622ee1' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e0ce2459-a8e3-50df-a551-0677518b13f6','Groove-centerline extraction','An image-analysis step in optical playback of grooved records that locates and traces the centre of the groove across a high-resolution image of the surface, converting the groove''s lateral (or vertical) path into the modulation waveform from which audio is derived.','A record groove wiggles, and those wiggles are the sound. This method uses software to find the middle of the groove in a photo of the record. Tracing that path turns the picture back into sound.','It replaces the physical stylus with a traced path, so audio can be recovered from discs too fragile, broken or worn to play safely with a needle.','After imaging a disc with a system such as IRENE, a technician runs centreline extraction to follow the groove and generate an audio file without touching the surface.','Optical Groove Scanning',ARRAY['Groove-topography reconstruction','Optical scanning','Fracture registration','Stylus','Spectral repair']::text[],ARRAY['Letting the tracer jump into an adjacent groove turn at damaged sections, producing skips and repeats in the audio.','Scanning at too low a resolution to resolve the groove wall, so fine high-frequency modulation is lost.','Treating dust and scratches in the image as groove modulation, adding clicks that then need removal.']::text[],ARRAY['Recovering a cracked lacquer disc by 2D optical imaging and centreline tracing.','Playing a worn disc too fragile for a stylus by extracting its groove centreline from images.','Comparing stylus playback with optical centreline extraction on a damaged 78.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e0ce2459-a8e3-50df-a551-0677518b13f6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-centerline extraction'),'[^a-z0-9]','','g'));
