INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'adf040f6-a50b-51c3-8505-b0cf5ec8a579','Groove-topography reconstruction','The recovery of a three-dimensional model of a record''s groove surface — typically by confocal or interferometric microscopy — from which the motion of a virtual stylus is computed to reconstruct the recorded audio without physical contact.','This method makes a detailed 3D map of the groove shape. Software then pretends a needle is riding that shape. The pretend needle movement is turned back into sound.','It captures the full groove shape, including depth (vertical) modulation, so audio can be recovered from fragile, worn or vertically-cut records that a stylus would damage or mistrack.','An archive uses a confocal scanner to build a groove-surface model of a rare cylinder, then reconstructs the audio by simulating stylus motion over the modelled surface.','Optical Groove Scanning',ARRAY['Groove-centerline extraction','Optical scanning','Vertical modulation','Fracture registration','Confocal microscopy']::text[],ARRAY['Assuming lateral (2D) tracing is enough for vertically-cut discs and cylinders, where the audio lives in groove depth.','Scanning at insufficient depth resolution, flattening the topography and losing high frequencies.','Ignoring debris and mould in the surface model, which the virtual stylus then reads as noise.']::text[],ARRAY['Recovering a hill-and-dale (vertically cut) cylinder using 3D confocal scanning.','Reconstructing audio from a delaminating disc too fragile for any stylus.','Choosing 3D topography over 2D imaging because the medium is vertically modulated.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='adf040f6-a50b-51c3-8505-b0cf5ec8a579' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-topography reconstruction'),'[^a-z0-9]','','g'));
