SELECT 'adf040f6-a50b-51c3-8505-b0cf5ec8a579','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='adf040f6-a50b-51c3-8505-b0cf5ec8a579' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c7c92be-9fba-505f-a5d8-6e294664892a','Harmonic hum reconstruction','A de-noising approach that models a mains-related hum not as a single tone but as a harmonic series — the fundamental (50 or 60 Hz) plus its integer multiples — and removes or notches that whole family together, reconstructing the underlying programme in the affected narrow bands.','Electrical hum is not one note. It is a low note plus many higher copies stacked above it. This method models that whole stack and removes it together, so the music behind it survives.','Because hum energy appears at the fundamental and many harmonics, treating the whole harmonic family at once removes hum more completely than a single notch while disturbing less wanted audio.','An engineer sets a 50 or 60 Hz hum profile in de-hum software and enables harmonic removal so the tool tracks and notches the higher multiples in one operation.','Noise Reduction',ARRAY['Heterodyne whistle','Notch filter','Mains frequency','Spectral repair','Signal-to-noise ratio']::text[],ARRAY['Notching only the fundamental (50 or 60 Hz) and leaving the audible harmonics, so the hum still buzzes.','Setting the wrong base frequency (50 Hz instead of 60 Hz, or vice versa) so the harmonic comb misses the hum.','Using very deep, wide notches that carve out musical energy sharing those frequencies.']::text[],ARRAY['Cleaning mains hum from a live recording made with a ground-loop problem.','Removing buzz with rich harmonics from an old tube-amplifier transfer.','De-humming film dialogue before it interferes with restoration EQ.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c7c92be-9fba-505f-a5d8-6e294664892a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Harmonic hum reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9c7c92be-9fba-505f-a5d8-6e294664892a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c7c92be-9fba-505f-a5d8-6e294664892a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e605388-cdf5-549c-8624-b76fb40212d3','Heterodyne whistle','An unwanted steady tone produced when two nearby signals or carriers mix (heterodyne), creating an audible beat at their difference frequency. In archival audio it commonly appears as a whistle from adjacent AM radio channels — an interstation beat near 9-10 kHz — or from other interfering tones captured in the original recording.','When two close signals mix, they make a new tone at the gap between them. On old radio and disc recordings this shows up as a steady whistle. It is like two slightly out-of-tune notes making a throb.','Recognising a whistle as a heterodyne beat, rather than programme content, tells the engineer it is a narrow, near-constant tone that can be tracked and notched out without wide-band damage.','An engineer identifies a persistent high whistle on an off-air transcription as an interstation heterodyne and removes it with a tracking notch or de-whistle tool.','Noise & Artifacts',ARRAY['Harmonic hum reconstruction','Notch filter','Interference','Spectral repair','High-frequency dropout']::text[],ARRAY['Mistaking a heterodyne whistle for a genuine high-frequency instrument, or removing real content thinking it is the whistle.','Using a fixed notch when the whistle drifts in frequency, so it slips out of the notch and returns.','Applying broad high-frequency roll-off to kill the whistle, dulling the whole recording instead.']::text[],ARRAY['Restoring an off-air AM broadcast transcription plagued by an interstation whistle.','Removing a drifting whistle from a shortwave recording.','Cleaning a disc transfer where a heterodyne tone was present in the original broadcast.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e605388-cdf5-549c-8624-b76fb40212d3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Heterodyne whistle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e605388-cdf5-549c-8624-b76fb40212d3','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e605388-cdf5-549c-8624-b76fb40212d3' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7822111c-f78c-5c78-b47c-b957bef948d6','High-frequency dropout','A momentary loss of reproduced signal, most severe at high frequencies, caused by a brief increase in the gap between the tape''s oxide and the replay head — from oxide shedding, debris, creases or poor pack. Short high-frequency wavelengths suffer first because reproduce loss rises steeply with head-to-tape spacing.','On tape, the high notes fade out for an instant when the tape lifts off the playback head. Dust, a crease, or shed coating can cause it. Short high sounds are hurt first because they need the tightest contact.','Understanding it as a spacing (contact) problem, not a recording fault, guides the fix — cleaning, careful handling, better pack and transport maintenance — rather than boosting EQ.','A transfer engineer hearing brief top-end fades cleans the tape path and re-tensions the pack, then treats residual dropouts with spectral repair instead of global EQ.','Tape Degradation',ARRAY['Spacing loss','Oxide shedding','Print-through','Generation loss assessment','Spectral repair']::text[],ARRAY['Compensating for dropouts with high-frequency EQ boost, which only raises hiss without restoring the missing signal.','Assuming brief top-end fades are a recording fault when they are usually a tape-to-head contact problem.','UNSAFE: Handling or playing mould-contaminated tape without gloves and respiratory protection, risking inhalation of spores and spreading contamination.']::text[],ARRAY['Transferring an aging cassette where high notes cut out briefly from oxide loss.','Diagnosing intermittent top-end fades traced to debris on the replay head.','Repairing scattered dropouts in a transfer with spectral tools after cleaning the tape.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7822111c-f78c-5c78-b47c-b957bef948d6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('High-frequency dropout'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7822111c-f78c-5c78-b47c-b957bef948d6','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7822111c-f78c-5c78-b47c-b957bef948d6' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf509d17-04ed-5b76-a70f-1f081e72c7a5','High-frequency roll-off constant','The time constant (expressed in microseconds) that defines the high-frequency portion of a record/replay equalization characteristic, setting the corner frequency above which the curve rolls off. Examples include the 75 microsecond treble constant of the RIAA disc curve and the 50 and 35 microsecond constants used in NAB and IEC/CCIR magnetic-tape replay.','Playback gear must undo the tone shaping used when a record or tape was made. This constant is a small timing number that sets where the treble is turned back down. The wrong number makes a recording too bright or too dull.','It precisely defines the treble corner of a standard replay curve, so a reproducer can invert the recording''s pre-emphasis and restore a flat, accurate frequency balance.','An engineer selects the correct roll-off constant on the replay preamp — for example 75 microseconds for an RIAA disc, or the constant for a given tape standard — so the transfer matches the original curve.','Playback Equalization',ARRAY['Historical replay equalization','RIAA equalization','NAB equalization','Turnover frequency','Pre-emphasis']::text[],ARRAY['Confusing the high-frequency roll-off constant with the low-frequency turnover constant and applying them to the wrong end of the curve.','Using a single default (such as RIAA) for every disc or tape, when 78s and different tape standards use different constants.','Mixing record and replay standards, so a tape recorded to one constant is played back with another and sounds too bright or too dull.']::text[],ARRAY['Setting a phono preamp''s treble time constant to 75 microseconds for an RIAA LP transfer.','Choosing the correct constant for a 38 cm/s IEC-equalized master tape.','Documenting which roll-off constant was used so a transfer can be reproduced later.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf509d17-04ed-5b76-a70f-1f081e72c7a5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('High-frequency roll-off constant'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bf509d17-04ed-5b76-a70f-1f081e72c7a5','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bf509d17-04ed-5b76-a70f-1f081e72c7a5' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd175ec65-bb9c-52ce-9a4e-59c5e3b58d2c','Historical replay equalization','The practice of reproducing a historical recording through the equalization curve appropriate to its format, era and label — such as the many pre-RIAA 78 rpm curves, or the correct NAB or IEC/CCIR tape standard — rather than defaulting to a single modern curve, so the transferred frequency balance matches what was intended.','Old records and tapes had their tone shaped in many different ways before one standard existed. This means playing each one back with its own matching curve. Using the wrong curve makes it sound too bright or too dull.','It restores the intended frequency balance of recordings made before or outside modern standards, avoiding the tonal errors that come from applying today''s RIAA curve to everything.','When transferring a 1940s disc, an engineer selects the label''s documented turnover and roll-off, auditions candidate curves, and logs the one chosen with the transfer.','Playback Equalization',ARRAY['High-frequency roll-off constant','RIAA equalization','NAB equalization','Turnover frequency','Pre-emphasis']::text[],ARRAY['Playing every 78 or acoustic disc through the modern RIAA curve, which did not exist when they were cut.','Baking a guessed EQ curve into the preservation master instead of transferring cleanly and documenting the intended curve.','Assuming all discs from one era or label share one curve, when curves varied by company and period.']::text[],ARRAY['Transferring a pre-1954 78 rpm disc and selecting a period turnover and roll-off instead of RIAA.','Choosing NAB versus IEC/CCIR replay for an archival tape depending on its origin.','Auditioning candidate curves to match the tonal balance of an undocumented lacquer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d175ec65-bb9c-52ce-9a4e-59c5e3b58d2c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Historical replay equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd175ec65-bb9c-52ce-9a4e-59c5e3b58d2c','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d175ec65-bb9c-52ce-9a4e-59c5e3b58d2c' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3fbdaffb-1e40-5719-a4c1-a5e740ecb626','Hub bind','A condition in which the tape pack or reel is restrained at the hub so it cannot turn or feed freely — caused by an over-tight wind at the core, deposits or adhesive between wraps, a warped or oversized hub, or a reel seated too tightly on the spindle — producing erratic tension, speed errors and risk of stretching or edge damage on playback.','The hub is the center that a tape winds around. Hub bind is when the tape or reel grips the hub too tightly to spin smoothly. That drag can stretch the tape and make the sound waver.','Naming this fault helps a technician read sudden tension and speed problems as a hub or pack restraint rather than a transport failure, so the reel is freed instead of forced.','Before transfer, an engineer checks that the reel spins freely on the hub and gently rewinds a tightly bound pack at low tension to relieve hub bind rather than playing it under strain.','Tape Handling',ARRAY['Tape pack','Cinching','Pack slip','Flutter spectrum','Wow and flutter']::text[],ARRAY['Forcing a bound reel to play, so the motor drags the tape against the hub and stretches or creases it.','Reading erratic tension and speed as a transport fault when the pack is actually binding at the hub.','Winding tape onto a warped, cracked or wrong-size hub, which invites binding and uneven pack tension.']::text[],ARRAY['Preparing an old reel that will not spin freely on the supply turntable before transfer.','Diagnosing sudden speed wobble traced to a tape pack gripping a warped hub.','Gently rewinding or re-hubbing a tightly-wound archival reel to relieve binding.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3fbdaffb-1e40-5719-a4c1-a5e740ecb626' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hub bind'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3fbdaffb-1e40-5719-a4c1-a5e740ecb626','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3fbdaffb-1e40-5719-a4c1-a5e740ecb626' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f5354120-e87b-5b9e-82bc-189c1b3efd05','Hub brake','A braking mechanism acting on the supply and take-up reel hubs of a tape transport that controls back-tension and decelerates the reels during stop and fast-wind, preventing tape spillage, slack loops, and overrun. Braking may be mechanical (band or shoe brakes) or, on later machines, achieved electrically through reel-motor torque control.','A hub brake slows and holds the spinning reels on a tape machine. It stops the tape from spilling into loose loops when you press stop. Think of it like the brakes on a bike wheel.','It maintains correct tape tension and brings the reels to a controlled halt, so the tape stays taut against the heads and does not spill, stretch, or snap during stopping and fast winding.','An archivist servicing a reel-to-reel machine adjusts or replaces worn brake bands so the transport stops smoothly, avoiding slack loops that could crease or snap a fragile archival tape.','Tape Transport',ARRAY['Capstan','Tape tension (back-tension)','Tape pack','Hub bind']::text[],ARRAY['Confusing the hub brake with the capstan; the capstan sets playback speed, while the brakes only control the reels during stop and fast-wind.','Treating weak or uneven braking as harmless, when it lets reels overrun and spill tape, which can crease, stretch, or snap an irreplaceable archival tape.','Adjusting brake tension by guesswork instead of to the manufacturer''s service-manual specification, causing inconsistent tension and speed errors.']::text[],ARRAY['Restoring a vintage Studer or Ampex reel machine before an archival transfer, checking that both reel brakes hold and release evenly.','Diagnosing tape spillage or slack loops that appear each time the transport is stopped.','Setting hold-back tension so a brittle acetate tape is not jerked during start and stop.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f5354120-e87b-5b9e-82bc-189c1b3efd05' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hub brake'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f5354120-e87b-5b9e-82bc-189c1b3efd05','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f5354120-e87b-5b9e-82bc-189c1b3efd05' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f53c2a83-4f88-5313-99ea-fbb3e2d40215','Hum fundamental','The lowest-frequency component of mains-related hum in an audio signal, occurring at the power-line frequency itself, nominally 50 Hz or 60 Hz depending on region, from which the associated hum harmonics are derived. It arises from magnetic or electrostatic coupling of the AC supply, or from imperfect power-supply filtering, into the signal path.','Mains hum is the low buzz that leaks from the power supply into a recording. The hum fundamental is its base note. It sits at the local power frequency, either 50 or 60 cycles per second.','Identifying the fundamental frequency tells a restorer exactly where the hum''s base tone sits, which anchors any notch filter or de-hum process aimed at removing it and its harmonics.','A restorer reads the spectrogram, finds a strong narrow peak at 50 or 60 Hz, sets that as the hum fundamental in a de-hum tool, and lets it null the fundamental plus harmonics.','Noise & Interference',ARRAY['Hum-harmonic series','Hum tracking','Line-frequency wander','Ignition interference']::text[],ARRAY['Assuming the fundamental is always 60 Hz; in 50 Hz regions the base hum sits at 50 Hz, and mislabelling it puts every notch on the wrong frequency.','Removing only the fundamental and leaving its harmonics, so the hum still sounds buzzy rather than clean.','Confusing the hum fundamental with rumble or a musical bass note at a similar frequency and notching out wanted content.']::text[],ARRAY['Cleaning a location dialogue recording spoiled by 60 Hz mains hum from nearby lighting.','Removing 50 Hz hum from a European archival tape before digital delivery.','Diagnosing whether a low buzz is the mains fundamental or a mechanical rumble.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f53c2a83-4f88-5313-99ea-fbb3e2d40215' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hum fundamental'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f53c2a83-4f88-5313-99ea-fbb3e2d40215','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f53c2a83-4f88-5313-99ea-fbb3e2d40215' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '34fba21b-2893-511b-9742-fead67843833','Hum tracking','A de-hum technique in which the removal filter continuously follows (tracks) small variations in the hum''s fundamental frequency and phase over time, rather than assuming a fixed frequency, so the notch or subtraction stays aligned as the mains frequency drifts. It is typically adaptive, re-estimating the hum frequency from the signal and steering the harmonic comb accordingly.','Power hum can drift a little in pitch across a recording. Hum tracking follows that drift and keeps the filter locked onto it. It is like a filter that chases the hum instead of standing still.','It keeps the hum notch centred on the real hum frequency as it wanders, giving deeper, more stable removal than a fixed notch, which would drift off target and leave residue.','When a fixed 50 Hz notch leaves a wavering buzz, a restorer switches the de-hum module to an adaptive tracking mode so it locks to and follows the changing hum frequency.','Noise & Interference',ARRAY['Hum fundamental','Hum-harmonic series','Line-frequency wander','Ignition interference']::text[],ARRAY['Using a fixed-frequency notch on hum that drifts, so the filter slips off target and audible buzz returns.','Setting the tracker''s range too wide, so it locks onto wanted low-frequency musical content instead of the hum.','Assuming a tracker removes the harmonics automatically without enabling the harmonic comb.']::text[],ARRAY['Restoring an old tape whose hum pitch drifts because the original mains supply was unstable.','Cleaning a field recording where a portable generator''s frequency wandered.','Removing hum from a wire or acetate recording with unstable playback speed.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='34fba21b-2893-511b-9742-fead67843833' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hum tracking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '34fba21b-2893-511b-9742-fead67843833','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='34fba21b-2893-511b-9742-fead67843833' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '777d6f43-ce2a-5366-bfc8-eba7e21d3fac','Hum-harmonic series','The series of spectral components produced by mains hum at integer multiples of the power-line fundamental, for example 50, 100, 150, 200 Hz or 60, 120, 180, 240 Hz, created because the coupled or rectified AC waveform is non-sinusoidal. Full-wave rectification in power supplies emphasises the even-order components (100 or 120 Hz and above), while direct magnetic coupling of the line often emphasises the fundamental and odd harmonics.','Hum is not one clean tone. It comes with a stack of higher tones at whole-number multiples of the base. So 60 hertz hum also shows buzz at 120, 180, 240 and up. Removing all of them is what makes it sound clean.','Recognising the whole harmonic series lets a restorer target every hum component with a harmonic comb, not just the fundamental, so the characteristic buzzy timbre is fully removed.','A restorer enables a harmonic-comb de-hum that places notches on the fundamental and its multiples, then trims how many harmonics are treated to match what the spectrogram shows.','Noise & Interference',ARRAY['Hum fundamental','Hum tracking','Line-frequency wander','Ignition interference']::text[],ARRAY['Treating hum as a single tone and notching only the fundamental, leaving the higher harmonics buzzing.','Adding far more harmonic notches than the signal actually contains, thinning the wanted audio.','Confusing power-supply harmonics (strong at 100 or 120 Hz) with magnetically induced hum (strong at the fundamental) and choosing the wrong removal settings.']::text[],ARRAY['Cleaning a guitar-amp recording where a ground problem added a rich hum with many harmonics.','Restoring a transcription disc with buzzy harmonic hum from old rectifier equipment.','Tuning a de-hum comb to match the harmonics visible on a spectrogram.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='777d6f43-ce2a-5366-bfc8-eba7e21d3fac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hum-harmonic series'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
