INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '42f4b68f-55b2-5ec1-8690-2cdb54a5c4f7','IRENE scanning','A non-contact optical method for recovering audio from grooved media in which a disc or cylinder is imaged or profiled at high resolution and the groove geometry is converted into sound by software, with no stylus touching the surface. IRENE uses 2D imaging for laterally cut discs and confocal 3D profilometry for vertically cut (hill-and-dale) grooves and cylinders; it was developed by Carl Haber and colleagues at Lawrence Berkeley National Laboratory and is used by institutions including the Library of Congress and NEDCC.','IRENE plays old records with a camera instead of a needle. It takes very detailed pictures of the groove, then software turns those pictures into sound. Because nothing touches the disc, it can recover broken or fragile records that a needle would ruin.','It exists to recover sound from discs and cylinders that are broken, delaminating, or too fragile to play with a stylus, and to avoid adding wear during transfer.','An archivist images a cracked 78 or a soft wax cylinder on an IRENE system, then reconstructs and de-noises the audio from the pictures rather than risking a physical playback.','Optical Scanning',ARRAY['Image-domain dewarping','Multi-pass transfer','Multi-source alignment','Impulse interpolation']::text[],ARRAY['Believing IRENE always beats stylus playback; for a clean, playable disc a well-set-up turntable transfer is often faster and equal or better.','Forgetting that vertical-cut grooves and cylinders need 3D depth profiling, not the 2D image mode used for lateral discs.','Underestimating the heavy image processing and storage the method needs after scanning.']::text[],ARRAY['Recovering audio from a 78-rpm disc broken into several pieces.','Transferring flaking or mould-damaged lacquer or glass discs without further wear.','Digitising delicate wax cylinders that a stylus could shatter or abrade.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='42f4b68f-55b2-5ec1-8690-2cdb54a5c4f7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('IRENE scanning'),'[^a-z0-9]','','g'));
