INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9133d6c8-6186-5dc3-be1c-2dc527495fb4','Ignition interference','Impulsive electromagnetic interference generated by spark-ignition systems, chiefly petrol/gasoline engines, whose repetitive high-voltage spark discharges radiate broadband radio-frequency noise. In a recording or radio signal it appears as sharp, rhythmic clicks or a buzzing crackle whose rate rises and falls with engine speed; it is a recognised category of man-made radio noise.','Car and motorbike engines make sparks to fire the fuel. Each spark sends out a burst of radio noise. A recorder or radio can pick it up. It sounds like sharp clicks or crackle. The rate speeds up as the engine revs.','Naming this noise source helps a restorer recognise its impulsive, engine-speed-linked pattern and choose de-click or de-crackle tools, rather than mistaking it for damage on the medium.','When a field recording or aircheck is peppered with engine-synced clicks, a restorer identifies ignition interference and treats it with impulse-removal (de-click) processing.','Noise & Interference',ARRAY['Impulse interpolation','Hum fundamental','Line-frequency wander','Hum-harmonic series']::text[],ARRAY['Mistaking engine-ignition clicks for physical damage such as scratches on the original medium, and blaming the transfer.','Trying to remove rhythmic ignition clicks with broadband noise reduction, which dulls the audio instead of targeting the impulses.','Assuming shielding applied afterwards can fix noise that is already recorded into the signal.']::text[],ARRAY['Restoring a mid-century outdoor field recording contaminated by passing-traffic ignition noise.','Cleaning an AM radio aircheck that captured car-ignition crackle.','Diagnosing rhythmic clicks that change rate with a vehicle''s engine speed.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9133d6c8-6186-5dc3-be1c-2dc527495fb4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ignition interference'),'[^a-z0-9]','','g'));
