INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a72c9a3f-aacd-597e-8b5d-6e984a40904c','Image-domain dewarping','A correction applied to the scanned image of a grooved carrier, as in optical audio recovery, that geometrically remaps the picture to undo physical warp, eccentricity, or distortion before the groove is traced into audio. Working in the image domain, on pixels rather than the recovered waveform, it flattens or re-registers the groove path so subsequent tracking follows the true groove rather than the deformation.','Old discs can be warped or off-centre. When they are scanned as pictures, the groove looks bent or wavy. Image-domain dewarping straightens the picture first. Then the software can follow the real groove and not the warp.','It removes geometric distortion at the image stage so the extracted audio is free of the wow, wander, or tracking errors that the physical warp would otherwise bake into the sound.','Processing an IRENE scan of a warped lacquer disc, the operator applies dewarping to the image so the groove-tracking step does not read the warp as pitch and level fluctuation.','Optical Scanning',ARRAY['IRENE scanning','Multi-pass transfer','Multi-source alignment','Impulse interpolation']::text[],ARRAY['Skipping dewarping and letting disc warp show up as wow and tracking glitches in the recovered audio.','Over-correcting the geometry so the groove path is distorted and real signal is altered.','Confusing image-domain dewarping, which fixes the picture, with time-domain wow correction, which fixes the finished waveform.']::text[],ARRAY['Recovering audio from a heat-warped lacquer or shellac disc on an optical scanner.','Correcting eccentric, off-centre pressings before groove extraction.','Preparing scanned images of a broken disc whose pieces do not lie perfectly flat.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a72c9a3f-aacd-597e-8b5d-6e984a40904c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Image-domain dewarping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a72c9a3f-aacd-597e-8b5d-6e984a40904c','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a72c9a3f-aacd-597e-8b5d-6e984a40904c' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5971668b-fb19-5c4a-8814-200c7e275860','Impulse interpolation','A click/impulse-removal technique in which samples corrupted by a short transient disturbance (a click, tick, or scratch pulse) are detected, discarded, and reconstructed by interpolating replacement values from the surrounding undamaged samples. Model-based implementations use autoregressive (AR) prediction to estimate the missing samples so the repair matches the local signal, leaving no audible gap.','A click is a tiny burst of bad samples in the sound. Impulse interpolation finds those bad samples, throws them out, and fills the gap using the good sound on both sides. It is like patching a small hole so you cannot see the join.','It removes clicks and ticks without punching holes or dulling the audio, because the gap is rebuilt from real neighbouring signal rather than muted or smeared.','A restorer runs a de-click pass on a vinyl or 78 transfer; the tool interpolates across each detected click so the pops vanish while the music underneath is preserved.','Click Removal',ARRAY['Ignition interference','IRENE scanning','Multi-pass transfer','Image-domain dewarping']::text[],ARRAY['Setting click detection too aggressively, so transients such as drum hits or consonants are treated as clicks and interpolated away.','Trying to interpolate across gaps that are too long, which produces smeared or dull artefacts instead of a clean repair.','Confusing click interpolation, for short impulses, with broadband hiss reduction, for steady noise, and using the wrong tool.']::text[],ARRAY['De-clicking a 78-rpm or vinyl transfer full of pops and ticks.','Removing isolated digital dropouts or ticks from a damaged file.','Cleaning ignition-noise clicks from a field recording.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5971668b-fb19-5c4a-8814-200c7e275860' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Impulse interpolation'),'[^a-z0-9]','','g'));
