INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67bc325f-caf5-508a-8dbe-f033fcd00229','Leader detachment','A fault in which the non-magnetic leader (or trailer) tape spliced to the start or end of a recording tape becomes separated from it, typically through failure of the splicing adhesive with age. The recording tape may be left with no handling leader, an exposed or damaged splice end, or a free tape end liable to further damage.','Reel tapes have a blank strip, the leader, joined to each end. Over time the glue on that join can dry out and let go. When the leader falls off, the recording end is left loose and easy to damage.','Recognising leader detachment matters because the leader protects the recording''s start and end and threads the machine; once it detaches, the vulnerable tape end must be re-leadered before safe playback.','Before transferring an archival reel, a technician re-splices a fresh leader when the original has come away, protecting the first and last recorded turns during threading and winding.','Tape Damage',ARRAY['Metallic sensing foil','Hub brake','Multi-pass transfer','Multi-source alignment']::text[],ARRAY['Playing a reel with a detached or failing splice, so the loose end snags and the recording''s start or end is creased or torn.','Reusing old bleeding-adhesive splices instead of removing the residue and making a fresh, clean splice.','Confusing the blank leader with lost recorded content and assuming audio is missing.']::text[],ARRAY['Preparing a 1970s reel whose leader splices have dried and fallen off before digitisation.','Re-leadering a tape so it threads safely through the transport.','Inspecting incoming archival reels for failed head or tail splices.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67bc325f-caf5-508a-8dbe-f033fcd00229' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Leader detachment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '67bc325f-caf5-508a-8dbe-f033fcd00229','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
