INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c43cd36d-1718-5218-9c95-37fceb246587','Line-frequency wander','Slow drift of the AC mains (line) frequency away from its nominal value of 50 or 60 Hz over time, caused by grid load balancing or, in older or independent supplies, by unregulated generation. Because mains hum is locked to the line frequency, this wander makes the hum fundamental and its harmonics drift correspondingly, so a fixed-frequency notch gradually falls off target.','The power grid''s frequency is not perfectly steady; it drifts a little around 50 or 60 hertz. Any hum in a recording drifts with it. That is why a fixed hum filter can slip off the moving hum and stop working well.','Understanding line-frequency wander explains why hum in a recording is not perfectly steady, and why adaptive tracking de-hum is needed to follow the moving hum rather than a fixed notch.','Seeing the hum line waver on a spectrogram, a restorer chooses an adaptive de-hum that tracks the frequency instead of a static 50 or 60 Hz notch.','Noise & Interference',ARRAY['Hum fundamental','Hum tracking','Hum-harmonic series','Ignition interference']::text[],ARRAY['Assuming mains hum sits at an exactly constant frequency and relying on a fixed notch that drifts off the wandering hum.','Blaming tape-speed instability for a wavering hum that is actually caused by line-frequency drift in the original supply.','Setting an adaptive tracker''s range too narrow to follow the full extent of the wander.']::text[],ARRAY['Restoring a recording made on an unstable local generator whose frequency drifted.','Explaining why a static hum notch leaves residual buzz that comes and goes.','Choosing tracking de-hum for an old mains-powered recording.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c43cd36d-1718-5218-9c95-37fceb246587' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Line-frequency wander'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c43cd36d-1718-5218-9c95-37fceb246587','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c43cd36d-1718-5218-9c95-37fceb246587' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '40ab2d6e-84c6-5f99-ab75-36cd5f3d8bfe','Metallic sensing foil','A short strip of electrically conductive metal foil (or metallised leader) affixed to or spliced into a tape which, on passing a contact or photo-electric sensor in the transport, triggers an automatic function such as end-of-tape stop, auto-reverse, or cue location. On some machines a pair of metal contacts is bridged by the foil to complete a sensing circuit.','Some tape machines watch for a small metal strip stuck to the tape. When that shiny foil passes the sensor, the machine knows the tape has reached a marked point. It then stops or flips automatically.','The foil lets the transport detect specific points on the tape, chiefly the end, so it can stop or reverse automatically and avoid running the tape off the reel or straining it.','When digitising a reel or cassette that relies on sensing foil, a technician checks the foil is intact and the sensor works, or disables auto-stop so the transport does not halt or reverse unexpectedly mid-transfer.','Tape Transport',ARRAY['Hub brake','Leader detachment','Multi-source alignment','Multi-pass transfer']::text[],ARRAY['Assuming a missing or oxidised sensing foil is harmless; without it, an auto-stop machine may not halt at the tape end and can spill or strain the tape.','Confusing the metallic sensing foil, a control trigger, with an edit splice or with the recording itself, and removing it.','Overlooking that different machines sense the foil electrically or optically, and expecting one method to work on all decks.']::text[],ARRAY['Transferring a reel that uses metal sensing foil for end-of-tape auto-stop.','Servicing a transport whose auto-stop no longer triggers because the foil or sensor is dirty.','Deciding whether to retain or bypass sensing-foil auto-stop during an archival transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='40ab2d6e-84c6-5f99-ab75-36cd5f3d8bfe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Metallic sensing foil'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '40ab2d6e-84c6-5f99-ab75-36cd5f3d8bfe','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='40ab2d6e-84c6-5f99-ab75-36cd5f3d8bfe' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15e0972a-abf2-5d0a-a69e-79b4fecbb84c','Multi-pass transfer','An archival transfer strategy in which the same carrier is played and captured more than once, often with different settings, styli, alignment, or azimuth, or simply as repeated passes, so the best portions of each pass can be selected or combined into an optimal preservation copy. It is used where a single pass cannot capture the whole item cleanly, as with damaged discs or difficult tapes.','Sometimes one playback cannot capture a damaged recording cleanly. In a multi-pass transfer, the item is played several times, maybe with different settings. Then the best parts of each pass are picked or blended into one good copy.','It maximises the signal recovered from a fragile or damaged original by giving the operator several captures to choose from or combine, rather than betting everything on one imperfect pass.','Facing a cracked disc that mistracks in places, a transfer engineer makes several passes and edits together the cleanest segment of each into the final master.','Transfer Workflow',ARRAY['Multi-source alignment','IRENE scanning','Impulse interpolation','Image-domain dewarping']::text[],ARRAY['Assuming more passes always help; each extra playback of a fragile original adds wear, so passes must be justified against the risk.','Failing to keep the passes time-aligned, making it hard to edit or combine them cleanly.','Documenting only the final edit and not which pass each segment came from, harming the archival record.']::text[],ARRAY['Transferring a broken or badly worn 78 that mistracks at different spots each play.','Capturing several stylus sizes on a worn groove to pick the quietest result.','Combining repeated optical scans of a fragile cylinder.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15e0972a-abf2-5d0a-a69e-79b4fecbb84c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Multi-pass transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '15e0972a-abf2-5d0a-a69e-79b4fecbb84c','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='15e0972a-abf2-5d0a-a69e-79b4fecbb84c' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fccb20cc-2349-5fe7-ba7c-9fe9c4a1215d','Multi-source alignment','The process of temporally, and sometimes spectrally, aligning two or more separate captures of the same content — different copies, generations, or transfer passes — so their samples correspond, allowing them to be compared, selected between, or combined. Alignment corrects speed, start-offset, and drift differences so equivalent moments line up sample-accurately.','The same recording may exist as several copies or several playbacks. Multi-source alignment lines them up in time so the same moment matches across all of them. Only then can you compare them or blend the best parts together.','It makes independent captures directly comparable, so a restorer can pick the cleaner source at each moment or average them to reduce noise, which is impossible while they drift out of sync.','Given two surviving tape copies of a broadcast, an engineer time-aligns them and switches to whichever is cleaner through each damaged passage.','Transfer Workflow',ARRAY['Multi-pass transfer','IRENE scanning','Impulse interpolation','Image-domain dewarping']::text[],ARRAY['Aligning only the start points and ignoring speed drift, so the sources slowly slip out of sync later in the programme.','Combining sources that are actually different edits or takes, introducing content mismatches.','Averaging misaligned sources, which blurs transients instead of reducing noise.']::text[],ARRAY['Reconstructing a complete programme from two damaged tape copies with different dropouts.','Noise-reducing by averaging several aligned transfer passes of one disc.','Comparing a master and a dub to choose the best-sounding source per section.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fccb20cc-2349-5fe7-ba7c-9fe9c4a1215d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Multi-source alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fccb20cc-2349-5fe7-ba7c-9fe9c4a1215d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fccb20cc-2349-5fe7-ba7c-9fe9c4a1215d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8c32e359-8cac-5746-8444-16dc0a0a6566','Multi-stylus transfer','The archival practice of reproducing a grooved disc or cylinder with several replay styli of differing tip radius and profile, transferring the recording more than once, and then selecting or combining the passages that track best. It exists because worn, damaged, or non-standard grooves often yield the lowest noise and distortion with a stylus geometry other than the nominal one, and no single stylus is optimal across a whole imperfect carrier.','Old records have grooves of many shapes and wear. A worn or cracked groove may sound best with a different needle. So the record is played and recorded with several needles. Then the best-sounding version of each part is kept.','It lets the engineer match stylus size and shape to the real condition of each groove section, cutting surface noise and distortion and recovering the truest signal from an imperfect carrier.','Working from a set of styli of different radii, a technician makes several passes of a damaged 78 or lacquer disc and auditions them side by side, choosing the stylus or splicing between transfers to get the cleanest result.','Disc Transfer',ARRAY['Non-RIAA equalization','Noncontact playback','Optical sound recovery','Best-copy selection','Flat transfer']::text[],ARRAY['Assuming one ''correct'' stylus fits every disc, when tip radius and shape must be matched to the groove standard and its wear.','Choosing the largest or smallest stylus for lowest noise without checking that it rides the modulated groove walls rather than the worn top or bottom.','UNSAFE: Handling or playing mould-affected discs without gloves and respiratory protection, risking spore inhalation and cross-contamination.']::text[],ARRAY['Transferring a scratched pre-1925 acoustic 78 whose groove wear varies across the side.','Digitising a delaminating lacquer disc where different styli track the good and damaged bands better.','Recovering a cylinder whose groove pitch does not match a single standard modern stylus.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8c32e359-8cac-5746-8444-16dc0a0a6566' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Multi-stylus transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
