WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8c32e359-8cac-5746-8444-16dc0a0a6566' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '821abccc-fbe8-5c15-bc18-dccc24ad157b','Noise-reduction identification','The process of determining which analogue companding noise-reduction system (for example Dolby A, B, C or SR, dbx Type I or II, or telcom) was used when a tape was recorded, so that the matching complementary decoder can be applied on replay. It is required because these systems encode the signal and must be decoded with the same, correctly aligned system, or the reproduced level and frequency balance will be wrong.','Many tapes were recorded through a noise-cutting system. That system squeezes the sound in a set way. To get it back right, you must play it through the same system. So first you work out which one was used. The box notes, careful listening, or a spectrum display can tell you.','It ensures the tape is decoded with the correct complementary system and alignment, so hiss, dynamics, and tone are restored to the original rather than left under- or over-corrected.','Before transfer the engineer checks the box and log for a system marking, listens for tell-tale pumping of the background hiss, or uses a spectrum analyser, then routes the tape through the matching decoder during capture.','Tape Transfer',ARRAY['Nominal tape speed','Non-RIAA equalization','Azimuth alignment','Flat transfer','Partial dropout']::text[],ARRAY['Decoding a tape with the wrong system, such as Dolby B for a dbx recording, which badly distorts level and frequency response.','Trying to decode before the machine is aligned for level and azimuth, so alignment errors compound the decoder''s errors.','Assuming an undocumented cassette is unencoded and transferring it flat when it was in fact Dolby-encoded.']::text[],ARRAY['Preparing a 1980s multitrack master that may be Dolby A or SR encoded for digitisation.','Transferring a domestic cassette with no visible Dolby marking.','Diagnosing a transfer that sounds dull and lifeless because noise reduction was left un-decoded.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='821abccc-fbe8-5c15-bc18-dccc24ad157b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noise-reduction identification'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '821abccc-fbe8-5c15-bc18-dccc24ad157b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='821abccc-fbe8-5c15-bc18-dccc24ad157b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ded2248-7640-5c3a-85fa-e6034329d3dd','Nominal tape speed','The standard, rated speed at which a magnetic tape was recorded or is designed to be replayed - one of the established values such as 30, 15, 7.5, 3.75, 1.875 or 15/16 inches per second - as distinct from the actual measured speed, which may differ owing to recorder tolerance, alignment, or power-supply variation. It is the reference speed named on the box or set by the format, used as the starting point for setting replay speed.','Tape machines run at set standard speeds, like seven and a half inches per second. The nominal speed is that named, standard value. But a machine may have run a little fast or slow. So the real speed can differ from the nominal one. Archivists check pitch and set the true speed for transfer.','It gives a common reference so tapes can be threaded and replayed at the intended speed, and comparing the nominal to the measured speed reveals recorder drift that must be corrected to keep pitch and duration right.','The technician selects the machine speed matching the tape''s nominal value, then confirms true pitch against a known reference tone or musical pitch and trims the replay speed if the original transport ran off-speed.','Tape Transfer',ARRAY['Nonlinear-speed recording','Noise-reduction identification','Azimuth alignment','Partial dropout','Flat transfer']::text[],ARRAY['Treating the nominal speed as the exact true speed, so recorder off-speed is carried into the transfer as wrong pitch.','Transferring a 7.5 ips tape at 15 ips, or the reverse, after mis-reading the box, doubling or halving pitch and duration.','Forgetting that some recordings change speed part-way through, so a single nominal speed does not apply.']::text[],ARRAY['Setting up a reel machine to replay a field recording labelled 7.5 ips.','Correcting the pitch of a tape recorded on a transport whose motor ran fast.','Choosing 1.875 ips for a standard compact cassette transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ded2248-7640-5c3a-85fa-e6034329d3dd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nominal tape speed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ded2248-7640-5c3a-85fa-e6034329d3dd','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
