INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17547511-549f-5598-9bf8-7f0dc23b5933','Non-RIAA equalization','Any disc replay equalisation curve other than the RIAA standard - chiefly the many pre-standardisation turnover and roll-off curves (such as Columbia, Decca/ffrr, EMI, HMV and Victor) applied to 78 rpm records and to early microgroove LPs before the RIAA curve was adopted in the mid-1950s. Reproducing such a disc faithfully requires applying the matching curve, or transferring flat and correcting in the digital domain.','Records are cut with the bass turned down and the treble up. On playback you reverse this with an equaliser curve. Modern records all share one curve, called RIAA. Older 78s and early LPs used many different curves instead. To play them right, use the correct old curve, or fix it later on the computer.','It restores the original tonal balance of records made before the RIAA curve became universal, since using the wrong curve leaves the transfer too bright, too dull, or bass-heavy.','A transfer engineer identifies the label and era, selects the matching turnover and roll-off, or makes a flat transfer and applies the curve in software, and documents the choice with the archival file.','Disc Transfer',ARRAY['Multi-stylus transfer','Flat transfer','Noncontact playback','Optical sound recovery','Best-copy selection']::text[],ARRAY['Playing every 78 through the RIAA phono curve, which was not standardised until the mid-1950s and does not fit earlier discs.','Guessing a curve without checking the label and era, producing a transfer with the wrong tonal balance.','Applying a replay curve during capture with no flat archival version, removing the option to re-correct later.']::text[],ARRAY['Transferring a 1930s Columbia 78 that needs its period turnover and roll-off.','Digitising an early-1950s LP cut before RIAA standardisation.','Making a flat preservation master and applying the curve only to the access copy.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17547511-549f-5598-9bf8-7f0dc23b5933' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Non-RIAA equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17547511-549f-5598-9bf8-7f0dc23b5933','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17547511-549f-5598-9bf8-7f0dc23b5933' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2326e336-75bc-5878-8d3b-30601e5d4da0','Noncontact playback','Reproduction of a grooved recording without a stylus physically riding in the groove, instead reading the groove''s shape optically or with a laser - for example the ELP Laser Turntable, or image-based systems such as IRENE and VisualAudio that photograph or scan the surface and reconstruct the audio computationally. It is used chiefly for broken, delaminating, or extremely fragile carriers, generally at lower fidelity than good mechanical playback but without adding physical wear.','Normally a needle sits in a record''s groove to play it. Noncontact playback reads the groove without touching it. It uses a laser or takes very detailed pictures of the surface. A computer then turns the groove shape into sound. This is used for broken or fragile records that a needle could destroy.','It lets sound be recovered from carriers too damaged, broken, or fragile to survive a stylus, and it avoids adding mechanical wear to rare originals.','For a cracked lacquer disc or a broken cylinder, an archive uses an optical system such as IRENE, which images the surface so the waveform can be rebuilt without a stylus.','Optical Transfer',ARRAY['Optical sound recovery','Multi-stylus transfer','Non-RIAA equalization','Best-copy selection']::text[],ARRAY['Assuming optical playback always beats a stylus, when on undamaged discs a well-set mechanical transfer usually sounds better.','Expecting it to hide dirt and mould automatically, when contamination still degrades the image and should be addressed first.','UNSAFE: Handling broken or mould-affected discs bare-handed; use gloves and respiratory protection to avoid cuts and spore inhalation.']::text[],ARRAY['Recovering audio from a lacquer disc broken into several pieces.','Playing a delaminating disc that a stylus would destroy.','Digitising a fragile wax cylinder without touching its surface.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2326e336-75bc-5878-8d3b-30601e5d4da0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noncontact playback'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2326e336-75bc-5878-8d3b-30601e5d4da0','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2326e336-75bc-5878-8d3b-30601e5d4da0' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2189946d-9b33-57d3-830b-265de5c8535d','Nonlinear-speed recording','A recording made on a transport lacking constant-speed (capstan-and-pinch-roller) control, so the carrier speed varied over the course of the recording rather than staying constant. Because the speed plotted against time is not linear, replaying the tape at a single fixed speed produces continuous pitch drift, and faithful transfer requires reproducing it with a matched, varying replay-speed curve.','Good tape machines pull the tape past the head at a steady speed. Some cheap or early machines did not. Their tape sped up and slowed down while recording. Played back at one steady speed, the pitch drifts up or down. To fix it, the replay speed must be varied to match the original.','Recognising a nonlinear-speed recording explains why its pitch wanders and tells the engineer that a varying, matched replay speed - not a single fixed speed - is needed to restore correct pitch.','Faced with a tape whose pitch sags toward the reel ends, the engineer uses a machine or software that can vary replay speed along a curve fitted to the original transport''s behaviour.','Tape Transfer',ARRAY['Nominal tape speed','Noise-reduction identification','Partial dropout','Flat transfer']::text[],ARRAY['Playing such a tape at one fixed speed and accepting the drifting pitch as if it were original.','Blaming pitch drift on a faulty replay machine rather than on the recording transport.','Assuming digital pitch-correction after a flat transfer is as good as matching the varying speed during capture.']::text[],ARRAY['Transferring a battery field-recorder tape whose motor slowed as the battery drained.','Restoring pitch on an early capstan-less reel recording.','Fitting a replay-speed curve on a suitable machine to track the original speed variation.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2189946d-9b33-57d3-830b-265de5c8535d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nonlinear-speed recording'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2189946d-9b33-57d3-830b-265de5c8535d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2189946d-9b33-57d3-830b-265de5c8535d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ec872ac-96f0-55c5-b73c-46c2b318267b','Optical sound recovery','The recovery of an audio signal by optically imaging a physical recording and reconstructing the waveform computationally, rather than tracing it with a stylus or a real-time photocell. In archival audio it covers image-based reading of grooved discs and cylinders (systems such as IRENE and VisualAudio) and, by extension, the rescue of degraded photographic (optical) film soundtracks, where the recorded modulation is measured from high-resolution images.','Some recordings store sound as a groove or a pattern of light and dark. Optical sound recovery takes very detailed pictures of that pattern. A computer measures the shapes and rebuilds the sound. Nothing has to touch or drag across the surface. This helps save recordings too damaged to play the normal way.','It extracts sound from carriers that cannot be safely or successfully played by conventional means, turning a measured image of the surface into an audio file.','An archive images a broken disc or a shrunken optical film track at high resolution and runs software that follows the modulation and outputs audio, often after cleaning up noise from dirt and damage in the image.','Optical Transfer',ARRAY['Noncontact playback','Multi-stylus transfer','Non-RIAA equalization','Best-copy selection']::text[],ARRAY['Believing optical recovery always yields higher quality, when for intact carriers a good stylus transfer is usually cleaner.','Skipping cleaning first, so dirt and damage in the image add noise the software must interpolate over.','Confusing the reconstructed, image-based method with real-time optical film reproduction through a photocell.']::text[],ARRAY['Rebuilding audio from a shattered lacquer disc by imaging its pieces.','Rescuing a warped or shrunken optical film soundtrack.','Reading a cylinder''s grooves from photographs instead of playing it with a stylus.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ec872ac-96f0-55c5-b73c-46c2b318267b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optical sound recovery'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ec872ac-96f0-55c5-b73c-46c2b318267b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ec872ac-96f0-55c5-b73c-46c2b318267b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5db113bd-2829-5b7d-8d30-5dd4c00a450c','Pack spill','A winding fault in which a reel of magnetic tape is wound loosely or unevenly so that the tape pack loses its firm, even shape and layers slip, telescope, or spill off the hub. A spilled or slack pack leaves the tape edges unsupported and exposed, inviting edge damage, creasing, and cinching, and it signals that the tape was not wound at a correct, even tension.','Tape should be wound onto a reel in a firm, even roll called the pack. If it is wound too loose or unevenly, the roll loses its shape. Layers then slide or spill off the reel. The loose edges get bent, creased, or crushed. That is why archivists wind tape smoothly at the right tension.','Spotting a spilled pack warns that a tape has been poorly wound and is at risk, prompting a careful, even library wind before storage or transfer to protect the edges and prevent creasing.','On finding a slack, spilling pack, the technician spools the tape slowly and evenly on a well-aligned machine to restore a firm, flat pack rather than fast-winding it or storing it loose.','Tape Defects',ARRAY['Partial dropout','Paper leader','Print-through','Nominal tape speed']::text[],ARRAY['Fast-winding a slack tape to tidy it, which stretches and creases the exposed edges.','Storing a reel with a spilling, slack pack so the unsupported edges get bent or crushed.','Assuming a poorly wound pack is harmless, when uneven tension leads to cinching and dropout.']::text[],ARRAY['Receiving an archival reel that has partly unspooled into a loose, spilling pack.','Preparing a slack tape for transfer by first winding an even, firm pack.','Inspecting stored reels for loose winding before long-term storage.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5db113bd-2829-5b7d-8d30-5dd4c00a450c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pack spill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5db113bd-2829-5b7d-8d30-5dd4c00a450c','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5db113bd-2829-5b7d-8d30-5dd4c00a450c' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '420a800c-bd29-5633-a9b3-8af9e55fd2c7','Paper leader','Non-magnetic leader made of paper rather than plastic (polyester) stock, spliced to the head, tail, or between sections of a tape. Common on early and consumer tapes, paper leader protects and identifies the recording and aids threading, but it is comparatively weak and often acidic, can shed fibres and dust onto the tape and heads, and its splices may dry out or bleed adhesive with age.','Leader is the blank strip joined to the ends of a tape. It protects the recording and helps you thread the machine. Some leader is made of paper instead of plastic. Paper leader is weaker and can turn acidic as it ages. It sheds bits of dust, and its splices can dry out or ooze glue.','As a leader it protects the recorded ends, marks or colour-codes sections, and gives something to thread, and knowing it is paper flags the added risks of acidity, shedding, and failing splices during handling.','When a technician finds brittle or shedding paper leader with a failing splice, they clean the residue and may replace the leader and re-splice before transfer to protect the tape and keep the heads clean.','Tape Handling',ARRAY['Pack spill','Partial dropout','Print-through','Nominal tape speed']::text[],ARRAY['Assuming all leader is inert plastic and ignoring that aged paper leader is acidic and abrasive.','Playing straight through shedding paper leader, depositing dust on the heads and guides.','Leaving a dried or bleeding paper-leader splice in place, letting adhesive migrate onto the recorded tape.']::text[],ARRAY['Threading an old domestic reel that begins with brittle paper leader.','Cleaning adhesive residue from a failed paper-leader splice before transfer.','Deciding whether to replace deteriorated paper leader on an archival tape.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='420a800c-bd29-5633-a9b3-8af9e55fd2c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Paper leader'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '420a800c-bd29-5633-a9b3-8af9e55fd2c7','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='420a800c-bd29-5633-a9b3-8af9e55fd2c7' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b76489a-bbb7-583b-81aa-c46d67ec2c21','Parallel transfer','A transfer approach in which several signals or carriers are digitised at the same time - for example capturing all tracks of a multitrack tape at once into one multichannel file, or running multiple playback and capture chains simultaneously - rather than transferring them one after another (serially). It is used to keep related channels synchronous in a single capture and, in mass-digitisation, to raise throughput.','You can transfer recordings one at a time, or several at once. Parallel transfer captures more than one at the same time. For example, all tracks of a multitrack tape go in together. Or several machines run at once into several recorders. Doing them together keeps linked tracks lined up and saves time.','It captures channels that belong together in one synchronous pass so they stay time-aligned, and it lets a lab digitise more material in the same period by running several chains at once.','In a busy digitisation lab an engineer may capture every track of a multitrack master simultaneously into one multichannel file, or run several monitored transfer stations at the same time.','Transfer Workflow',ARRAY['Nominal tape speed','Noise-reduction identification','Partial dropout','Best-copy selection']::text[],ARRAY['Running many streams at once with too few staff to monitor each, so a fault on one transfer goes unnoticed.','Assuming parallel capture removes the need to align and check every machine individually.','Capturing multitrack channels one at a time when they should be taken together to stay in sync.']::text[],ARRAY['Digitising a 24-track master by capturing all tracks simultaneously into one file.','Scaling up a mass-digitisation project by running several monitored transfer stations at once.','Keeping a stereo pair or its timecode track synchronous by capturing them together.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b76489a-bbb7-583b-81aa-c46d67ec2c21' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parallel transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b76489a-bbb7-583b-81aa-c46d67ec2c21','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b76489a-bbb7-583b-81aa-c46d67ec2c21' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d1b198e-4078-5444-a1e9-570ae7b2862d','Partial dropout','A dropout that only partly reduces the reproduced signal - attenuating it or losing mainly the higher frequencies - rather than muting it completely, caused by a momentary increase in head-to-tape spacing from oxide shedding, debris, creases, or coating defects. Because magnetic spacing loss rises with frequency, a small separation dulls and weakens the signal (a partial dropout) while a larger one cuts it out entirely.','A dropout is a brief loss of sound on tape. It happens when the tape lifts slightly off the play head. A tiny gap does not kill the sound completely. Instead that moment goes quieter and duller, losing the highs first. That smaller, partial loss is a partial dropout.','Recognising a dropout as partial rather than total tells the engineer it comes from slight loss of head contact and can often be eased by cleaning and better handling, rather than being a permanent gap.','Hearing brief dulling or level dips, the technician cleans the tape and tape path, improves contact and tension, and re-transfers, then may smooth any residual partial dropouts with restoration software.','Tape Defects',ARRAY['Pack spill','Paper leader','Print-through','Nominal tape speed']::text[],ARRAY['Confusing a partial dropout with a deliberate level change or a bad edit.','Assuming every dropout is permanent oxide loss, when many partial ones clear after cleaning the tape and path.','Boosting high frequencies to mask a partial dropout, which just raises noise instead of restoring head contact.']::text[],ARRAY['Hearing brief high-frequency dulling on an old, shedding tape.','Cleaning the tape path to cure intermittent level dips before transfer.','Using restoration software to smooth residual partial dropouts after capture.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d1b198e-4078-5444-a1e9-570ae7b2862d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Partial dropout'),'[^a-z0-9]','','g'));
