INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ea97f4f-997a-55a8-a11b-7a87a730a362','Patch-source restoration','A restoration technique in which a damaged, missing, or unrepairable passage of a recording is repaired by substituting equivalent audio patched in from a clean source, either a nearby undamaged region of the same recording or a parallel copy, take, or transfer of the same content.','This means fixing a broken spot in a recording by pasting in good audio from somewhere else. The patch can come from another copy or from a clean part nearby.','It repairs localized damage that cannot be cleaned in place, restoring musical or spoken continuity while leaving the surrounding original audio untouched.','An engineer selects a clean matching passage from a duplicate tape or an earlier bar of the same take and crossfades or splices it over a dropout, tear, or unrepairable click.','Restoration Technique',ARRAY['Spectral repair','Dropout','Razor edit','Crossfade','Preservation master']::text[],ARRAY['Choosing a patch source that differs in pitch, level, or tonal balance, so the repair is audible.','Failing to match ambience and noise floor between the patch and the surrounding audio.','Editing the preservation master itself instead of a copy, so the original evidence is lost.']::text[],ARRAY['Filling a tape dropout by copying the same phrase from a second surviving reel.','Replacing a torn, unrepairable section using the matching passage from an alternate broadcast dub.','Patching a burst of unrepairable clicks with a clean identical passage from another source copy.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ea97f4f-997a-55a8-a11b-7a87a730a362' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Patch-source restoration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ea97f4f-997a-55a8-a11b-7a87a730a362','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ea97f4f-997a-55a8-a11b-7a87a730a362' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b0938937-20c8-5a28-804d-91017160b6cf','Peak weighted wow and flutter','A measure of a recorder or reproducer''s short-term speed instability in which the frequency modulation of a standard 3.15 kHz reference tone is passed through the standardized flutter weighting network (peaking near 4 Hz) and read on a quasi-peak detector, expressed as a weighted-peak percentage per IEC 60386, DIN 45507, and AES6.','This is a way to measure how much a tape machine''s speed wobbles. A steady test tone is recorded, and a meter reads the worst wobble the ear notices most. It reports that biggest weighted swing as a percent.','It quantifies audible speed error using a hearing-based weighting and a peak-holding meter, so brief pitch excursions that listeners notice are not hidden by simple averaging.','A technician plays a standard 3.15 kHz test tone, reads the weighted-peak value on a flutter meter, and compares it against the machine''s specification before an archival transfer.','Measurement & Metrology',ARRAY['Quasi-peak wow and flutter','Wow','Flutter','Pinch-roller-rate component','Scrape flutter']::text[],ARRAY['Comparing a weighted-peak figure against an unweighted or RMS figure, which are not equivalent.','Blaming the machine when a warped or off-center test tape is causing the reading.','Forgetting that a weighted-peak reading is normally higher than the RMS value for the same machine.']::text[],ARRAY['Qualifying a reel-to-reel deck before transferring an irreplaceable master.','Diagnosing audible pitch waver on a restored piano recording.','Documenting transport performance in a preservation transfer report.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b0938937-20c8-5a28-804d-91017160b6cf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Peak weighted wow and flutter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b0938937-20c8-5a28-804d-91017160b6cf','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b0938937-20c8-5a28-804d-91017160b6cf' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '839b80a8-31d2-5983-8130-e9ad2842601d','Phase-coherent summation','The addition of two or more time-aligned signals so that their correlated, in-phase content adds constructively while uncorrelated content does not; correlated signal rises about 6 dB on doubling and uncorrelated noise about 3 dB, yielding the signal-to-noise gain exploited in coherent averaging of repeated transfers.','This means lining up two copies of the same sound and adding them together. The matching music adds up strongly, while the random hiss adds up far less. So the music stands out more clearly above the hiss.','By reinforcing shared signal and partly averaging out random noise, it recovers a cleaner result from several noisy passes or copies of the same source.','An engineer makes several aligned playbacks of a noisy or damaged recording, time-syncs them precisely, and sums them to lift the wanted signal above the noise floor.','Signal Processing',ARRAY['Phase','Signal averaging','Signal-to-noise ratio','Comb filtering','Azimuth']::text[],ARRAY['Summing sources that are not precisely time-aligned, which causes comb filtering and hollow tone.','Assuming noise cancels completely; only uncorrelated noise partly averages down, it does not vanish.','Combining sources with opposite polarity, so the wanted signal cancels instead of adding.']::text[],ARRAY['Averaging several aligned transfers of a hissy tape to raise the signal-to-noise ratio.','Combining two stylus passes of a damaged disc groove wall to reduce noise.','Summing correlated feeds where phase alignment determines the combined result.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='839b80a8-31d2-5983-8130-e9ad2842601d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phase-coherent summation'),'[^a-z0-9]','','g'));
