WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='839b80a8-31d2-5983-8130-e9ad2842601d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '651442ee-7575-5d4e-8cb6-bb8fe4d974ae','Pilot-tone leakage','The unwanted appearance of the synchronizing pilot tone, a reference tone (typically 50 Hz or 60 Hz) recorded on location for film or tape sync and often carried as a center-track push-pull (neopilot) signal designed to cancel at the audio head, within the reproduced program audio, heard as low-frequency hum when that cancellation is imperfect.','Some field recordings carry a hidden timing tone, usually a 50 or 60 hertz hum, used to match sound to film. Pilot-tone leakage is that timing tone bleeding into the audio, where you hear it as a low hum.','As a named defect it flags residual sync-tone contamination, guiding the engineer to notch or filter a tone that was never meant to be heard in the program.','During transfer of a synchronized field recording, the engineer spots a steady 50 Hz or 60 Hz component tied to the pilot track and removes it with a narrow notch or high-pass filter.','Signal Defects',ARRAY['Pilot tone','Hum','Notch filter','Crosstalk','Neopilot']::text[],ARRAY['Confusing pilot-tone leakage with ordinary mains hum introduced by the transfer chain.','Notching 50 Hz when the tone is actually 60 Hz, or the reverse, leaving the hum in place.','Applying a heavy low-cut that removes wanted bass along with the pilot tone.']::text[],ARRAY['Transferring a quarter-inch location dialogue reel recorded with camera sync.','Cleaning a documentary field recording where a low hum tracks the sync tone.','Assessing a neopilot master for center-track tone bleeding into the audio.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='651442ee-7575-5d4e-8cb6-bb8fe4d974ae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pilot-tone leakage'),'[^a-z0-9]','','g'));
