INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9cb319c2-7a78-504f-97df-0cb363208e31','Pinch-roller-rate component','A discrete speed-fluctuation (flutter) component in a tape transport occurring at the rotational frequency of the pinch (capstan pressure) roller, or its harmonics, caused by roller eccentricity, wear, flats, or contamination and appearing as a periodic peak in the flutter spectrum.','The pinch roller is a rubber wheel that presses the tape onto the drive shaft. If it is worn or not perfectly round, it makes the speed wobble once each turn. That regular wobble is the pinch-roller-rate component.','Identifying flutter at the roller''s turning rate points diagnosis straight to the pinch roller, so the correct part is cleaned or replaced rather than guessed at.','A technician runs a flutter analysis, finds a spectral peak matching the pinch-roller circumference and tape speed, and cleans or replaces the roller to cure the periodic waver.','Transport Artifacts',ARRAY['Pinch roller','Capstan','Flutter','Scrape flutter','Peak weighted wow and flutter']::text[],ARRAY['Assuming any periodic flutter is capstan-related without checking the roller''s own rotation rate.','Cleaning the capstan but ignoring a glazed or flat-spotted pinch roller.','Confusing a once-per-revolution roller component with random scrape flutter.']::text[],ARRAY['Diagnosing a slow, once-per-turn pitch waver on a transferred tape.','Analyzing a flutter spectrum during transport alignment.','Deciding whether to replace a hardened pinch roller before an archival transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9cb319c2-7a78-504f-97df-0cb363208e31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pinch-roller-rate component'),'[^a-z0-9]','','g'));
