WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9cb319c2-7a78-504f-97df-0cb363208e31' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '981189f9-fa80-5582-ab70-d28fb68639e4','Plastic leader','Non-magnetic leader tape made of plastic film (commonly polyester), spliced to the head, tail, and between sections of a recording tape to protect the ends, aid threading, and provide colored cueing or timing, as distinct from paper leader.','Leader tape is blank tape with no recording on it. It is spliced to the start and end of a reel to protect it and help thread the machine. Plastic leader is the kind made of plastic film instead of paper.','It shields the recorded oxide ends from handling damage, marks sections for cueing, and gives a strong, threadable start and finish to a reel.','When preparing a reel for transfer, an archivist splices fresh leader to the ends and may use colored plastic leader to mark cues, timing gaps, or the head and tail.','Tape Media',ARRAY['Leader tape','Splicing tape','Razor edit','Paper leader','Reel-to-reel']::text[],ARRAY['Assuming plastic leader can be recorded on; it carries no magnetic coating.','Ignoring static charge on plastic leader, which attracts dust onto nearby oxide.','Splicing leader with the wrong or aged adhesive tape, causing bleed onto the recording.']::text[],ARRAY['Re-leadering a fragile archival reel before playback.','Using colored leader to separate and time individual songs on a master.','Replacing brittle original leader that could snag the transport.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='981189f9-fa80-5582-ab70-d28fb68639e4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plastic leader'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '981189f9-fa80-5582-ab70-d28fb68639e4','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
