INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ccf27b4-909c-5b4a-b909-a3574aaac932','Post-transfer equalization','Equalization applied after a recording has been captured to a file, in the digital domain, as an access- or restoration-stage tonal correction, kept separate from and additional to the replay (reproduce) equalization used during capture, and normally applied only to derivative copies rather than to the preservation master.','This is tone shaping done after the recording has already been copied into the computer. It is used to fix or improve the sound for listening copies. The safe, untouched original file is left alone.','It lets engineers correct tonal problems non-destructively while preserving an unaltered master, because the original transfer stays untouched and every change stays reversible.','After making a flat or replay-equalized preservation transfer, the engineer opens a copy and applies corrective equalization there to produce a listenable access version.','Transfer Workflow',ARRAY['Replay equalization','Pre-equalized transfer','Preservation master','Access copy','Flat transfer']::text[],ARRAY['Confusing corrective post-transfer equalization with the mandatory replay curve applied during capture.','Baking tonal changes into the preservation master instead of a derivative copy.','Over-equalizing to modern taste and erasing the original recording''s character.']::text[],ARRAY['Producing a brightened access copy from a dull-sounding archival transfer.','Correcting tonal balance for a reissue while keeping the flat master intact.','Applying gentle equalization to a speech recording to improve intelligibility.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ccf27b4-909c-5b4a-b909-a3574aaac932' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-transfer equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2ccf27b4-909c-5b4a-b909-a3574aaac932','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2ccf27b4-909c-5b4a-b909-a3574aaac932' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '547cea17-84f3-5a0e-ba76-4c1dd5dd7af9','Pre-equalized transfer','A transfer in which equalization, typically the standard reproduce (replay) curve and sometimes additional corrective shaping, is applied to the signal at the point of capture, so the resulting file is already equalized, in contrast to a flat transfer that defers or omits such shaping.','This is a copy made with the tone correction already applied as it is recorded into the computer. The finished file is not flat; the equalization is built in. That choice cannot be fully undone later.','Applying the correct replay curve at capture yields a file that already sounds tonally right, but baking equalization in reduces later flexibility for a preservation master.','An engineer sets the deck or interface to the correct replay curve for the tape''s standard and records the already-equalized signal for immediate use.','Transfer Workflow',ARRAY['Replay equalization','Post-transfer equalization','Flat transfer','Preservation master','NAB equalization']::text[],ARRAY['Using the wrong replay curve for the tape''s standard, so the whole transfer is tonally skewed.','Baking corrective equalization into a preservation master, which should stay minimally processed.','Assuming that equalization built in at capture can be perfectly reversed later.']::text[],ARRAY['Capturing a tape through the deck''s standard replay curve for immediate use.','Making a quick equalized listening copy when a flat master is not required.','Debating whether to defer equalization to a post-transfer stage for the archival master.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='547cea17-84f3-5a0e-ba76-4c1dd5dd7af9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-equalized transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
