INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1612ed7d-2981-508d-a9ee-4c30412fdc85','Pressure pad','A small resilient pad, usually felt on a leaf spring, that presses the tape against the record/reproduce head to maintain intimate head-to-tape contact, used chiefly in compact cassettes, tape cartridges, and some consumer machines; professional open-reel transports instead rely on controlled tape tension for contact.','A pressure pad is a little felt cushion that pushes the tape against the playback head. Good contact means good sound, especially the high notes. Cassettes use one; big studio reel machines do not.','It keeps the tape firmly on the head so the magnetic signal transfers fully, preventing the level and high-frequency losses that come from any gap.','When a cassette plays dull or drops level, a technician checks the pressure pad for wear, hardening, or a weak spring and replaces the pad if contact is poor.','Tape Transport',ARRAY['Pressure-pad loss','Pressure-pad glazing','Head-to-tape contact','Spacing loss','Compact cassette']::text[],ARRAY['Assuming professional open-reel decks use pressure pads; they rely on tape tension.','Ignoring a hardened or missing pad as a cause of dull, weak playback.','UNSAFE: cleaning heads or pads with solvents in a poorly ventilated space or near heat or flame, ignoring the product''s safety data sheet.']::text[],ARRAY['Servicing a cassette deck that plays with muffled treble.','Assessing a cartridge tape''s pad before an archival transfer.','Explaining why a studio reel machine has no pressure pad.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1612ed7d-2981-508d-a9ee-4c30412fdc85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pressure pad'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1612ed7d-2981-508d-a9ee-4c30412fdc85','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1612ed7d-2981-508d-a9ee-4c30412fdc85' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd8ef51c5-6e4c-53ca-a902-1a9f3962fa2a','Pressure-pad glazing','A degradation in which a felt pressure pad''s surface becomes hardened, smoothed, and glossy from wear, heat, and accumulated binder and oxide deposits, reducing its compliance and its ability to hold the tape against the head, which causes high-frequency loss, level fluctuation, and modulation noise.','Over time a felt pressure pad can go hard and shiny, like a worn-smooth eraser. A glazed pad cannot press the tape evenly onto the head. The sound then loses treble and wavers in level.','Naming this specific wear pattern tells a technician the pad, not the head or tape, is at fault, so the pad is replaced to restore contact.','Inspecting a dull, noisy cassette, a technician sees the shiny hardened pad surface and swaps in a new compliant pad to recover treble and steady level.','Tape Transport',ARRAY['Pressure pad','Pressure-pad loss','Head-to-tape contact','Spacing loss','Dropout']::text[],ARRAY['Cleaning a glazed pad and expecting recovery when the felt itself is hardened and must be replaced.','Mistaking pad glazing for head wear or a faulty tape.','Ignoring glazing until it causes audible treble loss on an irreplaceable tape.']::text[],ARRAY['Diagnosing progressive treble loss on a long-stored cassette.','Refurbishing a cartridge machine''s pads before transfer.','Explaining wavering level traced to a hardened pad.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d8ef51c5-6e4c-53ca-a902-1a9f3962fa2a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pressure-pad glazing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd8ef51c5-6e4c-53ca-a902-1a9f3962fa2a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d8ef51c5-6e4c-53ca-a902-1a9f3962fa2a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '532e01b5-bbc6-5b71-a84f-7f66bf425163','Pressure-pad loss','The loss of signal, chiefly high frequencies (a form of spacing loss) and level, that results when a pressure pad fails to hold the tape in intimate contact with the head, due to pad wear, glazing, hardening, contamination, or weak spring pressure.','This is the sound you lose when the pressure pad stops pushing the tape tight to the head. Even a tiny gap steals the high notes and lowers the level. Worn or hard pads are the usual cause.','The term isolates head-contact failure at the pad as the cause of dulled, weakened playback, directing repair to the pad rather than the electronics.','Facing a cassette that plays dull and low, a technician confirms pressure-pad loss by improving pad contact and hearing the treble and level return.','Tape Transport',ARRAY['Pressure pad','Pressure-pad glazing','Spacing loss','Head-to-tape contact','High-frequency loss']::text[],ARRAY['Blaming worn heads or a faulty tape when the pad is the real cause.','Assuming lost treble is always electronic rather than a contact problem.','Overlooking that even a small pad-to-tape gap causes large high-frequency loss.']::text[],ARRAY['Restoring treble on a cassette with a tired pressure pad.','Comparing playback before and after improving pad contact.','Deciding to service the pad before transferring a rare cassette.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='532e01b5-bbc6-5b71-a84f-7f66bf425163' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pressure-pad loss'),'[^a-z0-9]','','g'));
