INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ddd6ce4e-fde8-5f47-8cc7-1e6e8dadb52f','Quasi-peak wow and flutter','Wow and flutter measured with the standardized quasi-peak detector specified in IEC 60386, DIN 45507, and AES6, a rectifier with defined fast-attack, slow-decay ballistics following the 4 Hz flutter weighting network, so that brief speed excursions are captured with a reading that falls between true peak and RMS.','This is a way to read a tape machine''s speed wobble with a special meter. The meter jumps up fast on a wobble and falls back slowly. That makes short wobbles show up, close to how the ear notices them.','The quasi-peak detector''s ballistics make the reading track the audibility of short speed excursions, giving a repeatable, standards-based figure that plain averaging would understate.','Using a standards-compliant flutter meter set to quasi-peak, a technician reads a repeatable weighted value from a 3.15 kHz test tone to qualify a transport.','Measurement & Metrology',ARRAY['Peak weighted wow and flutter','Wow','Flutter','Weighting filter','Pinch-roller-rate component']::text[],ARRAY['Treating quasi-peak and RMS wow-and-flutter figures as interchangeable numbers.','Ignoring which standard and detector a quoted specification uses when comparing machines.','Assuming a low RMS figure means brief excursions are also low.']::text[],ARRAY['Reading a repeatable flutter value during transport alignment.','Comparing a deck''s measured figure against its quasi-peak specification.','Documenting speed stability in a preservation transfer report.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ddd6ce4e-fde8-5f47-8cc7-1e6e8dadb52f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Quasi-peak wow and flutter'),'[^a-z0-9]','','g'));
