INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e37b88e3-efbf-5765-a00d-2a566afa3082','Radio breakthrough','The intrusion of a radio-frequency broadcast into an audio signal, where a strong RF field (for example an AM transmitter) is rectified by nonlinearities at cable junctions, connectors, or semiconductor inputs and demodulated into audible program, appearing as speech or music bleeding into the recording or transfer chain.','This is when a radio station leaks into your audio. A strong radio signal gets picked up by cables and turned back into sound. You then hear faint talk or music mixed into the recording.','Naming this interference tells the engineer the fault is picked-up radio energy, pointing to shielding, grounding, and filtering rather than to the source recording.','Hearing faint broadcast audio in a transfer, a technician improves cable shielding and grounding, shortens or reroutes leads, and fits radio-frequency filtering to suppress it.','Interference',ARRAY['Ground loop','Hum','Shielding','Balanced connection','Crosstalk']::text[],ARRAY['Assuming faint voices are on the tape when they are radio picked up in the signal chain.','Using long unbalanced cables that act as antennas near transmitters.','UNSAFE: defeating a mains earth or ground connection to chase interference, which removes vital shock protection required by wiring and workplace safety codes.']::text[],ARRAY['Removing a nearby AM station bleeding into a studio transfer.','Tracing broadcast pickup on long microphone or line runs.','Assessing whether faint speech is on the original tape or added by the chain.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e37b88e3-efbf-5765-a00d-2a566afa3082' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Radio breakthrough'),'[^a-z0-9]','','g'));
