INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6bb87a47-6ff3-5200-9a8e-37dadc8a93a6','Razor edit','A physical edit of magnetic tape made by cutting the tape with a razor blade in a splicing block, typically on a diagonal such as 45 degrees to smooth the transition, and joining the ends with non-magnetic splicing tape, used historically to assemble, correct, or shorten recordings before digital editing.','This is editing tape with a razor blade instead of a computer. You cut the tape in a little guide block, then join the ends with special sticky tape. The cut is angled so the join sounds smooth.','It let engineers assemble takes, remove mistakes, and time recordings before digital editing existed, and such original splices are now part of an artifact''s history.','When transferring an edited master, an archivist inspects each razor splice, re-secures failing ones with fresh splicing tape, and documents original edits rather than silently removing them.','Tape Editing',ARRAY['Splicing tape','Splicing block','Plastic leader','Crossfade','Patch-source restoration']::text[],ARRAY['Cutting straight across instead of at an angle, causing an audible click at the join.','Using ordinary pressure-sensitive tape whose adhesive bleeds and contaminates the heads.','UNSAFE: careless handling of razor blades, which cause serious cuts; use a proper splicing block and a guarded blade.']::text[],ARRAY['Repairing a failed original splice on an archival master.','Assembling final program order on quarter-inch tape before digital tools.','Documenting historic edits during a preservation transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6bb87a47-6ff3-5200-9a8e-37dadc8a93a6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Razor edit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6bb87a47-6ff3-5200-9a8e-37dadc8a93a6','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6bb87a47-6ff3-5200-9a8e-37dadc8a93a6' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7fdc42c-e8e9-5f9d-a53a-43d3327118b6','Rectifier buzz','An electrical interference artefact heard as a harsh, harmonically rich buzz centred on the AC mains frequency (50 or 60 Hz) and its harmonics. It arises because rectifier diodes in a power supply conduct only near the AC voltage peaks and therefore draw current in short pulses, imposing a harmonic-rich ripple on the supply that couples into the audio path through power or ground connections.','This is a harsh electrical hum with a buzzy edge. It comes from the power supply, the part that turns wall power into the low voltage gear runs on. That part only draws power in short bursts, near each peak of the wall voltage. Those bursts add many extra tones on top of the basic hum.','Naming this artefact lets a restorer separate a buzz packed with harmonics from a smooth single-tone hum, because the two need different fixes. A rich buzz calls for a harmonic comb rather than a single notch.','During transfer or cleanup a technician spots rectifier buzz on a spectrogram as evenly spaced harmonic lines above the mains fundamental, then removes it with a hum-removal tool that targets the fundamental plus its harmonics, or cures the offending power or ground path at source.','Electrical Noise',ARRAY['Hum removal','Ground loop','Harmonic distortion','Notch filter','Replay characteristic']::text[],ARRAY['Assuming a single notch at 50 or 60 Hz removes it, when most of the buzz energy lives in the harmonics above the fundamental.','Confusing rectifier buzz with tape hiss or dropout and reaching for the wrong tool.','UNSAFE: Curing buzz by lifting the mains earth/ground pin on equipment to break a ground loop, which defeats protective earthing and creates a shock hazard.']::text[],ARRAY['Digitising an archival tape recorded through a poorly grounded studio power supply.','Cleaning up a location recording contaminated by nearby light dimmers.','Auditing a spectrogram before transfer to plan hum and buzz removal.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7fdc42c-e8e9-5f9d-a53a-43d3327118b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rectifier buzz'),'[^a-z0-9]','','g'));
