INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5c925503-fb59-5ca0-ba7e-f22e4bb65d9b','Reel-rate component','A component of a tape machine''s wow-and-flutter whose modulation frequency corresponds to the rotational rate of a reel, spool or hub (once per revolution). It is typically a low-frequency wow contribution caused by reel eccentricity, a bent hub or an uneven pack, and its frequency changes as the winding radius changes during play.','This is a slow rise and fall in pitch. It repeats once for every turn of a tape reel. A bent or off-centre reel makes the tape speed up and slow down each spin. The wobble gets faster as the reel empties.','Identifying a speed error by its reel-rate timing lets a technician trace the fault to a specific rotating part rather than blaming the capstan or the recording itself.','When a transfer sounds wowy, the technician measures the flutter and checks whether the wobble period matches one reel revolution, pointing to a warped reel or hub that should be swapped before continuing.','Speed & Flutter',ARRAY['Wow and flutter','Scrape flutter','Capstan','Replay characteristic','Reel']::text[],ARRAY['Treating all speed wobble as capstan flutter and ignoring a warped or eccentric reel.','Trying to fix reel-rate wow only in software afterwards, when swapping the deformed reel before transfer gives a far better result.','UNSAFE: Fast-winding on a visibly deformed reel, which can snag, stretch or snap fragile archival tape.']::text[],ARRAY['Diagnosing a periodic pitch wobble during an open-reel transfer.','Deciding whether to move a tape onto a known-good reel before digitising.','Analysing wow-and-flutter measurements to separate reel-rate from capstan-rate errors.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5c925503-fb59-5ca0-ba7e-f22e4bb65d9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel-rate component'),'[^a-z0-9]','','g'));
