INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1ac2e7c4-e1a8-543e-a909-08d75d63791f','Reference transfer','A transfer in which the replay chain is calibrated and verified against known reference signals, the tape''s recorded line-up/alignment tones and/or a standard reference (test) tape, so that reproduced level, speed and frequency response are set to a documented, objective baseline rather than by ear alone.','This is a transfer where the machine is set up against known test tones first. Those tones act like a ruler. They prove the playback level and tone are correct. The exact settings are written down so the work can be checked or repeated.','It exists so a digitised copy is trustworthy and repeatable: the reference tones prove the replay settings were right, which matters for level, equalisation and noise-reduction decoding.','Before digitising, the technician plays the head line-up tones or a test tape, adjusts replay level and equalisation to the documented values, and logs them so later users can trust the transfer.','Transfer Workflow',ARRAY['Replay characteristic','Line-up tones','Azimuth','Test tape','Best copy selection']::text[],ARRAY['Setting replay level and equalisation by ear when documented reference tones are present on the tape.','Failing to record the calibration values, so the transfer cannot be verified or reproduced later.','Assuming line-up tones are always at standard level without checking the tape''s own documentation.']::text[],ARRAY['Calibrating a reel machine to a tape''s head tones before a preservation transfer.','Using a standard test tape to align a deck at the start of a digitising session.','Documenting replay settings so an archive can audit a transfer years later.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1ac2e7c4-e1a8-543e-a909-08d75d63791f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference transfer'),'[^a-z0-9]','','g'));
