INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0ad52284-c202-5948-ab49-3bdd3d40e18a','Rehousing for equalization','The archival practice of transferring a cassette tape into a different shell so that an auto-sensing replay deck applies the correct replay equalisation. Because most decks select equalisation by reading the notches on the shell, a Type III (ferrichrome) tape housed in a Type-I-style shell is mis-equalised; rehousing it into a Type II shell makes the deck select the required Type II curve.','Cassette decks pick the right playback setting by feeling notches cut into the case. Some tapes sit in a case with the wrong notches. So the deck uses the wrong setting. Moving the tape into a case with the correct notches fixes the sound.','It exists so a tape receives the equalisation it was recorded for on ordinary auto-sensing decks, without needing a rare machine that has a manual equalisation switch.','Facing a ferrichrome (Type III) cassette that plays dull on an auto-sensing deck, the technician carefully moves the tape pack, rollers, pressure pad and liner sheets into a quality Type II screw shell so the deck applies the correct curve.','Carrier Rehousing',ARRAY['Replay characteristic','Shell azimuth','Slip sheet','Cassette shell','Pressure pad']::text[],ARRAY['Forgetting to transfer the rollers, pressure pad and liner (slip) sheets, causing jams or wow and flutter after reassembly.','Assuming every dull cassette needs rehousing, when a deck with a manual equalisation switch may solve it without opening the shell.','Handling the exposed tape pack roughly during the swap, creasing or contaminating the tape.']::text[],ARRAY['Preparing a Type III ferrichrome cassette for transfer on a deck that only auto-senses equalisation.','Moving a tape out of a jamming low-cost welded shell into a screwed shell.','Recovering correct high-frequency response from a cassette that plays muffled.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0ad52284-c202-5948-ab49-3bdd3d40e18a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rehousing for equalization'),'[^a-z0-9]','','g'));
